insert into private.study_guides (guide, chunks, sha256) values ('study_guide_lag_bua123', 39, '9c3dbc9f2c2f41a4308cd45439e9875f32e1e31749bb3e0f321a9785e82ddd52');
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 1, $study_guide${"guide":"study_guide_lag_bua123","code":"LAG-BUA123","courseId":"ced55987-74eb-5998-929a-c1d5275c5a3b","actor":"00000000-0000-4000-8000-000000000045","overview":{"itemId":"9c10f95a-f53c-5ca4-b00c-223a3ba09197","create":true,"after":{"title":"Marketing Communication","body":"Every topic is examinable.","outcomes":["Identify and evaluate marketing communication techniques, and the principles and theories behind each.","Explain the marketing communication process and its models.","Plan marketing communications and choose the right mix of advertising, sales promotion, public relations, personal selling and digital tools.","Explain the role of the source, message, receiver, medium and opinion leaders.","Explain the forms of business communication and the communication process.","Explain the place of social media, word-of-mouth and digital marketing in modern marketing communication.","Apply marketing communication concepts, principles and theories to solve marketing communication problems."],"assessment":["Assignments: 10%. Mid-term test: 20%. End-of-semester examination: 70%.","The exam is objective (CBT), with some theory questions. Expect definitions, lists, counts, models, authors and short applications to Nigerian businesses."]}},"retire":[],"notes":[{"kind":"note","itemId":"7f7f8f99-5465-5156-b798-a4be79cffdc6","sourceKey":"guide-topic:1","position":1,"payload":{"title":"Nature, Types, Roles and Objectives of Marketing Communication","body":"Definitions of marketing, communication and marketing communication; the four types of communication; the Seven Ps; how marketing communication emerged and gave rise to IMC; the conditions for exchange and the stages of the marketing communications process; the roles (including DRIP) and objectives of marketing communication.","noteType":"guide_topic","number":1,"mustKnow":[{"text":"Definitions of marketing, communication and marketing communication; the four types of communication; the Seven Ps; how marketing communication emerged and gave rise to IMC; the conditions for exchange and the stages of the marketing communications process; the roles (including DRIP) and objectives of marketing communication."}],"lessons":[{"number":"1.1","title":"Marketing, communication and marketing communication","mustKnow":[{"type":"paragraph","text":[{"text":"Marketing communication is made of two key words: "},{"text":"marketing","bold":true},{"text":" and "},{"text":"communication","bold":true},{"text":"."}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing (simple definition):","bold":true},{"text":" the establishment of mutually satisfying exchange relationships through the buying and selling of goods, services or ideas."}]},{"text":[{"text":"Baker (2000):","bold":true},{"text":" marketing is a way of managing profitable customer relationships."}]},{"text":[{"text":"Kotler and Armstrong (2006):","bold":true},{"text":" the process through which companies create value for customers and build strong customer relationships in order to capture value from customers in return (also worded \"to generate value in return\")."}]},{"text":[{"text":"Strydom, Jooste and Cant (2000):","bold":true},{"text":" the process of planning and executing the conception, pricing, marketing communication and distribution of ideas, products and services to create exchanges that satisfy individual and corporate goals."}]},{"text":[{"text":"Stapleton and Ali (2007): 4 commonalities","bold":true},{"text":" shared by these definitions:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"a focus on "},{"text":"customers","bold":true},{"text":";"}]},{"text":[{"text":"the provision of "},{"text":"suitable offerings","bold":true},{"text":" (goods, services or ideas) to meet customers' needs;"}]},{"text":[{"text":"suitable benefits to the organisation","bold":true},{"text":";"}]},{"text":[{"text":"the "},{"text":"relationship between the customer and the organisation","bold":true},{"text":", on the basis of which value can be created."}]}]}]},{"text":[{"text":"Communication (1):","bold":true},{"text":" the exchange of thoughts or conversations through written words, verbal conversation, electronic or digital media and social media platforms, to exchange ideas and information for a pre-planned purpose."}]},{"text":[{"text":"Communication (2):","bold":true},{"text":" the process of using "},{"text":"words, sounds or visual cues","bold":true},{"text":" to supply information to one or more people."}]},{"text":[{"text":"Marketing communications (MarCom):","bold":true},{"text":" the "},{"text":"channels and tools","bold":true},{"text":" companies use to communicate the necessary message to the target group. MarCom helps customers understand a company and its products. By conveying messages of significant value, it encourages audiences to give "},{"text":"positive attitudinal and behavioural responses","bold":true},{"text":"."}]},{"text":[{"text":"There is "},{"text":"no universal definition","bold":true},{"text":" of marketing communications, so there are many interpretations. "},{"text":"5 common definitions:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A "},{"text":"continuous interaction between buyers and sellers","bold":true},{"text":" in a marketplace."}]},{"text":[{"text":"The means companies adopt to convey messages about their products and brands, "},{"text":"directly or indirectly","bold":true},{"text":", to customers with the intention to "},{"text":"persuade them to purchase","bold":true},{"text":"."}]},{"text":[{"text":"The process of "},{"text":"creating and delivering messages that promote the interests of an organisation","bold":true},{"text":"."}]},{"text":[{"text":"The use of different marketing strategies and tools to "},{"text":"connect with a target audience","bold":true},{"text":"."}]},{"text":[{"text":"At its core, the "},{"text":"integration of all promotional tools and sources","bold":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 2, $study_guide$true},{"text":" within a company to "},{"text":"maximise the impact on consumers and other end-users at minimal cost","bold":true},{"text":"."}]}]}]},{"text":[{"text":"3 questions","bold":true},{"text":" marketing communication answers:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Who is the customer?"}]},{"text":[{"text":"What is being exchanged?"}]},{"text":[{"text":"What internal and external influences affect the exchange?"}]}]}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A fuller, modern definition you should recognise: marketing communication is a "},{"text":"strategic process of creating, delivering and exchanging value-laden messages to shape customer perceptions and behaviours","bold":true},{"text":". Any option that calls it \"one-way\", \"price announcement only\", \"physical movement of goods\" or \"manufacturing\" is wrong."}]},{"text":[{"text":"Trap: the \"planning and executing the conception, pricing ... distribution\" wording is "},{"text":"Strydom, Jooste and Cant","bold":true},{"text":", "},{"text":"not","bold":true},{"text":" Baker."}]},{"text":[{"text":"Stapleton and Ali's commonalities never include cutting staff or costs."}]},{"text":[{"text":"All organisations","bold":true},{"text":" (commercial, government, charities, educational, not-for-profit, of any size) need to communicate with a range of stakeholders: suppliers, distribution partners, other departments and consumers, who are free to choose among competing offers."}]},{"text":[{"text":"A "},{"text":"customer's perception","bold":true},{"text":" of a company or brand is a "},{"text":"synthesis of bundles of messages","bold":true},{"text":": media advertising, "},{"text":"price","bold":true},{"text":", "},{"text":"packaging design","bold":true},{"text":", direct marketing, publicity, sales promotion and websites. The price of Indomie \"speaks\" as much as its TV advert."}]},{"text":[{"text":"Used well, MarCom generates "},{"text":"more leads, sales and loyal customers","bold":true},{"text":"; its ultimate aim is to influence "},{"text":"consumer decision-making and buying behaviour","bold":true},{"text":"."}]}]}]},{"number":"1.2","title":"Types of communication and the marketing mix","mustKnow":[{"type":"paragraph","text":[{"text":"4 types of communication","bold":true},{"text":" (by direction of flow between senders and receivers):"}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}],[{"text":"Example"}]],"rows":[[[{"text":"One-to-many","bold":true}],[{"text":"The most original form; generated from a "},{"text":"single broadcast point","bold":true},{"text":", then available over airwaves or in mass print runs"}],[{"text":"News distribution, general announcements, TV and radio broadcasts"}]],[[{"text":"Many-to-one","bold":true}],[{"text":"Generally connected to one-to-many; many receivers reply to one sender"}],[{"text":"The "},{"text":"reply button","bold":true},{"text":" in an email box"}]],[[{"text":"One-to-one","bold":true}],[{"text":"The "},{"text":"most intensive and interactive","bold":true},{"text":" form"}],[{"text":"A "},{"text":"sales presentation","bold":true},{"text":" or a "},{"text":"negotiation","bold":true}]],[[{"text":"Many-to-many","bold":true}],[{"text":"Growing because of the highly developed "},{"text":"Internet","bold":true},{"text":"; everyone talks to everyone"}],[{"text":"Online chat rooms","bold":true},{"text":", blogs, websites"}]]]},{"type":"paragraph","text":[{"text":"The marketing mix: the Seven Ps (formerly the Four Ps).","bold":true},{"text":" A brand typically builds its MarCom strategy around it:"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Product:","bold":true},{"text":" the features of the good or service the business offers."}]},{"text":[{"text":"Price:","bold":true},{"text":" the pricing model used for the good or service."}]},{"text":[{"text":"Promotion:","bold":true},{"text":" all the ways in which the brand, product or service is communicated to the public. It also involves another P, "},{"text":"Positioning","bold":true},{"text":", to evaluate how people view and respond to the brand."}]},{"text":[{"text":"Place:","bold":true},{"text":" where the good or service is bought and sold."}]},{"text":[{"text":"People:","bold":true},{"text":" all the people who interact with a brand's customers or clients."}]},{"text":[{"text":"Process:","bold":true},{"text":" the customer experience and communication process."}]},{"text":[{"text":"Packaging:","bold":true},{"text":" how best to attract customers in the physical and online marketplace."}]}]},{"type":"paragraph","text":[{"text":"Types of marketing communication (the tools):","bold":true},{"text":" the traditional "},{"text":"five","bold":true},{"text":" are advertising, sales promotion, personal selling, public relations and direct marketing. Others include publicity, events and experiences (sponsorship), interactive marketing and word-of-mouth marketing. Each is treated fully in Topic 3."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Count senders and receivers: GTBank emailing one newsletter to all customers is "},{"text":"one-to-many","bold":true},{"text":"; hundreds of them clicking \"reply\" is "},{"text":"many-to-one","bold":true},{"text":"; a sales pitch to one client is "},{"text":"one-to-one","bold":true},{"text":"; UNILAG students debating phone brands in a group chat is "},{"text":"many-to-many","bold":true},{"text":"."}]},{"text":[{"text":"\"Most intensive and interactive\" = one-to-one; \"most original\" = one-to-many. The count is "},{"text":"four","bold":true},{"text":"."}]},{"text":[{"text":"Trap: the extra P inside Promotion is "},{"text":"Positioning","bold":true},{"text":". In the services-marketing version of the 7 Ps you may meet "},{"text":"physical evidence","bold":true},{"text":" in place of packaging; for this course, learn the list above."}]},{"text":[{"text":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 3, $study_guide$A Lagos fashion brand training its shop attendants and delivery riders on how to treat buyers is working on "},{"text":"People","bold":true},{"text":"."}]},{"text":[{"text":"The combination most representative of MarCom is "},{"text":"advertising, sales promotion and direct marketing","bold":true},{"text":", not \"product, price and place\" or \"segmentation, targeting and positioning\". "},{"text":"Integrated advertising campaigns across multiple channels","bold":true},{"text":" are a core MarCom component; prototyping and warehousing are not."}]}]}]},{"number":"1.3","title":"The emergence of marketing communication and IMC","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing communication is "},{"text":"not new","bold":true},{"text":": communication has been part of marketing "},{"text":"for as long as people have exchanged goods","bold":true},{"text":"."}]},{"text":[{"text":"Technology and research made it "},{"text":"increasingly sophisticated","bold":true},{"text":" in recent decades and gave rise to "},{"text":"integrated marketing communication (IMC)","bold":true},{"text":"."}]},{"text":[{"text":"IMC:","bold":true},{"text":" the use of "},{"text":"multiple channels to create a unified message","bold":true},{"text":"."}]},{"text":[{"text":"Consumers have changed","bold":true},{"text":" in 4 ways: their behaviour is "},{"text":"more complex","bold":true},{"text":"; their "},{"text":"media habits are different","bold":true},{"text":"; they are "},{"text":"more confident and outspoken","bold":true},{"text":"; and, most important, they have "},{"text":"more choices than ever before","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Timeline:","bold":true}]},{"type":"table","header":[[{"text":"When"}],[{"text":"Development"}],[{"text":"Significance"}]],"rows":[[[{"text":"15th century"}],[{"text":"Johannes Gutenberg's printing press","bold":true}],[{"text":"Before it, only handwritten manuscripts for the elite; marked the "},{"text":"birth of print advertising","bold":true}]],[[{"text":"17th century"}],[{"text":"First printed advertisements","bold":true},{"text":" in newspapers"}],[{"text":"Promoted medicines to real estate"}]],[[{"text":"1920s"}],[{"text":"Radio commercials","bold":true},{"text":" begin"}],[{"text":"Reached households with audio messages"}]],[[{"text":"1950s"}],[{"text":"Television","bold":true},{"text":" becomes the "},{"text":"dominant platform","bold":true}],[{"text":"Combined visuals and sound"}]],[[{"text":"1960s"}],[{"text":"Volkswagen's "},{"text":"\"Think Small\"","bold":true},{"text":" campaign"}],[{"text":"Showed TV could be used for "},{"text":"storytelling","bold":true},{"text":" and "},{"text":"emotional connections","bold":true}]],[[{"text":"Late 20th century"}],[{"text":"The Internet","bold":true}],[{"text":"Digital age: websites as "},{"text":"virtual storefronts","bold":true},{"text":", email as a "},{"text":"direct line","bold":true},{"text":" to customers"}]],[[{"text":"1996"}],[{"text":"Hotmail's viral strategy","bold":true}],[{"text":"\"Get your free email at Hotmail\" on every sent email; millions of users within months; an early "},{"text":"viral digital marketing","bold":true},{"text":" success"}]],[[{"text":"Early 2000s"}],[{"text":"MySpace, Facebook, Twitter","bold":true}],[{"text":"Turned marketing into a "},{"text":"two-way conversation","bold":true},{"text":"; brands engage directly with customers"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The lesson of the whole journey: marketing communication is "},{"text":"ever-evolving","bold":true},{"text":", so understanding its history helps firms "},{"text":"anticipate future trends","bold":true},{"text":" and craft strategies that resonate with audiences."}]},{"text":[{"text":"Trap: \"consumers now have "},{"text":"fewer","bold":true},{"text":" choices\" is false. They have more."}]},{"text":[{"text":"Trap: printing press "},{"text":"15th","bold":true},{"text":" century, but first newspaper adverts "},{"text":"17th","bold":true},{"text":" century."}]},{"text":[{"text":"Hotmail's tagline is "},{"text":"viral","bold":true},{"text":" marketing: users spread the message simply by using the product."}]},{"text":[{"text":"Social media did "},{"text":"not","bold":true},{"text":" end print and broadcast advertising; it added two-way dialogue, as when Jumia replies to customers on X and Instagram."}]},{"text":[{"text":"IMC in practice: MTN running the same slogan, colours and offer on TV, radio, billboards and social media, so every channel tells one story."}]}]}]},{"number":"1.4","title":"Marketing communication and the process of exchange","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exchange process:","bold":true},{"text":" the act of "},{"text":"obtaining a desired object from someone by offering something of value in return","bold":true},{"text":"."}]},{"text":[{"text":"Transaction:","bold":true},{"text":" the result of an exchange between a person in need (offering money or other resources) and the company selling a good, service or idea."}]},{"text":[{"text":"5 conditions for exchange:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"There must be "},{"text":"at least two parties","bold":true},{"text":"."}]},{"text":[{"text":"Each must have "},{"text":"something that might be of value","bold":true},{"text":" to the other."}]},{"text":[{"text":"Each can "},{"text":"communicate and deliver","bold":true},{"text":" what they are offering."}]},{"text":[{"text":"Each is "},{"text":"free to accept or reject","bold":true},{"text":" what is on offer."}]},{"text":[{"text":"Each party "},{"text":"trusts/respects","bold":true},{"text":" the other sufficiently to take the exchange seriously."}]}]}]},{"text":[{"text":"Two observable types of exchange:","bold":true},{"text":" "},{"text":"market","bold":true},{"text":" exchange and "},{"text":"relational","bold":true},$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 4, $study_guide${"text":" exchange. There is a strong shift from one-off market exchanges to long-term "},{"text":"relationship marketing","bold":true},{"text":": \"Marketing is not just about selling products; it's about building relationships and creating value.\""}]}]},{"type":"paragraph","text":[{"text":"Process of marketing communications (steps in order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify the target audience:","bold":true},{"text":" focus on distinct segments; presenting to everyone does not work."}]},{"text":[{"text":"Determine the unique value (selling) proposition (UVP/USP):","bold":true},{"text":" what makes the business stand out and outperform rivals."}]},{"text":[{"text":"Bring the solution to customers' queries:","bold":true},{"text":" reach customers' pain points with the good or service."}]},{"text":[{"text":"Select channels","bold":true},{"text":" to deliver the brand message: depends on the "},{"text":"objectives","bold":true},{"text":" to be accomplished and "},{"text":"customers' preferences (choices)","bold":true},{"text":"."}]},{"text":[{"text":"Budget allocation:","bold":true},{"text":" how much to spend on each channel."}]},{"text":[{"text":"Message development:","bold":true},{"text":" crafting key messages that resonate with the audience."}]},{"text":[{"text":"Execution:","bold":true},{"text":" implementing the chosen plan."}]},{"text":[{"text":"Evaluate and measure the result:","bold":true},{"text":" track outcomes after the campaign runs."}]},{"text":[{"text":"Develop control measures:","bold":true},{"text":" measure the campaign's effectiveness "},{"text":"against objectives","bold":true},{"text":" and make necessary adjustments."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Condition 3 shows most directly "},{"text":"why marketing communication is necessary","bold":true},{"text":": a seller who cannot tell buyers what it offers cannot exchange."}]},{"text":[{"text":"Trap: \"each party must be "},{"text":"legally bound","bold":true},{"text":" to accept whatever is offered\" is "},{"text":"not","bold":true},{"text":" a condition. Freedom to accept or reject is."}]},{"text":[{"text":"Ada pays ₦4,500 to a Yaba bookshop for a book: the completed exchange is a "},{"text":"transaction","bold":true},{"text":"."}]},{"text":[{"text":"MarCom helps exchange by "},{"text":"generating awareness, fostering trust and driving purchase intent","bold":true},{"text":". Exchange is a "},{"text":"reciprocal creation of value","bold":true},{"text":" benefiting both organisation and customers. Partnerships between brands and consumers, and between firms in distribution channels, are vital to MarCom."}]},{"text":[{"text":"UVP/USP example:","bold":true},{"text":" Domino's Pizza positions itself as delivering the newest and hottest pizza faster than rivals, in only "},{"text":"30 minutes","bold":true},{"text":"."}]},{"text":[{"text":"This process is sometimes introduced as \"six stages\"; learn each step's name and job in the order above. Step 8 tracks outcomes; step 9 compares with objectives and "},{"text":"adjusts","bold":true},{"text":"."}]}]}]},{"number":"1.5","title":"Roles and objectives of marketing communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Primary objective:","bold":true},{"text":" to "},{"text":"increase sales volume","bold":true},{"text":" through "},{"text":"persuasive, informative and positive messages","bold":true},{"text":"."}]},{"text":[{"text":"MarCom objectives are "},{"text":"long-term goals","bold":true},{"text":" that aim to "},{"text":"boost the brand's value over time","bold":true},{"text":"."}]},{"text":[{"text":"9 specific objectives:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Increase brand awareness:","bold":true},{"text":" make people know the business and its products exist (broadcast commercials or print ads); a top priority for new and existing firms."}]},{"text":[{"text":"Change attitudes:","bold":true},{"text":" correct mistaken beliefs spread about the business or its products."}]},{"text":[{"text":"Influence purchase intent:","bold":true},{"text":" compelling ads that focus on "},{"text":"superior benefits to users compared with competitors","bold":true},{"text":"."}]},{"text":[{"text":"Stimulate trial purchase and repeat patronage:","bold":true},{"text":" free trials or samples take the risk off so customers experience the brand."}]},{"text":[{"text":"Drive brand switching:","bold":true},{"text":" get buyers of competing products to switch to your brand."}]},{"text":[{"text":"Connect companies with consumers:","bold":true},{"text":" convey messages so the brand is better known and trusted."}]},{"text":[{"text":"Build a brand image:","bold":true},{"text":" branding is not built in a short time."}]},{"text":[{"text":"Conduct research for the company:","bold":true},{"text":" connect company stakeholders with the market by "},{"text":"reading trend movements","bold":true},{"text":" in the sector."}]},{"text":[{"text":"Do direct selling:","bold":true},{"text":" market products directly into end users' hands to build trust."}]}]}]},{"text":[{"text":"5 important roles:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Building brand awareness:","bold":true},{"text":" customers know the organisation exists and what it offers."}]},{"text":[{"text":"Maintaining customer loyalty:","bold":true},{"text":" customers develop a positive bond with the company and its brands."}]},{"text":[{"text":"Creating demand for products and services:","bold":true},{"text":" improved or innovative products are not enough; people need to know they exist to buy them."}]},{"text":[{"text":"Shortening the sales cycle:","bold":true},{"text":" by better understanding customer needs, buying motivations, influences and processes, and using this insight when engaging consumers."}]},$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 5, $study_guide${"text":[{"text":"Highlighting a competitive edge:","bold":true},{"text":" in a crowded 21st-century marketplace, points of differentiation must be shared with the public to enhance competitive advantage."}]}]}]},{"text":[{"text":"3 other specific roles:","bold":true},{"text":" (i) influences consumer behaviour to drive sales; (ii) engages customers at various points along the buying journey; (iii) integrates all marketing tools to achieve seamless communication."}]},{"text":[{"text":"DRIP (Fill):","bold":true},{"text":" "},{"text":"D","bold":true},{"text":"ifferentiate, "},{"text":"R","bold":true},{"text":"einforce, "},{"text":"I","bold":true},{"text":"nform, "},{"text":"P","bold":true},{"text":"ersuade."}]},{"text":[{"text":"Kotler's three classic aims:","bold":true},{"text":" "},{"text":"inform, persuade, remind","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"DRIP role"}],[{"text":"What it does"}],[{"text":"Example"}]],"rows":[[[{"text":"Differentiate"}],[{"text":"Shows how the brand differs from rivals"}],[{"text":"Highlighting a unique feature"}]],[[{"text":"Reinforce"}],[{"text":"Consolidates past messages and experiences; reminds and reassures existing buyers"}],[{"text":"A well-known drink reminding loyal buyers of good times with it"}]],[[{"text":"Inform"}],[{"text":"Makes people aware of the offer"}],[{"text":"A new product launch"}]],[[{"text":"Persuade"}],[{"text":"Encourages a desired action, such as buying"}],[{"text":"\"Buy now\" offers"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Matching scenarios (the commonest question style):"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A new fintech app runs radio and print ads so people know it exists: "},{"text":"increase brand awareness","bold":true},{"text":"."}]},{"text":[{"text":"A bottled-water brand hit by false rumours shows its NAFDAC approval and factory tests: "},{"text":"change attitudes","bold":true},{"text":"."}]},{"text":[{"text":"Free sample sachets of a new cream at a Lagos mall: "},{"text":"stimulate trial purchase","bold":true},{"text":"."}]},{"text":[{"text":"Bonus data for customers of rival networks who port their lines: "},{"text":"drive brand switching","bold":true},{"text":"."}]},{"text":[{"text":"Birthday messages and loyalty-point updates from an Abuja supermarket: "},{"text":"maintaining customer loyalty","bold":true},{"text":" (a role)."}]}]}]},{"text":[{"text":"Trap: a familiar brand \"reminding\" loyal buyers of good experiences is "},{"text":"Reinforce","bold":true},{"text":" under DRIP (Kotler would say "},{"text":"remind","bold":true},{"text":")."}]},{"text":[{"text":"Fixing machinery, setting the minimum wage, cutting production costs or replacing a quality product are "},{"text":"never","bold":true},{"text":" MarCom objectives or roles."}]},{"text":[{"text":"Strategically, MarCom "},{"text":"enhances brand equity, fosters loyalty and drives repeat purchases","bold":true},{"text":", and influences purchasing patterns through "},{"text":"targeted messaging","bold":true},{"text":". Its primary function is to "},{"text":"inform, persuade and remind","bold":true},{"text":" customers to sustain engagement with the brand."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing: exchange relationships; Baker = profitable customer relationships; Kotler and Armstrong = create value, capture value in return."}]},{"text":[{"text":"Communication = using words, sounds or visual cues to supply information to one or more people."}]},{"text":[{"text":"MarCom = channels and tools to communicate the necessary message to the target group; no universal definition."}]},{"text":[{"text":"4 types of communication: one-to-many (most original), many-to-one (email reply), one-to-one (most intensive), many-to-many (chat rooms, blogs)."}]},{"text":[{"text":"Seven Ps (formerly Four Ps): product, price, promotion (plus positioning), place, people, process, packaging."}]},{"text":[{"text":"Printing press (15th c.), first print ads (17th c.), radio (1920s), TV dominant (1950s), Think Small (1960s), Hotmail viral (1996), social media two-way (early 2000s); IMC = multiple channels, one unified message."}]},{"text":[{"text":"5 conditions for exchange; exchange process yields a transaction; nine-step MarCom process from target audience to control measures."}]},{"text":[{"text":"Primary objective: increase sales volume; 9 specific objectives; 5 main roles plus 3 others; DRIP = Differentiate, Reinforce, Inform, Persuade."}]}]}],"theory":{"itemId":"b1e247aa-afc5-562a-bdb7-676783d6166e","question":[{"type":"paragraph","text":[{"text":"State the five conditions for an exchange to take place and explain which of them shows why marketing communication is needed."}]}]},"practice":[{"topic":"Nature, Types, Roles and Objectives of Marketing Communication","named":false}]}},{"kind":"note","itemId":"73884fc6-797d-56d4-abb1-d1798a443445","sourceKey":"guide-topic:2","position":2,"payload":{"title":"Models of Marketing Communication and MarCom Planning","body":"The basic communication model and its elements; linear, interactional and transactional views; one-step, two-step and multi-step flow; the response hierarchy models (AIDA, Lavidge and Steiner, innovation-adoption, information processing, DAGMAR); the process of marketing communications and SMART objectives; SOSTAC; the MCPF and its seven elements; push, pull and profile strategies; budgeting methods.","noteType":"guide_topic","number":2,"mustKnow":[{"text":"The basic communication model and its elements; linear, interactional and transactional views; one-step, two-step and multi-step flow; the response hierarchy models (AIDA, Lavidge and Steiner, innovation-adoption, information processing, DAGMAR); the process of marketing communications and SMART objectives; SOSTAC; the MCPF and its seven elements; push, pull and profile strategies; budgeting methods."}],"lessons":[{"number":"2.1",$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 6, $study_guide$"title":"The basic communication model","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Model of marketing communication:","bold":true},{"text":" a simplified picture of how a persuasive message passes from a sender to a receiver. Its usefulness lies in its ability to "},{"text":"explain how persuasive messages are transmitted and received","bold":true},{"text":", so a marketer can see where communication can break down."}]},{"text":[{"text":"Basic elements:","bold":true},{"text":" "},{"text":"sender, encoded message, medium (channel), receiver and feedback","bold":true},{"text":", plus noise."}]},{"text":[{"text":"Basic sequence:","bold":true},{"text":" "},{"text":"Sender - encoding - message/medium - decoding - receiver - feedback.","bold":true}]}]},{"type":"table","header":[[{"text":"Element"}],[{"text":"Meaning"}]],"rows":[[[{"text":"Sender (source)"}],[{"text":"The person or organisation with an idea to share, e.g. the brand"}]],[[{"text":"Encoding"}],[{"text":"Turning the sender's ideas into a message made of words, pictures, symbols or sounds"}]],[[{"text":"Message"}],[{"text":"The set of symbols the sender transmits"}]],[[{"text":"Medium (channel)"}],[{"text":"The path that carries the message: TV, radio, press, social media, a salesperson"}]],[[{"text":"Decoding"}],[{"text":"The receiver interpreting the symbols in the message to give it meaning"}]],[[{"text":"Receiver"}],[{"text":"The person who gets and decodes the message (the target audience)"}]],[[{"text":"Response"}],[{"text":"What the receiver does after exposure"}]],[[{"text":"Feedback"}],[{"text":"The part of the response that goes back to the sender"}]],[[{"text":"Noise"}],[{"text":"Any unplanned interference or distortion that stops the receiver getting the message as intended"}]],[[{"text":"Field of experience"}],[{"text":"The experiences, attitudes, values and perceptions each party brings; understanding is greatest where the two fields overlap"}]]]},{"type":"paragraph","text":[{"text":"Three views of communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Linear (Shannon and Weaver, 1949):","bold":true},{"text":" a "},{"text":"one-way","bold":true},{"text":" flow from sender, through encoding, message and channel, to decoding by a receiver. "},{"text":"Weakness:","bold":true},{"text":" it treats the receiver as "},{"text":"passive","bold":true},{"text":" and ignores feedback."}]},{"text":[{"text":"Interactional (Schramm):","bold":true},{"text":" two-way; sender and receiver take turns, both encode and decode; adds "},{"text":"feedback","bold":true},{"text":" and "},{"text":"field of experience","bold":true},{"text":"."}]},{"text":[{"text":"Transactional:","bold":true},{"text":" both parties send and receive "},{"text":"at the same time","bold":true},{"text":", so meaning is created jointly within a shared context."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A sound model stresses "},{"text":"feedback as a way of refining the effectiveness of messages","bold":true},{"text":". Without feedback, the firm cannot tell whether its message was understood."}]},{"text":[{"text":"Feedback example:","bold":true},{"text":" after hearing a radio jingle for a new noodle brand, a listener calls the toll-free line to ask where to buy it. The call is "},{"text":"feedback","bold":true},{"text":", not the channel. Likes, comments, complaints, sales figures and survey answers are also feedback."}]},{"text":[{"text":"Noise examples:","bold":true},{"text":" a power cut during a TV advert, traffic noise drowning a radio jingle, a rival's advert in the same break, a blurred billboard, a receiver who is distracted."}]},{"text":[{"text":"Field of experience trap:","bold":true},{"text":" a Lagos bank uses slang and references its young target customers in Ibadan do not understand, so the advert fails. The cause is "},{"text":"too little overlap between the fields of experience","bold":true},{"text":" of sender and receiver, not noise. The fix is to encode in words and images the audience shares."}]},{"text":[{"text":"Exams swap encoding and decoding. Remember: the "},{"text":"sender encodes","bold":true},{"text":", the "},{"text":"receiver decodes","bold":true},{"text":". Options that put the receiver first, or decoding before the medium, are wrong."}]},{"text":[{"text":"The basic model is a "},{"text":"communication","bold":true},{"text":" model. Do not confuse it with the 4Ps (product, price, place, promotion), STP (segmentation, targeting, positioning) or SWOT."}]}]}]},{"number":"2.2","title":"Flow models: one-step, two-step and multi-step","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"One-step flow (hypodermic needle or magic bullet):","bold":true},{"text":" the mass media reach the audience "},{"text":"directly","bold":true},{"text":", with "},{"text":"no opinion leaders","bold":true},{"text":" in between. Every receiver is assumed to take in the message the same way."}]},{"text":[{"text":"Two-step flow (Lazarsfeld and colleagues; later Katz and Lazarsfeld):","bold":true},{"text":" messages flow from the "},{"text":"mass media to opinion leaders","bold":true},{"text":", who then pass them on (with their own interpretation) to "},{"text":"opinion followers","bold":true},{"text":"."}]},{"text":[{"text":"Multi-step flow:","bold":true},{"text":" develops the two-step model by recognising that information can flow "},{"text":"in several directions among the media, opinion leaders and opinion followers","bold":true},{"text":". Followers also use the media directly, and opinion leaders also seek advice from others."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Opinion leader:","bold":true},{"text":" a person within a group whose views on a product or topic others respect and copy."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Key difference:","bold":true},{"text$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 7, $study_guide$":" in the one-step model the media reach the audience directly; in the two-step model "},{"text":"opinion leaders stand in between","bold":true},{"text":". Neither model's distinguishing feature is feedback."}]},{"text":[{"text":"Nigerian application:","bold":true},{"text":" a skincare brand sends free products to a well-known Nigerian beauty blogger, hoping her followers will copy her recommendations. This relies on the "},{"text":"two-step flow","bold":true},{"text":". Influencer marketing on Instagram and TikTok, and telecoms such as MTN or Glo using celebrity ambassadors, follow the same logic."}]},{"text":[{"text":"The two-step idea came from Lazarsfeld, Berelson and Gaudet's study of how American voters decided in the 1940 election: personal influence mattered more than media alone."}]}]}]},{"number":"2.3","title":"Response hierarchy (hierarchy-of-effects) models","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Hierarchy-of-effects (response hierarchy) models:","bold":true},{"text":" models that assume buyers pass through a "},{"text":"set sequence of stages, from awareness to purchase","bold":true},{"text":", in response to marketing communication."}]},{"text":[{"text":"Three components (learn, feel, do):","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cognitive (thinking):","bold":true},{"text":" what the receiver "},{"text":"knows or thinks","bold":true},{"text":", e.g. awareness, knowledge."}]},{"text":[{"text":"Affective (feeling):","bold":true},{"text":" what the receiver "},{"text":"feels","bold":true},{"text":", e.g. liking, preference."}]},{"text":[{"text":"Conative (behavioural):","bold":true},{"text":" what the receiver "},{"text":"does","bold":true},{"text":", e.g. trial, purchase."}]}]}]}]},{"type":"table","header":[[{"text":"Model (author)"}],[{"text":"Cognitive"}],[{"text":"Affective"}],[{"text":"Conative (behaviour)"}]],"rows":[[[{"text":"AIDA (E. St. Elmo Lewis)"}],[{"text":"Attention"}],[{"text":"Interest, Desire"}],[{"text":"Action"}]],[[{"text":"Hierarchy of effects (Lavidge and Steiner, 1961)"}],[{"text":"Awareness, Knowledge"}],[{"text":"Liking, Preference"}],[{"text":"Conviction, Purchase"}]],[[{"text":"Innovation-adoption (Rogers)"}],[{"text":"Awareness"}],[{"text":"Interest, Evaluation"}],[{"text":"Trial, Adoption"}]],[[{"text":"Information processing (McGuire)"}],[{"text":"Presentation, Attention, Comprehension"}],[{"text":"Yielding, Retention"}],[{"text":"Behaviour"}]],[[{"text":"DAGMAR (Russell Colley, 1961)"}],[{"text":"Awareness, Comprehension"}],[{"text":"Conviction"}],[{"text":"Action"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"AIDA","bold":true},{"text":" = "},{"text":"A","bold":true},{"text":"ttention, "},{"text":"I","bold":true},{"text":"nterest, "},{"text":"D","bold":true},{"text":"esire, "},{"text":"A","bold":true},{"text":"ction (4 stages). Desire comes immediately after Interest."}]},{"text":[{"text":"Lavidge and Steiner","bold":true},{"text":" (6 stages): "},{"text":"awareness, knowledge, liking, preference, conviction, purchase.","bold":true}]},{"text":[{"text":"Innovation-adoption","bold":true},{"text":" (5 stages): "},{"text":"awareness, interest, evaluation, trial, adoption.","bold":true}]},{"text":[{"text":"Information processing","bold":true},{"text":" (6 stages): presentation, attention, comprehension, yielding, retention, behaviour."}]},{"text":[{"text":"DAGMAR","bold":true},{"text":" = "},{"text":"D","bold":true},{"text":"efining "},{"text":"A","bold":true},{"text":"dvertising "},{"text":"G","bold":true},{"text":"oals for "},{"text":"M","bold":true},{"text":"easured "},{"text":"A","bold":true},{"text":"dvertising "},{"text":"R","bold":true},{"text":"esults, by "},{"text":"Russell Colley","bold":true},{"text":" (1961). Stages (ACCA): "},{"text":"awareness, comprehension, conviction, action.","bold":true}]},{"text":[{"text":"DAGMAR principle:","bold":true},{"text":" advertising objectives must be "},{"text":"specific and measurable","bold":true},{"text":", with a defined "},{"text":"target audience","bold":true},{"text":", a "},{"text":"benchmark","bold":true},{"text":" (starting point), the "},{"text":"degree of change","bold":true},{"text":" sought and a "},{"text":"time period","bold":true},{"text":". Objectives are communication tasks, not just sales."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"AIDA in practice:","bold":true},{"text":" a poster for a new Lagos gym uses bright colours and a bold headline so passers-by stop and look: "},{"text":"Attention","bold":true},{"text":". A \"Shop now - offer ends at midnight\" button on a Jumia-style advert: "},{"text":"Action","bold":true},{"text":". Showing how tasty a new Indomie flavour is builds "},{"text":"Interest","bold":true},{"text":"; showing someone enjoying it and saying \"you deserve this\" builds "},{"text":"Desire","bold":true},{"text":"."}]},{"text":[{"text":"Kotler's buyer-readiness stages","bold":true},{"text":" are the same six as Lavidge and Steiner. Exams swap the order of liking and knowledge, or of preference and conviction: knowledge always comes before liking, and preference before conviction."}]},{"text":[{"text":"Some writers place conviction in the affective stage rather than the conative; in every version, "},{"text":"liking and preference are affective","bold":true},{"text":" and "},{"text":"purchase is conative","bold":true},{"text":"."}]},{"text":[{"text":"Do not mix up the stage lists: \"awareness, comprehension, conviction, action\" is DAGMAR; \"awareness, interest, evaluation, trial, adoption\" is innovation-adoption; \"attention, interest, desire, action\" is AIDA. \"Exposure, reception, cognitive response ... behaviour\" belongs to a different communications-response sequence, not innovation-adoption."}]},{"text":[{"text":"DAGMAR example:","bold":true},{"text":" \"Raise awareness of our new juice among Lagos undergraduates from 20% to 45% wit$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 8, $study_guide$hin six months.\" Target audience = Lagos undergraduates; benchmark = 20%; degree of change = 25 percentage points; time period = six months."}]},{"text":[{"text":"Criticism of hierarchy models:","bold":true},{"text":" consumers "},{"text":"do not always pass through the stages in a fixed order","bold":true},{"text":". With low-involvement or impulse buys (a sachet of Pure Water, a Gala at a traffic jam), people may buy first and form attitudes afterwards (do-feel-learn or learn-do-feel). The models also make it hard to link one advert to one stage, and they ignore the effect of other influences such as friends and price."}]}]}]},{"number":"2.4","title":"Developing a marketing communications plan","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Why a plan is needed:","bold":true},{"text":" it sets out "},{"text":"in a logical order what the firm wants to achieve with communication and how","bold":true},{"text":", so activities are coordinated and can be evaluated. It does "},{"text":"not","bold":true},{"text":" replace the marketing plan or guarantee success."}]},{"text":[{"text":"An effective plan requires "},{"text":"setting measurable goals, selecting appropriate tools and evaluating outcomes","bold":true},{"text":"."}]},{"text":[{"text":"A well-executed plan ensures "},{"text":"integration and consistency across all communication touchpoints","bold":true},{"text":" (one clear message across every tool)."}]},{"text":[{"text":"A "},{"text":"foundational element","bold":true},{"text":" is formulating "},{"text":"precise, actionable and time-bound objectives","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Process of marketing communications (in order):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Identify the target audience","bold":true},{"text":" (first stage): focus on distinct segments, not everybody."}]},{"text":[{"text":"Determine the company's unique value (selling) proposition (UVP or USP):","bold":true},{"text":" what makes the business stand out from rivals."}]},{"text":[{"text":"Bring the solution to customers' queries:","bold":true},{"text":" strategies that answer customers' pain points with the product."}]},{"text":[{"text":"Select channels to deliver the brand message:","bold":true},{"text":" based on objectives and customers' choices."}]},{"text":[{"text":"Budget allocation:","bold":true},{"text":" how much to spend on each channel."}]},{"text":[{"text":"Message development:","bold":true},{"text":" crafting key messages that resonate with the audience."}]},{"text":[{"text":"Execution:","bold":true},{"text":" implementing the chosen plan."}]},{"text":[{"text":"Evaluate and measure the results:","bold":true},{"text":" track outcomes after the campaign runs."}]},{"text":[{"text":"Develop control measures:","bold":true},{"text":" measure effectiveness against objectives and make adjustments."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"SMART objectives:","bold":true},{"text":" "},{"text":"S","bold":true},{"text":"pecific, "},{"text":"M","bold":true},{"text":"easurable, "},{"text":"A","bold":true},{"text":"chievable, "},{"text":"R","bold":true},{"text":"ealistic, "},{"text":"T","bold":true},{"text":"ime-bound."}]},{"text":[{"text":"SOSTAC","bold":true},{"text":" (P.R. Smith): "},{"text":"S","bold":true},{"text":"ituation, "},{"text":"O","bold":true},{"text":"bjectives, "},{"text":"S","bold":true},{"text":"trategy, "},{"text":"T","bold":true},{"text":"actics, "},{"text":"A","bold":true},{"text":"ction, "},{"text":"C","bold":true},{"text":"ontrol."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"USP example:","bold":true},{"text":" Domino's Pizza positioning itself as the business that delivers the newest and hottest pizza faster than competitors, in only 30 minutes, is its "},{"text":"unique value (selling) proposition","bold":true},{"text":". A Nigerian parallel: a bank promising account opening in five minutes on its app."}]},{"text":[{"text":"Count trap:","bold":true},{"text":" this process is often introduced as \"six stages\", yet nine steps are named above. Learn the order: the first is "},{"text":"identifying the target audience","bold":true},{"text":", and the last two are evaluating results and developing control measures."}]},{"text":[{"text":"Good objective:","bold":true},{"text":" \"Increase awareness of our new brand among undergraduates in Lagos from 20% to 45% within six months\" is well written because it is "},{"text":"specific, measurable and time-bound, with a clear target audience and benchmark","bold":true},{"text":"."}]},{"text":[{"text":"Bad planning habits","bold":true},{"text":" exams offer as distractors: choosing media first and setting objectives after the campaign; copying a competitor's plan without audience analysis; spending equally on every tool; repeating last year's plan unchanged; leaving objectives undefined; choosing the cheapest medium regardless of audience; making each tool send a different, unrelated message."}]},{"text":[{"text":"SOSTAC","bold":true},{"text":" stages: Situation = where are we now; Objectives = where do we want to be; Strategy = how do we get there overall; Tactics = the details (which tools); Action = who does what and when; Control = how we measure and adjust. Smith adds the "},{"text":"3Ms","bold":true},{"text":": men (people), money, minutes (time)."}]},{"text":[{"text":"Kotler's steps for effective communication:","bold":true},{"text":" identify the target audience; determine communication objectives (buyer-readiness stage); design the message; choose the media; select the message source; collect feedback."}]}]}]},{"number":"2.5","title":"The Marketing Communications Planning Framework (MCPF)","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"MCPF (Fill):","bold":true},{"text":" a "},{"text":"sequence of linked stages that guides the development of a marketing communi$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 9, $study_guide$cations plan","bold":true},{"text":". It provides a "},{"text":"structured approach for aligning communication strategies with business objectives","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"The seven elements in order:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Context analysis","bold":true},{"text":" (first): customer, business, internal and external contexts."}]},{"text":[{"text":"Communication objectives:","bold":true},{"text":" derived from the "},{"text":"corporate and marketing objectives","bold":true},{"text":"; SMART."}]},{"text":[{"text":"Marketing communications strategy:","bold":true},{"text":" the overall approach: push, pull or profile, and positioning."}]},{"text":[{"text":"Coordinated communications mix:","bold":true},{"text":" "},{"text":"choosing and combining the tools, media and messages so they work together","bold":true},{"text":"."}]},{"text":[{"text":"Resources:","bold":true},{"text":" the "},{"text":"budget, people and time","bold":true},{"text":" needed to carry out the plan."}]},{"text":[{"text":"Scheduling and implementation:","bold":true},{"text":" "},{"text":"when each activity will happen and in what order","bold":true},{"text":"."}]},{"text":[{"text":"Evaluation and control","bold":true},{"text":" (last): measuring results against objectives and adjusting."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Feedback:","bold":true},{"text":" results from evaluation "},{"text":"feed back into earlier stages","bold":true},{"text":" so that future plans improve."}]}]},{"type":"paragraph","text":[{"text":"Four contexts examined in context analysis:","bold":true}]},{"type":"table","header":[[{"text":"Context"}],[{"text":"What it covers"}]],"rows":[[[{"text":"Customer"}],[{"text":"Buyers' needs, behaviour, segments, how they decide"}]],[[{"text":"Business"}],[{"text":"Competitors, the market, the firm's marketing strategy"}]],[[{"text":"Internal"}],[{"text":"The firm's resources, culture, finance, skills"}]],[[{"text":"External (wider environment)"}],[{"text":"Political, economic, social, technological, legal factors (PESTEL)"}]]]},{"type":"paragraph","text":[{"text":"Three strategies (3Ps):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Pull:","bold":true},{"text":" aimed at "},{"text":"end-user consumers","bold":true},{"text":", to encourage them to ask for and buy the product, so it is \"pulled\" through the channel."}]},{"text":[{"text":"Push:","bold":true},{"text":" aimed at "},{"text":"wholesalers and retailers","bold":true},{"text":" (the trade), to encourage them to stock and promote the product."}]},{"text":[{"text":"Profile:","bold":true},{"text":" aimed at "},{"text":"a wide range of stakeholders","bold":true},{"text":", to build the organisation's "},{"text":"corporate image and reputation","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Context analysis is the foundation","bold":true},{"text":" because it provides the information on which objectives, strategy and the mix are based. Final evaluation of results is "},{"text":"not","bold":true},{"text":" part of context analysis; it is the last stage."}]},{"text":[{"text":"External context example:","bold":true},{"text":" a Nigerian telecom firm studying new NCC regulations, inflation and changes in technology before a campaign is analysing the "},{"text":"external (wider environment) context","bold":true},{"text":"."}]},{"text":[{"text":"Strategy example:","bold":true},{"text":" \"Position our bank as the friendliest choice for students, using a pull strategy built mainly on social media\" is a "},{"text":"marketing communications strategy","bold":true},{"text":" statement."}]},{"text":[{"text":"Push example:","bold":true},{"text":" a detergent maker giving extra margins and display allowances to distributors and supermarkets in Kano. "},{"text":"Pull example:","bold":true},{"text":" heavy TV and social media adverts for Peak Milk so shoppers ask for it by name. "},{"text":"Profile example:","bold":true},{"text":" Dangote publicising its corporate social responsibility to investors, government and communities."}]},{"text":[{"text":"Control and evaluation example:","bold":true},{"text":" six weeks after launch, a Port Harcourt restaurant checks whether awareness rose to the target and adjusts its adverts where it fell short."}]},{"text":[{"text":"Order trap: some versions list scheduling before resources. What never changes is that "},{"text":"context analysis comes first, objectives come immediately after it, and evaluation and control come last","bold":true},{"text":". Anything such as \"recruitment of factory workers\" or \"deciding the corporate mission\" is "},{"text":"not","bold":true},{"text":" an MCPF stage."}]}]}]},{"number":"2.6","title":"Budgeting methods","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Affordable method:","bold":true},{"text":" spend whatever is left after all other costs and the profit target are covered."}]},{"text":[{"text":"Percentage-of-sales method:","bold":true},{"text":" budget = percentage x sales (past or forecast sales)."}]},{"text":[{"text":"Competitive parity method:","bold":true},{"text":" match competitors' spending, or the industry's ratio of promotion to sales."}]},{"text":[{"text":"Objective-and-task method:","bold":true},{"text":" set objectives, list the tasks needed to reach them, cost each task and add them up. Budget = sum of task costs. Considered the most logical method."}]},{"text":[{"text":"Arbitrary method:","bold":true},{"text":" management simply picks a figure."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Share of voice (SOV)","bold":true},{"text":" = brand's promotion spend / total category promotion spend x 100."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Percentage of sales:","bold":true},{"t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 10, $study_guide$ext":" sales ₦500 million, 4% rule. Budget = 0.04 x ₦500,000,000 = "},{"text":"₦20,000,000","bold":true},{"text":". Weakness: it treats sales as the cause of promotion rather than the result, so budgets fall when sales fall, exactly when more promotion may be needed."}]},{"text":[{"text":"Competitive parity:","bold":true},{"text":" the industry spends 5% of sales on promotion; your sales are ₦400 million. Budget = 0.05 x ₦400,000,000 = "},{"text":"₦20,000,000","bold":true},{"text":". Weakness: it assumes competitors know best and ignores your own objectives."}]},{"text":[{"text":"Objective-and-task:","bold":true},{"text":" to raise awareness from 20% to 45%, a firm needs TV ₦12m + radio ₦4.5m + social media ₦3m + campus sampling ₦2.5m. Budget = 12 + 4.5 + 3 + 2.5 = "},{"text":"₦22 million","bold":true},{"text":". Strength: spending is tied to objectives."}]},{"text":[{"text":"Affordable:","bold":true},{"text":" expected revenue ₦120m, all other costs ₦100m, profit target ₦15m. Promotion budget = 120 - 100 - 15 = "},{"text":"₦5 million","bold":true},{"text":". Weakness: promotion is treated as a leftover, not an investment."}]},{"text":[{"text":"Share of voice:","bold":true},{"text":" your brand spends ₦20m in a category where total spend is ₦80m. SOV = 20 / 80 x 100 = "},{"text":"25%","bold":true},{"text":"."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Basic model: sender - encoding - message/medium - decoding - receiver - feedback, with noise; Schramm adds field of experience."}]},{"text":[{"text":"Linear model is one-way with a passive receiver; interactional adds feedback; transactional is simultaneous."}]},{"text":[{"text":"One-step: media direct to audience. Two-step: media - opinion leaders - followers. Multi-step: many directions."}]},{"text":[{"text":"AIDA: attention, interest, desire, action. Lavidge and Steiner: awareness, knowledge, liking, preference, conviction, purchase."}]},{"text":[{"text":"Innovation-adoption: awareness, interest, evaluation, trial, adoption. DAGMAR (Colley): awareness, comprehension, conviction, action."}]},{"text":[{"text":"Cognitive = think, affective = feel, conative = do."}]},{"text":[{"text":"MarCom process starts with identifying the target audience; objectives must be SMART; SOSTAC = situation, objectives, strategy, tactics, action, control."}]},{"text":[{"text":"MCPF: context analysis, objectives, strategy, coordinated mix, resources, scheduling and implementation, evaluation and control."}]},{"text":[{"text":"Pull = consumers; push = trade; profile = all stakeholders."}]},{"text":[{"text":"Budgets: affordable, percentage of sales, competitive parity, objective-and-task."}]}]}],"theory":{"itemId":"375505a3-1862-516c-b36b-c37951d4c922","question":[{"type":"paragraph","text":[{"text":"A Lagos snack maker had sales of ₦250 million last year and forecasts ₦300 million this year. It budgets 3% of sales for promotion. (a) Find the budget using past sales and using forecast sales. (b) If rivals together spend ₦36 million, what is the firm's share of voice using the forecast-based budget?"}]}]},"practice":[{"topic":"Models of Marketing Communication and MarCom Planning","named":false}]}},{"kind":"note","itemId":"faab1a42-3d24-5ead-bf1a-9b7dba9b0e9b","sourceKey":"guide-topic:3","position":3,"payload":{"title":"MarCom Context, Mix and Selection Criteria","body":"The four contexts of marketing communication; the tools and media of the marketing communications mix and what each does; strengths and weaknesses of each tool and the four comparison criteria; the four groups of factors for selecting the mix, plus push, pull and profile strategies, product life cycle and buyer readiness; market segmentation as it applies to communication.","noteType":"guide_topic","number":3,"mustKnow":[{"text":"The four contexts of marketing communication; the tools and media of the marketing communications mix and what each does; strengths and weaknesses of each tool and the four comparison criteria; the four groups of factors for selecting the mix, plus push, pull and profile strategies, product life cycle and buyer readiness; market segmentation as it applies to communication."}],"lessons":[{"number":"3.1","title":"The marketing communication context","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing communication context:","bold":true},{"text":" the circumstances, inside and outside the organisation, in which communication takes place and is interpreted. It is not just the words and pictures in an advert, the size of the budget or the price."}]},{"text":[{"text":"Context is analysed "},{"text":"before","bold":true},{"text":" a campaign is planned, so that tools, messages and media fit the situation."}]},{"text":[{"text":"The 4 contexts:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Customer context:","bold":true},{"text":" the needs, perceptions, attitudes and decision-making process of the target segment; who the customers are, how they buy and how they use media."}]},{"text":[{"text":"Business context:","bold":true},{"text":" the organisation's corporate and marketing strategy, its brand and market position, and its competitors and market trends in the industry."}]},{"text":[{"text":"Internal context:","bold":true},{"text":" what is inside the organisation: budget and other resources, staff skills, culture and values, internal policies and procedures."}]},{"text":[{"text":"External context:","bold":true},{"text":" forces outside the organisation's control: political, economic, social and technological ("},{"text":"PEST","bold":true},{"text":") factors and the wider stakeholders (government, media, community, investors)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal vs external trap:","bold":true},{"text":" \"company policies and procedures\", \"organisation culture and values\" and \"staff appraisals\" are "},{"text":"internal","bol$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 11, $study_guide$d":true},{"text":". \"Competitive positioning and market trends\" are "},{"text":"outside","bold":true},{"text":" the organisation: in a two-way internal/external question, they are the "},{"text":"external","bold":true},{"text":" factor. In the four-context framework they sit under the business context, while PEST and wider stakeholders are the external context."}]},{"text":[{"text":"Example: a Kano food company finds it has a small promotion budget, few staff skilled in social media and a cautious culture. All three findings concern the firm itself, so they are the "},{"text":"internal context","bold":true},{"text":"."}]},{"text":[{"text":"Example: GTBank studying how young customers choose banking apps is analysing the "},{"text":"customer context","bold":true},{"text":"; studying new regulations or rising data costs is the "},{"text":"external context","bold":true},{"text":"."}]}]}]},{"number":"3.2","title":"The marketing communications mix: tools and media","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Marketing communications mix:","bold":true},{"text":" a set of tools (disciplines) that can be used in various combinations and different degrees of intensity in order to communicate with a target audience. Its purpose is to reach and persuade the intended audience effectively across channels. The whole process of marketing is executed through it."}]},{"text":[{"text":"The 5 traditional (main) tools:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Advertising"}]},{"text":[{"text":"Sales promotion"}]},{"text":[{"text":"Personal selling"}]},{"text":[{"text":"Public relations (with publicity)"}]},{"text":[{"text":"Direct marketing"}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Media:","bold":true},{"text":" the other part of the mix: the channels in which "},{"text":"time and space can be bought or used","bold":true},{"text":" to deliver messages to target audiences (TV, radio, press, outdoor, internet)."}]},{"text":[{"text":"Price, product design, distribution and inventory are "},{"text":"not","bold":true},{"text":" communication tools. Do not confuse the communications mix (tools) with the marketing mix (4 Ps: product, price, place, promotion). Promotion is the one P that the communications mix fills out."}]}]},{"type":"paragraph","text":[{"text":"Definitions of each tool","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Advertising:","bold":true},{"text":" an "},{"text":"indirect, paid","bold":true},{"text":" method used by firms to inform customers about goods and services via television, radio, print media and online websites. One of the most widely used tools. Main job: build brand recognition and reinforce market presence through paid media."}]},{"text":[{"text":"Sales promotion:","bold":true},{"text":" aims to stimulate sales (business revenue) through "},{"text":"incentives, short-term discounts and other promotional offers","bold":true},{"text":", boosting sales and strengthening customer satisfaction. Forms: "},{"text":"coupons, rebates, paybacks, buy-one-get-one-free","bold":true},{"text":", price-offs, free samples, contests. Role: trigger "},{"text":"immediate","bold":true},{"text":" purchase."}]},{"text":[{"text":"Public relations (PR):","bold":true},{"text":" focuses on the firm's "},{"text":"reputation","bold":true},{"text":" through "},{"text":"unpaid or earned","bold":true},{"text":" communication (traditional media, social media, in-person engagement). Activities: "},{"text":"press releases, communication campaigns, crisis management","bold":true},{"text":", building positive relationships with media figures and other stakeholders. Role: enhance reputation and credibility through earned media."}]},{"text":[{"text":"Publicity:","bold":true},{"text":" promotes to the mass market like advertising "},{"text":"except that it is free","bold":true},{"text":". It appears in the news media's "},{"text":"editorial section","bold":true},{"text":" and is about "},{"text":"newsworthy","bold":true},{"text":" events. Most common forms: "},{"text":"news (press) releases, photos and feature stories","bold":true},{"text":"."}]},{"text":[{"text":"Personal selling:","bold":true},{"text":" the traditional method in which salespeople approach prospects directly and inform them about goods and services; "},{"text":"face-to-face","bold":true},{"text":" selling in which a salesperson uses skills and techniques to build personal relationships. Regarded as one of the "},{"text":"most reliable","bold":true},{"text":" modes because it is done "},{"text":"directly","bold":true},{"text":", orally face to face or in writing (emails, text messages)."}]},{"text":[{"text":"Direct marketing:","bold":true},{"text":" a "},{"text":"more personalised","bold":true},{"text":" form of communication through direct communication or distribution to "},{"text":"individuals","bold":true},{"text":", rather than generalised messages on mass media. Examples: emails, brochures, interactive consumer websites, telemarketing, catalogues, direct mail."}]}]},{"type":"paragraph","text":[{"text":"Other tools in the wider mix","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Events and experiences (sponsorship):","bold":true},{"text":" companies sponsor sports, entertainment, non-profit or community events to "},{"text":"reinforce their brand","bold":true},{"text":" in customers' minds and create a "},{"text":"long-term association","bold":true},{"text":" for brand exposure."}]},{"text":[{"text":"Interactive marketing:","bold":true},{"text":" customers "},{"text":"interact with the firm online","bold":true},{"text":" and get queries resolved online; the firm can show each customer what they chose or ordered in the recent past (Amazon is the classic example). This is the digital/interactive tool."}]},{"text":[{"text":"Word-of-mouth marketing:","bold":true},{"text":" customers "},{"text":"share their exp$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 12, $study_guide$eriences","bold":true},{"text":" of goods and services they recently bought with peers and friends. One of the most widely practised methods."}]},{"text":[{"text":"Packaging:","bold":true},{"text":" the pack itself communicates: brand name, colours, information, claims; often the last message seen before purchase."}]},{"text":[{"text":"Point of purchase (POP):","bold":true},{"text":" displays, shelf strips, posters and stands in the shop where the buying decision is made."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Advertising vs publicity:","bold":true},{"text":" both reach the mass market, but advertising is "},{"text":"paid","bold":true},{"text":" and the firm controls the message; publicity is "},{"text":"not paid for","bold":true},{"text":" and appears as "},{"text":"news","bold":true},{"text":" chosen by editors. Exams swap these constantly."}]},{"text":[{"text":"PR vs publicity:","bold":true},{"text":" PR is the broader management of reputation and relationships with all stakeholders; publicity is one output of PR (the free news coverage)."}]},{"text":[{"text":"Direct marketing vs advertising:","bold":true},{"text":" direct marketing speaks to "},{"text":"selected individuals","bold":true},{"text":" in a personalised way; advertising speaks to the general public."}]},{"text":[{"text":"Scenario practice:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Lagos water company, after an online rumour of contamination, holds a press conference, issues a press release and invites journalists on a factory tour: "},{"text":"public relations","bold":true},{"text":" (crisis management)."}]},{"text":[{"text":"A Surulere supermarket offers \"buy two packs of noodles, get a third free, this weekend only\": "},{"text":"sales promotion","bold":true},{"text":" (short-term incentive)."}]},{"text":[{"text":"An Ikeja furniture company mails brochures, each addressed by name with a reply form, to 2,000 customers on its database: "},{"text":"direct marketing","bold":true},{"text":"."}]},{"text":[{"text":"A personalised email offer to customers on a mailing list: "},{"text":"direct marketing","bold":true},{"text":"."}]},{"text":[{"text":"A telecom company such as MTN or Glo pays to put its name, logo, jerseys and banners on a university inter-faculty football competition for the season: "},{"text":"events and experiences (sponsorship)","bold":true},{"text":"."}]},{"text":[{"text":"Jumia answering customer questions online and showing each buyer their recent orders: "},{"text":"interactive marketing","bold":true},{"text":"."}]}]}]},{"text":[{"text":"A press release is "},{"text":"not","bold":true},{"text":" sales promotion; a 30-second TV commercial is "},{"text":"advertising","bold":true},{"text":", not PR."}]}]}]},{"number":"3.3","title":"Strengths, weaknesses and the comparison criteria","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Tools are compared on "},{"text":"4 criteria:","bold":true},{"text":" "},{"text":"communication effectiveness, credibility, cost and control","bold":true},{"text":". (Not SWOT, not the 4 Ps, not AIDA.)"}]},{"text":[{"text":"Absolute cost:","bold":true},{"text":" the total bill paid. "},{"text":"Relative cost (cost per contact):","bold":true},{"text":" total cost divided by the number of people reached."}]},{"text":[{"text":"Formulas:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost per contact = total cost ÷ number of people reached"}]},{"text":[{"text":"Cost per thousand (CPM) = (total cost ÷ audience reached) × 1,000"}]}]}]}]},{"type":"table","header":[[{"text":"Tool"}],[{"text":"Main strengths"}],[{"text":"Main weaknesses"}]],"rows":[[[{"text":"Advertising"}],[{"text":"Reaches a large, geographically dispersed audience at a "},{"text":"low cost per contact","bold":true},{"text":"; firm controls message, timing and media; repeats message; builds image"}],[{"text":"High absolute cost","bold":true},{"text":" (TV); largely "},{"text":"one-way and impersonal","bold":true},{"text":", cannot adapt to each person's questions; low credibility (seen as biased); clutter"}]],[[{"text":"Sales promotion"}],[{"text":"Quick, measurable sales boost; encourages trial and brand switching; attracts attention"}],[{"text":"Effects mainly "},{"text":"short-term","bold":true},{"text":"; buyers may "},{"text":"wait for deals","bold":true},{"text":"; can cheapen the brand; little help in building loyalty"}]],[[{"text":"Public relations and publicity"}],[{"text":"Highest credibility","bold":true},{"text":" (third party, such as the news media, delivers it); low cost; reaches people who avoid adverts"}],[{"text":"Least control","bold":true},{"text":": editors decide whether, when and how the story appears; no guarantee of coverage or immediate sales"}]],[[{"text":"Personal selling"}],[{"text":"Two-way","bold":true},{"text":", immediate feedback; tailored to each customer's needs; can answer objections and close the sale; builds relationships"}],[{"text":"Highest cost per contact","bold":true},{"text":"; reaches relatively "},{"text":"few","bold":true},{"text":" people; depends on salesperson quality"}]],[[{"text":"Direct marketing"}],[{"text":"Personalised and targeted; responses easily "},{"text":"measured","bold":true},{"text":"; private from competitors"}],[{"text":"Seen as intrusive "},{"text":"\"junk\"","bold":true},{"text":" mail, calls or emails; needs a good database; can be costly per contact"}]],[[{"text":"Sponsorship"}],[{"text":"Long-term brand association; reaches fans emotionally"}],[{"text":"Hard to measure; little control over the event's image"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Quick-fire rules exams use:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Most "},{"text":"credible","bold":true},{"text":": public relations (publicity)."}]},{"text":[{"text":"Least control","bold":true},{"text":": pu$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 13, $study_guide$blic relations (publicity)."}]},{"text":[{"text":"Highest cost per contact","bold":true},{"text":": personal selling."}]},{"text":[{"text":"Greatest "},{"text":"two-way interaction","bold":true},{"text":" and immediate feedback: personal selling."}]},{"text":[{"text":"Low cost per contact, wide reach","bold":true},{"text":": advertising."}]},{"text":[{"text":"Short-term sales boost","bold":true},{"text":": sales promotion."}]}]}]},{"text":[{"text":"Worked example: high absolute cost, low cost per contact.","bold":true},{"text":" A prime-time TV spot package costs ₦3,000,000 and reaches 6,000,000 viewers."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost per contact = ₦3,000,000 ÷ 6,000,000 = ₦0.50 per viewer."}]},{"text":[{"text":"CPM = ₦0.50 × 1,000 = ₦500 per thousand viewers."}]},{"text":[{"text":"The total bill (₦3m) is large, but spread across a huge audience the cost per person is tiny. That is what \"high absolute cost, low cost per contact\" means."}]}]}]},{"text":[{"text":"Worked example: personal selling.","bold":true},{"text":" A sales representative costs the firm ₦600,000 a month (salary, transport, allowances) and makes 120 calls."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Cost per contact = ₦600,000 ÷ 120 = ₦5,000 per call."}]},{"text":[{"text":"Each sales call costs ₦5,000 ÷ ₦0.50 = 10,000 times as much as one TV contact. In return, each call is two-way, tailored and can close a sale."}]}]}]},{"text":[{"text":"Worked example: direct marketing cost per response.","bold":true},{"text":" A firm mails 2,000 brochures at ₦750 each and 3% reply."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Total cost = 2,000 × ₦750 = ₦1,500,000."}]},{"text":[{"text":"Replies = 3% × 2,000 = 60."}]},{"text":[{"text":"Cost per response = ₦1,500,000 ÷ 60 = ₦25,000. Being able to count replies like this is why direct marketing is called measurable."}]}]}]},{"text":[{"text":"Small budget, wide coverage:","bold":true},{"text":" a new Yaba fashion start-up with little money gains most cheaply by sending a "},{"text":"news release about an interesting launch event","bold":true},{"text":" to local media (publicity). National TV, league sponsorship or a large sales force are far too costly."}]},{"text":[{"text":"Trap: advertising does "},{"text":"not","bold":true},{"text":" give the firm \"no control\" (it gives high control) and does "},{"text":"not","bold":true},{"text":" have a high cost per person reached."}]}]}]},{"number":"3.4","title":"Selecting the mix: factors, strategies, PLC and buyer readiness","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Selection criteria","bold":true},{"text":" are used to "},{"text":"identify and prioritise the tools that will be most effective","bold":true},{"text":" for the audience and the objectives. They do "},{"text":"not","bold":true},{"text":" mean equal budget shares, copying competitors, or dropping objectives."}]},{"text":[{"text":"Factors influencing the choice of mix (and how often each tool is used) fall into "},{"text":"4 groups:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Product related factors:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"the amount and complexity of product information to be communicated"}]},{"text":[{"text":"the stage of the product in the product life cycle"}]},{"text":[{"text":"product type and unit price"}]}]}]},{"text":[{"text":"Customer related factors:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"characteristics of the target market"}]},{"text":[{"text":"type of buying decision"}]}]}]},{"text":[{"text":"Organisation related factors:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"marketing channel adopted"}]},{"text":[{"text":"branding strategies"}]},{"text":[{"text":"budget"}]}]}]},{"text":[{"text":"Competition and situation related factors:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"visibility of the firm and its political, legal and social environment"}]},{"text":[{"text":"impact of competition"}]}]}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Push strategy:","bold":true},{"text":" communication (personal selling, trade promotions, extra margins, display allowances) is directed at "},{"text":"channel members","bold":true},{"text":" so that they stock and promote the product to end users."}]},{"text":[{"text":"Pull strategy:","bold":true},{"text":" communication (advertising, consumer promotions) is directed at "},{"text":"final consumers","bold":true},{"text":" so that they ask retailers for the product, and retailers then order from the manufacturer."}]},{"text":[{"text":"Profile strategy:","bold":true},{"text":" communication aimed at a "},{"text":"wide range of stakeholders","bold":true},{"text":" (investors, government, local community, media) to build "},{"text":"corporate reputation","bold":true},{"text":", not to move products through the channel."}]}]},{"type":"table","header":[[{"text":"PLC stage"}],[{"text":"Communication emphasis"}]],"rows":[[[{"text":"Introduction"}],[{"text":"Advertising and publicity to build "},{"text":"awareness","bold":true},{"text":"; sales promotion (samples, coupons) to encourage "},{"text":"trial","bold":true},{"text":"; personal selling to win distributors"}]],[[{"text":"Growth"}],[{"text":"Advertising and publicity continue to build preference; word of mouth spreads; less need for promotion incentives"}]],[[{"text":"Maturity"}],[{"text":"Sales promotion","bold":true},{"text":" becomes relatively more important; reminder and persuasive advertising against intense competition"}]],[[{"text":"Decline"}],[{"text":"Promotion "},{"text":"reduced to a low level","bold":true},{"text":"; some "},{"text":"reminder advertising","bold":true},{"text":" kept; publicity and selling cut back"}]]]$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 14, $study_guide$},{"type":"paragraph","text":[{"text":"Buyer readiness stages:","bold":true}]},{"type":"table","header":[[{"text":"Stage"}],[{"text":"Most cost-effective tools"}]],"rows":[[[{"text":"Awareness and knowledge"}],[{"text":"Advertising and public relations (publicity)"}]],[[{"text":"Liking, preference and conviction"}],[{"text":"Personal selling (advertising helps less)"}]],[[{"text":"Purchase (ordering, closing)"}],[{"text":"Personal selling and sales promotion"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Classification traps:","bold":true},{"text":" budget is an "},{"text":"organisation","bold":true},{"text":" factor, not product. Branding strategy is an "},{"text":"organisation","bold":true},{"text":" factor, so it is "},{"text":"not","bold":true},{"text":" a product-related factor. PLC stage is a "},{"text":"product","bold":true},{"text":" factor. Type of buying decision is a "},{"text":"customer","bold":true},{"text":" factor. Impact of competition is a "},{"text":"competition and situation","bold":true},{"text":" factor, not product."}]},{"text":[{"text":"Product type and price:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Expensive, technically complex products sold to a few buyers (medical scanners for hospitals, industrial machines, Dangote Cement supply contracts with builders): rely most on "},{"text":"personal selling","bold":true},{"text":", because the information is complex and the buyer needs explanation and negotiation."}]},{"text":[{"text":"Low-priced, frequently bought consumer goods sold to millions (soft drinks, Indomie noodles, detergents): lean most on "},{"text":"advertising and sales promotion","bold":true},{"text":", because reach and low cost per contact matter."}]}]}]},{"text":[{"text":"Push example:","bold":true},{"text":" a new seasoning brand gives Idumota wholesalers extra margins, display allowances and regular visits from sales reps so they stock it and recommend it to retailers: "},{"text":"push","bold":true},{"text":"."}]},{"text":[{"text":"Pull example:","bold":true},{"text":" a manufacturer runs heavy TV adverts and consumer coupons so consumers ask retailers for the brand, and retailers then order it: "},{"text":"pull","bold":true},{"text":"."}]},{"text":[{"text":"Profile example:","bold":true},{"text":" an oil company's annual report, community-development announcements and investor briefings: "},{"text":"profile","bold":true},{"text":"."}]},{"text":[{"text":"Many firms combine push and pull: national adverts (pull) plus distributor incentives (push)."}]},{"text":[{"text":"Other selection criteria to keep in mind: cost, control, credibility, reach, target audience, budget and objectives. A firm with an awareness objective and a mass audience picks advertising; one with a closing objective and a few big buyers picks personal selling."}]}]}]},{"number":"3.5","title":"Market segmentation and communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Market segmentation:","bold":true},{"text":" the grouping of consumers who are homogeneous in some way and then differentiating the products or brands to meet the groups' needs. Also: identifying specific market segments in a marketplace, then developing different marketing offerings that will be attractive to each segment. Equally: dividing the market of potential customers into groups by shared characteristics so a custom marketing mix can be built for each."}]},{"text":[{"text":"Why group at all: every consumer is unique, and tailoring products to each individual is very expensive."}]},{"text":[{"text":"The concept was introduced by "},{"text":"Wendell R. Smith","bold":true},{"text":" (1956)."}]},{"text":[{"text":"5 reasons for segmentation:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It is easier to meet the needs of a group than the needs of every individual in a whole market."}]},{"text":[{"text":"Meeting a group's needs better brings greater "},{"text":"loyalty, increased trial and higher perceived quality","bold":true},{"text":"."}]},{"text":[{"text":"It gives the marketer a "},{"text":"target advertising group","bold":true},{"text":", which makes advertising more "},{"text":"cost-effective","bold":true},{"text":"."}]},{"text":[{"text":"Identifying and covering the main segment can help "},{"text":"keep competition out","bold":true},{"text":" of the market."}]},{"text":[{"text":"An identified unmet need can give "},{"text":"entry into the market","bold":true},{"text":" if its segment is large and profitable."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3 bases (consumer profile):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Demographics:","bold":true},{"text":" age, income, marital status, and geography or location. This gives a focus for producing the product and communicating with consumers."}]},{"text":[{"text":"Physical needs:","bold":true},{"text":" e.g. oily or sensitive skin needing a particular cream; taste needs such as salty or sweet. Focus falls on product performance and delivery."}]},{"text":[{"text":"Lifestyle:","bold":true},{"text":" found through consumer immersion, e.g. busy career woman, diet consciousness, caring parenting. Focus falls on product performance and delivery."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"3 effects of segmentation:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"On consumers:","bold":true},{"text":" an easy, clear choice of product; consumers identify their class and buy in line with it."}]},{"text":[{"text":"On brands:","bold":true},{"text":" brands are produced for different classes, with variants such as \"mild\", \"strong\", \"smooth\" or \"extra\"."}]},{"text":[{"text":"On the marketer:","bold":true},{"text":" a focus for planning marketing activities and communication or advertising; the marketer kno$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 15, $study_guide$ws the target and directs all strategies at it."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"4 common types:","bold":true},{"text":" geographic, demographic (most common), behavioural, psychographic."}]},{"text":[{"text":"A good segment","bold":true},{"text":" is internally "},{"text":"homogeneous","bold":true},{"text":" and externally "},{"text":"heterogeneous","bold":true},{"text":": members respond alike, and differ from other segments."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Wider bases:","bold":true},{"text":" gender, age, income (high, middle, low), place, occupation, usage (heavy, medium, light), lifestyle."}]},{"text":[{"text":"Geographic:","bold":true},{"text":" by region; bottled water sells strongly where clean water is scarce. "},{"text":"Demographic:","bold":true},{"text":" age, gender, marital status, family size, income, religion, occupation, nationality. "},{"text":"Behavioural:","bold":true},{"text":" knowledge and use of the product (non-users, ex-users, potential, first-time, current users), loyalty (brand loyal, brand-neutral, competitor loyal), usage rate. "},{"text":"Psychographic:","bold":true},{"text":" personality, lifestyle and attitude."}]},{"text":[{"text":"Why segmentation matters for communication:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"It defines the "},{"text":"target audience","bold":true},{"text":", the first step in any communication plan."}]},{"text":[{"text":"It shapes the "},{"text":"message","bold":true},{"text":": a youth data plan from MTN speaks in campus slang; a premium banking product speaks of security and status."}]},{"text":[{"text":"It guides "},{"text":"media and tool choice","bold":true},{"text":": students are reached on Instagram, TikTok and campus events; older rural farmers through radio in local languages and market-day activations."}]},{"text":[{"text":"It "},{"text":"cuts waste","bold":true},{"text":": money is spent only on people likely to respond, raising conversions. That is the \"cost-effective advertising\" reason."}]}]}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Context = circumstances inside and outside the firm; 4 contexts: customer, business, internal, external (PEST and stakeholders)."}]},{"text":[{"text":"The mix = tools used in combinations and intensities; 5 traditional tools: advertising, sales promotion, personal selling, PR, direct marketing; plus media (bought or used time and space)."}]},{"text":[{"text":"Advertising = indirect, paid. Publicity = free, editorial, newsworthy. PR = reputation, earned, crisis management. Sales promotion = short-term incentives. Personal selling = face-to-face, most reliable. Direct marketing = personalised to individuals."}]},{"text":[{"text":"Extra tools: events and experiences (sponsorship), interactive marketing, word of mouth, packaging, point of purchase."}]},{"text":[{"text":"Compare tools on effectiveness, credibility, cost and control. PR is most credible but least controlled; personal selling costs most per contact and gives most feedback."}]},{"text":[{"text":"4 factor groups: product, customer, organisation, competition and situation. Budget, channel and branding = organisation."}]},{"text":[{"text":"Push = at channel members; pull = at consumers; profile = at stakeholders for reputation."}]},{"text":[{"text":"Introduction = awareness plus trial; maturity = sales promotion; decline = reminder only."}]},{"text":[{"text":"Segmentation = grouping homogeneous consumers; 5 reasons, 3 bases (demographics, physical needs, lifestyle), 3 effects (consumers, brands, marketer)."}]}]}],"theory":{"itemId":"922c23bb-5130-582c-894f-f17688cfd613","question":[{"type":"paragraph","text":[{"text":"A drinks firm compares two options. A radio campaign costs ₦2,400,000 and reaches 1,600,000 listeners. A sales team costs ₦1,800,000 and makes 300 calls on supermarket buyers. Calculate the cost per contact of each, the radio CPM, and state which tool suits building awareness and which suits closing orders."}]}]},"practice":[{"topic":"MarCom Context, Mix and Selection Criteria","named":false}]}},{"kind":"note","itemId":"890a36ca-b6aa-5862-bef9-081f35e31b61","sourceKey":"guide-topic:4","position":4,"payload":{"title":"Source, Message, Receiver and Medium; Opinion Leaders","body":"The four building blocks (source, message, receiver, medium) and how they fit the communication process; source credibility, attractiveness and power and the process each works through; message appeals, sidedness, order and conclusion drawing; the receiver's selective filters and fields of experience; personal and non-personal channels and media choice; opinion leaders, opinion formers, two-step and multi-step flow; adoption and diffusion of innovations.","noteType":"guide_topic","number":4,"mustKnow":[{"text":"The four building blocks (source, message, receiver, medium) and how they fit the communication process; source credibility, attractiveness and power and the process each works through; message appeals, sidedness, order and conclusion drawing; the receiver's selective filters and fields of experience; personal and non-personal channels and media choice; opinion leaders, opinion formers, two-step and multi-step flow; adoption and diffusion of innovations."}],"lessons":[{"number":"4.1","title":"The four building blocks and the process","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Source (sender):","bold":true},{"text":" the originator of the message, such as a brand, company or spokesperson. For it to work, the audience must see the source as "},{"text":"credible, knowledgeable and relevant","bold":true},{"text":"."}]},{"text":[{"text":"Message:","bold":true},{"text":" the crafted content intended to inform, persuade or evoke a response. An effective message is "},{"text":"clear, compelling and tailored to the audience's needs and values","bold":true},{"text":"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 16, $study_guide$; a strategically crafted one "},{"text":"connects with the audience's aspirations, problems and motivations","bold":true},{"text":"."}]},{"text":[{"text":"Receiver (audience):","bold":true},{"text":" the intended audience that "},{"text":"decodes and responds to","bold":true},{"text":" the message. Their reaction depends on "},{"text":"their own interpretation, cultural background and how relevant the message is to them","bold":true},{"text":"."}]},{"text":[{"text":"Medium (channel):","bold":true},{"text":" the channel, such as digital platforms or broadcast media, that delivers the message. It should be "},{"text":"selected to match the target audience's media preferences and habits","bold":true},{"text":"."}]},{"text":[{"text":"The interplay of source, message, receiver and medium makes up "},{"text":"the framework of the marketing communication process","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Elements of the process (9):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sender:","bold":true},{"text":" the party sending the message."}]},{"text":[{"text":"Encoding:","bold":true},{"text":" putting thought into symbols (words, pictures, music)."}]},{"text":[{"text":"Message:","bold":true},{"text":" the set of symbols sent."}]},{"text":[{"text":"Media (channel):","bold":true},{"text":" the path the message travels."}]},{"text":[{"text":"Decoding:","bold":true},{"text":" the receiver giving meaning to the symbols."}]},{"text":[{"text":"Receiver:","bold":true},{"text":" the party getting the message."}]},{"text":[{"text":"Response:","bold":true},{"text":" the receiver's reactions after exposure (e.g. awareness, liking, buying)."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" the "},{"text":"part of the receiver's response that is communicated back to the sender","bold":true},{"text":"."}]},{"text":[{"text":"Noise:","bold":true},{"text":" "},{"text":"unplanned distortion or interference","bold":true},{"text":" during the process, which can make the receiver get a different message from the one sent."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Field of experience:","bold":true},{"text":" the experiences, attitudes, values and language a person brings. Communication is most effective when the sender's and receiver's fields of experience "},{"text":"overlap","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Noise example:","bold":true},{"text":" a paint brand's radio jingle is drowned by generator sound in many homes, so listeners miss the brand name. The generator sound is "},{"text":"noise","bold":true},{"text":". Other noise: a poor network signal, a rival advert in the same break, a distracted viewer."}]},{"text":[{"text":"Feedback example:","bold":true},{"text":" after an advert runs, a firm tracks calls to its hotline, changes in sales and comments on its social media page. All are "},{"text":"feedback","bold":true},{"text":". Do not confuse feedback with response: response is everything the receiver does; feedback is only the part that returns to the sender."}]},{"text":[{"text":"Field of experience trap:","bold":true},{"text":" an advert full of Lagos teenage slang aimed at elderly rural farmers fails because there is "},{"text":"too little overlap","bold":true},{"text":" between the fields of experience of sender and receiver. That is why a firm advertising in the North may use Hausa, and in the South-West Yoruba."}]},{"text":[{"text":"The sender encodes; the receiver decodes. Exams often swap these two."}]}]}]},{"number":"4.2","title":"The source","mustKnow":[{"type":"paragraph","text":[{"text":"3 categories of source characteristics","bold":true},{"text":" (Kelman's model, used by Belch and Belch), each working through a different process:"}]},{"type":"table","header":[[{"text":"Source characteristic"}],[{"text":"What it is made of"}],[{"text":"Process of influence"}]],"rows":[[[{"text":"Credibility","bold":true}],[{"text":"expertise, trustworthiness"}],[{"text":"Internalisation","bold":true}]],[[{"text":"Attractiveness","bold":true}],[{"text":"similarity, familiarity, likability"}],[{"text":"Identification","bold":true}]],[[{"text":"Power","bold":true}],[{"text":"ability to reward or punish"}],[{"text":"Compliance","bold":true}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Expertise:","bold":true},{"text":" the knowledge, experience or skill the source is seen to have on the subject."}]},{"text":[{"text":"Trustworthiness:","bold":true},{"text":" the honesty, integrity and believability of the source; the audience's belief that the source has "},{"text":"no motive to mislead","bold":true},{"text":" them."}]},{"text":[{"text":"Internalisation:","bold":true},{"text":" the receiver accepts a credible source's view "},{"text":"because they believe the information is accurate","bold":true},{"text":", so it becomes part of their own beliefs."}]},{"text":[{"text":"Similarity:","bold":true},{"text":" the source resembles the receiver (same needs, lifestyle, background). "},{"text":"Familiarity:","bold":true},{"text":" knowing the source through exposure. "},{"text":"Likability:","bold":true},{"text":" affection for the source because of looks, behaviour or other traits."}]},{"text":[{"text":"Identification:","bold":true},{"text":" the receiver adopts the source's view because they want to be like, or relate to, the source."}]},{"text":[{"text":"Power:","bold":true},{"text":" the source can "},{"text":"administer rewards or punishments","bold":true},{"text":". The receiver goes along mainly through "},{"text":"compliance","bold":true},{"text":", which may be outward only."}]},{"text":[{"text":"Direct source:","bold":true},{"text":" a spokesperson who delivers the message or demonstrates the product. "},{"text":"Indirect source:","bold":true},{"text":" someone (e.g. a model) who delivers no message but "},{"text":"draws attention","bold":$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 17, $study_guide$true},{"text":" to and enhances the look of the advert."}]},{"text":[{"text":"Sleeper effect:","bold":true},{"text":" the persuasive impact of a message from a "},{"text":"low-credibility","bold":true},{"text":" source "},{"text":"increases over time","bold":true},{"text":", as people forget the source but remember the message."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Applications:","bold":true},{"text":" a qualified dentist in a clinic explaining how a toothpaste prevents decay = "},{"text":"expertise","bold":true},{"text":". An ordinary mother of three in a busy Lagos home, just like the women the brand targets, praising a detergent = "},{"text":"similarity","bold":true},{"text":". A popular Afrobeats star in a drink advert = attractiveness (familiarity and likability)."}]},{"text":[{"text":"Why power is rarely usable in mass advertising:","bold":true},{"text":" advertisers usually "},{"text":"cannot reward or punish consumers, nor check whether they comply","bold":true},{"text":". Power shows up more in settings such as a manager instructing staff or a big buyer pressing a supplier."}]},{"text":[{"text":"Risks of celebrity endorsers:","bold":true}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"A "},{"text":"scandal","bold":true},{"text":" involving the celebrity harms the brand's image."}]},{"text":[{"text":"Overexposure:","bold":true},{"text":" endorsing so many brands that the endorsement loses impact."}]},{"text":[{"text":"Overshadowing the product:","bold":true},{"text":" viewers remember the star but not the brand."}]},{"text":[{"text":"Mismatch","bold":true},{"text":" between the celebrity's image and the brand."}]},{"text":[{"text":"High cost","bold":true},{"text":" and loss of popularity over time."}]}]}]},{"text":[{"text":"Trap:","bold":true},{"text":" a celebrity "},{"text":"attracting attention","bold":true},{"text":" to an advert is a "},{"text":"benefit","bold":true},{"text":", not a risk."}]},{"text":[{"text":"Trust falls when the audience sees the source as paid to say it; this is why a neutral expert or a satisfied customer is often more believable than the company itself."}]}]}]},{"number":"4.3","title":"The message: appeals, sidedness and structure","mustKnow":[{"type":"paragraph","text":[{"text":"Message appeals","bold":true},{"text":" (the theme that gets the audience to respond):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Rational (informational) appeal:","bold":true},{"text":" focuses on the product's "},{"text":"features, quality, economy, value or performance","bold":true},{"text":"."}]},{"text":[{"text":"Emotional appeal:","bold":true},{"text":" stirs feelings (love, warmth, joy, pride, fear, guilt, shame) rather than giving facts."}]},{"text":[{"text":"Moral appeal:","bold":true},{"text":" directed to the audience's "},{"text":"sense of what is right and proper","bold":true},{"text":"; used for social causes (a cleaner environment, helping the needy)."}]},{"text":[{"text":"Fear appeal:","bold":true},{"text":" shows the bad consequences of not using the product or not changing behaviour."}]},{"text":[{"text":"Humour appeal:","bold":true},{"text":" uses jokes and wit to attract attention and liking."}]},{"text":[{"text":"Sex appeal:","bold":true},{"text":" uses sexual imagery or attractive models to draw attention."}]},{"text":[{"text":"Comparative advertising:","bold":true},{"text":" "},{"text":"directly or indirectly names a competitor","bold":true},{"text":" and compares the brand with it on one or more attributes."}]}]},{"type":"paragraph","text":[{"text":"Message sidedness:","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"What it does"}],[{"text":"Works best when the audience"}]],"rows":[[[{"text":"One-sided","bold":true}],[{"text":"presents "},{"text":"only positive","bold":true},{"text":" points"}],[{"text":"already favours the brand, is less educated, is unlikely to hear opposing claims"}]],[[{"text":"Two-sided","bold":true}],[{"text":"presents "},{"text":"both good and bad","bold":true},{"text":" points"}],[{"text":"is "},{"text":"well educated, initially opposed, or likely to hear competitors' counter-arguments","bold":true}]],[[{"text":"Refutational appeal","bold":true}],[{"text":"presents both sides, then "},{"text":"argues against (refutes)","bold":true},{"text":" the opposing view"}],[{"text":"faces rival claims; it builds resistance to them"}]]]},{"type":"paragraph","text":[{"text":"Message structure:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Primacy effect:","bold":true},{"text":" information presented "},{"text":"first","bold":true},{"text":" is learned best, so place the strongest arguments at the "},{"text":"beginning","bold":true},{"text":"."}]},{"text":[{"text":"Recency effect:","bold":true},{"text":" information presented "},{"text":"last","bold":true},{"text":" is remembered best, so place the strongest arguments at the "},{"text":"end","bold":true},{"text":"."}]},{"text":[{"text":"Conclusion drawing:","bold":true},{"text":" leave the conclusion "},{"text":"open","bold":true},{"text":" when the audience is "},{"text":"highly educated and highly involved","bold":true},{"text":"; state it clearly when the audience is less educated, less interested, sees the message only once, or the issue is complex."}]},{"text":[{"text":"Verbal vs visual:","bold":true},{"text":" pictures are often remembered better than words; the two should support each other."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Applications:","bold":true},{"text":" a milk advert showing a mother lovingly feeding her smiling baby = "},{"text":"emotional","bold":true},{"text":". An advert saying a generator uses less fuel per hour = "},{"text":"rational","bold":true},{"text":". A campaign urging Lagosians not to dump refuse in drains = "},{"text":"moral","bold":true},{"text":"."}]},{"text":[{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 18, $study_guide$:"Fear appeals work","bold":true},{"text":" when they show the threat "},{"text":"and give a clear, easy action","bold":true},{"text":" to avoid it (e.g. a drink-driving campaign that says \"drink, do not drive; take a ride\"). Very shocking images with no solution make people switch off. Moderate fear usually works better than extreme fear."}]},{"text":[{"text":"Humour:","bold":true},{"text":" it draws attention and liking, but the joke can "},{"text":"distract attention from the brand","bold":true},{"text":" and "},{"text":"wear out with repetition","bold":true},{"text":". It may also not translate across cultures."}]},{"text":[{"text":"Sex appeal:","bold":true},{"text":" draws attention but can distract from the brand and offend, especially in a conservative society; the product must be relevant to it."}]},{"text":[{"text":"Comparative risk:","bold":true},{"text":" consumers may get confused and credit the competitor (selective distortion; see Lesson 4.4). In Nigeria such adverts must also stay truthful and fair under the advertising code enforced by ARCON (formerly APCON)."}]},{"text":[{"text":"Sidedness traps:","bold":true},{"text":" a smartphone advert listing only positives = "},{"text":"one-sided","bold":true},{"text":". \"Some say our prices are higher; here is why that is false\" = "},{"text":"refutational","bold":true},{"text":". Two-sided messages raise credibility because the source admits a weakness."}]},{"text":[{"text":"Rational and emotional appeals are often combined, e.g. a bank advert showing a happy family (emotion) and an interest rate (reason)."}]}]}]},{"number":"4.4","title":"The receiver and the medium","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Perception:","bold":true},{"text":" the process of selecting, organising and interpreting information inputs to create meaning."}]},{"text":[{"text":"Selective perception:","bold":true},{"text":" the receiver's filtering of messages. Consumers notice only some adverts, interpret them to fit what they already believe, and remember only part of them. It has these parts:"}],"blocks":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Selective exposure:","bold":true},{"text":" choosing which messages to come into contact with (e.g. changing the channel during adverts)."}]},{"text":[{"text":"Selective attention:","bold":true},{"text":" noticing only some of the messages one is exposed to."}]},{"text":[{"text":"Selective distortion (comprehension):","bold":true},{"text":" twisting information that conflicts with one's beliefs."}]},{"text":[{"text":"Selective retention:","bold":true},{"text":" remembering information that supports one's beliefs and forgetting the rest."}]}]}]},{"text":[{"text":"Decoding","bold":true},{"text":" is done by the receiver, through their own field of experience, culture and needs."}]}]},{"type":"paragraph","text":[{"text":"Personal vs non-personal channels:","bold":true}]},{"type":"table","header":[[],[{"text":"Personal channels"}],[{"text":"Non-personal channels"}]],"rows":[[[{"text":"Meaning"}],[{"text":"two or more people communicate directly (face to face, phone, chat)"}],[{"text":"carry messages "},{"text":"without personal contact or feedback","bold":true}]],[[{"text":"Types"}],[{"text":"advocate","bold":true},{"text":" (company salespeople), "},{"text":"expert","bold":true},{"text":" (independent experts), "},{"text":"social","bold":true},{"text":" (neighbours, friends, family, associates)"}],[{"text":"major media","bold":true},{"text":" (print, broadcast, display, online), "},{"text":"atmospheres","bold":true},{"text":" (designed environments), "},{"text":"events","bold":true},{"text":" (staged occurrences)"}]],[[{"text":"Example"}],[{"text":"a salesperson's face-to-face talk with a customer"}],[{"text":"TV commercial, newspaper advert, roadside billboard"}]]]},{"type":"paragraph","text":[{"text":"Main media compared:","bold":true}]},{"type":"table","header":[[{"text":"Medium"}],[{"text":"Strengths"}],[{"text":"Weaknesses"}]],"rows":[[[{"text":"Television","bold":true}],[{"text":"sight, sound and motion; very wide mass reach"}],[{"text":"high absolute cost","bold":true},{"text":", clutter, short exposure"}]],[[{"text":"Radio","bold":true}],[{"text":"low cost, local, reaches people on the move, wide reach in Nigeria"}],[{"text":"audio only, fleeting, low attention"}]],[[{"text":"Newspapers","bold":true}],[{"text":"timely, local, believable"}],[{"text":"short life, poor reproduction"}]],[[{"text":"Magazines","bold":true}],[{"text":"specific audiences, good colour, long life"}],[{"text":"long lead time, high cost"}]],[[{"text":"Outdoor (billboards)","bold":true}],[{"text":"high repeat exposure, low cost per exposure"}],[{"text":"little selectivity, short message"}]],[[{"text":"Internet/digital","bold":true}],[{"text":"targeted, interactive, measurable, low cost"}],[{"text":"audience controls exposure, ad blocking"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Choose the medium "},{"text":"after","bold":true},{"text":" identifying the target audience, matching their media habits, and weighing "},{"text":"reach","bold":true},{"text":" (how many people), "},{"text":"frequency","bold":true},{"text":" (how often) and "},{"text":"impact","bold":true},{"text":" (quality of exposure) against cost."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Social channel example:","bold":true},{"text":" a buyer's friends, neighbours and family talk to them about a product. A pharmacist recommending a drug is an "},{"text":"expert","bold":true},{"text":" channel; a Jumia sales agent is an "},{"text":"advocate","bold":true},{"text":" channel."}]},{"text":[{"text":"Personal channels are more persuasive because they allow two-way talk and instant feedback; non-personal channels reach far more people at a lower cost per person."}]},{"text":[{"text":"Medium trap:","bold":true},{"text":" the medium should not always be the cheapest$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 19, $study_guide$, nor always TV. A firm targeting university students may favour Instagram and campus radio; one targeting market women may use radio in local languages."}]},{"text":[{"text":"Comparative advertising and selective distortion:","bold":true},{"text":" viewers may misremember which brand made the claim and credit the rival."}]}]}]},{"number":"4.5","title":"Opinion leaders, opinion formers and the flow of communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Opinion leader:","bold":true},{"text":" a person "},{"text":"within a reference group","bold":true},{"text":" who, because of "},{"text":"special skills, knowledge, personality or other characteristics","bold":true},{"text":", exerts social influence on others. A trusted person whose views and recommendations shape other people's attitudes and actions. Usually "},{"text":"not paid","bold":true},{"text":" and has no formal position."}]},{"text":[{"text":"Opinion former:","bold":true},{"text":" holds a "},{"text":"formal or professional position","bold":true},{"text":" (e.g. journalist, critic, doctor) that gives their views authority."}]},{"text":[{"text":"Opinion follower:","bold":true},{"text":" a person who seeks and accepts the views of opinion leaders."}]},{"text":[{"text":"Why opinion leaders matter:","bold":true},{"text":" they "},{"text":"increase a message's reach and credibility through their social influence","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Typical traits of opinion leaders:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"More "},{"text":"exposed to media","bold":true},{"text":" in their area of interest than their followers."}]},{"text":[{"text":"More knowledgeable and involved in the product category."}]},{"text":[{"text":"Usually from the "},{"text":"same social class","bold":true},{"text":" as their followers."}]},{"text":[{"text":"Influential in "},{"text":"specific categories","bold":true},{"text":", not all categories."}]},{"text":[{"text":"More innovative, sociable and confident."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Two-step flow model","bold":true},{"text":" (Lazarsfeld and colleagues, 1940s): information flows "},{"text":"from the mass media to opinion leaders, who then pass it on to the wider population","bold":true},{"text":"."}]},{"text":[{"text":"Multi-step flow model:","bold":true},{"text":" improves on it by recognising that "},{"text":"media reach both leaders and followers directly, and influence flows in several directions","bold":true},{"text":" (leaders to followers, followers to leaders, follower to follower)."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Leader or former?","bold":true},{"text":" Tunde, unpaid, reads technology blogs and tries new phones early, so friends in his estate ask his advice = "},{"text":"opinion leader","bold":true},{"text":". A professional food critic with a weekly newspaper column = "},{"text":"opinion former","bold":true},{"text":" (her influence comes from her formal position)."}]},{"text":[{"text":"Application of two-step flow:","bold":true},{"text":" marketers "},{"text":"target opinion leaders","bold":true},{"text":", e.g. with free samples or early access, so they spread the word. Examples: giving a new phone to tech reviewers, sampling a new seasoning cube to respected caterers."}]},{"text":[{"text":"Traps:","bold":true},{"text":" opinion leaders do not remove the need for paid advertising, do not control distribution, and are not equally influential across all categories. A fashion leader may know nothing about cars."}]},{"text":[{"text":"The two-step model was criticised because followers also get information straight from the media; this led to the multi-step model."}]}]}]},{"number":"4.6","title":"Adoption and diffusion of innovations","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Adoption process:","bold":true},{"text":" the "},{"text":"mental process an individual goes through","bold":true},{"text":" from first hearing about an innovation to finally adopting it. Stages (Kotler): "},{"text":"awareness, interest, evaluation, trial, adoption","bold":true},{"text":"."}]},{"text":[{"text":"Diffusion of innovation:","bold":true},{"text":" the "},{"text":"spread of an innovation through a whole market over time","bold":true},{"text":" (Everett Rogers)."}]}]},{"type":"paragraph","text":[{"text":"5 adopter categories, first to last","bold":true},{"text":" (Rogers):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Innovators","bold":true},{"text":" (2.5%): venturesome, take risks."}]},{"text":[{"text":"Early adopters","bold":true},{"text":" (13.5%): guided by respect; "},{"text":"opinion leaders","bold":true},{"text":" in their community."}]},{"text":[{"text":"Early majority","bold":true},{"text":" (34%): deliberate; adopt before the average person."}]},{"text":[{"text":"Late majority","bold":true},{"text":" (34%): sceptical; adopt after most people have."}]},{"text":[{"text":"Laggards","bold":true},{"text":" (16%): "},{"text":"tradition-bound, suspicious of change","bold":true},{"text":", adopt only when the innovation has become something of a tradition itself."}]}]},{"type":"paragraph","text":[{"text":"5 characteristics affecting the rate of adoption:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Relative advantage:","bold":true},{"text":" how much better it seems than what exists."}]},{"text":[{"text":"Compatibility:","bold":true},{"text":" how well it fits the values and experiences of users."}]},{"text":[{"text":"Complexity:","bold":true},{"text":" how hard it is to understand or use (more complex = slower)."}]},{"text":[{"text":"Divisibility (trialability):","bold":true},{"text":" whether it can be tried on a small scale."}]},{"text":[{"text":"Communicability (observability):","bold":true},{"text":" how easily its results can $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 20, $study_guide$be seen or described to others."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Relative advantage example:","bold":true},{"text":" mobile money spread quickly in Nigeria partly because users saw it as clearly better than queuing in banking halls to send money."}]},{"text":[{"text":"Trap:","bold":true},{"text":" adoption is about "},{"text":"one individual","bold":true},{"text":"; diffusion is about the "},{"text":"whole market","bold":true},{"text":". Grouping buyers into innovators, early adopters and so on is the adopter categorisation, not the adoption process."}]},{"text":[{"text":"Order trap:","bold":true},{"text":" innovators come "},{"text":"before","bold":true},{"text":" early adopters. Memory aid: I-E-E-L-L (Innovators, Early adopters, Early majority, Late majority, Laggards)."}]},{"text":[{"text":"Worked example:","bold":true},{"text":" a fintech app targets 400,000 potential users. Using Rogers' percentages:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Innovators: 2.5% of 400,000 = 0.025 x 400,000 = 10,000"}]},{"text":[{"text":"Early adopters: 13.5% x 400,000 = 54,000"}]},{"text":[{"text":"Early majority: 34% x 400,000 = 136,000"}]},{"text":[{"text":"Late majority: 34% x 400,000 = 136,000"}]},{"text":[{"text":"Laggards: 16% x 400,000 = 64,000"}]},{"text":[{"text":"Check: 10,000 + 54,000 + 136,000 + 136,000 + 64,000 = 400,000. The first two groups together = 16% = 64,000 people, the group to win first because early adopters lead opinion."}]}]}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Source, message, receiver and medium together form the framework of the marketing communication process."}]},{"text":[{"text":"Noise = unplanned interference; feedback = the part of the response sent back; overlap of fields of experience aids understanding."}]},{"text":[{"text":"Source characteristics: credibility (expertise, trustworthiness) to internalisation; attractiveness (similarity, familiarity, likability) to identification; power to compliance."}]},{"text":[{"text":"Sleeper effect: a low-credibility source's message gains impact over time."}]},{"text":[{"text":"Appeals: rational, emotional, moral, fear, humour, sex, comparative. Fear needs a clear way out."}]},{"text":[{"text":"Two-sided for educated, opposed or counter-argued audiences; refutational = both sides plus rebuttal; primacy = strongest first; open conclusion for educated, involved audiences."}]},{"text":[{"text":"Selective exposure, attention, distortion and retention make up selective perception."}]},{"text":[{"text":"Personal channels: advocate, expert, social. Non-personal: media, atmospheres, events."}]},{"text":[{"text":"Opinion leader = informal peer; opinion former = formal position. Two-step: media to leaders to others; multi-step: many directions."}]},{"text":[{"text":"Adopters: innovators, early adopters (opinion leaders), early majority, late majority, laggards."}]}]}],"theory":{"itemId":"fae777aa-140e-58e7-bab6-c1817b21c519","question":[{"type":"paragraph","text":[{"text":"Name the three categories of source characteristics and state the process through which each influences the receiver, with one example each."}]}]},"practice":[{"topic":"Source, Message, Receiver, Medium and Opinion Leaders","named":false}]}},{"kind":"note","itemId":"e52f06c3-d074-5d3f-b72e-271f5628d4ce","sourceKey":"guide-topic:5","position":5,"payload":{"title":"Communication, Business Communication and the Communication Process","body":"The meaning, origin, importance and 7 Cs of communication; what business communication is, its purposes and examples; the forms of business communication (internal/external, formal/informal and the grapevine, upward/downward/horizontal/diagonal, verbal/non-verbal, oral/written, visual); the elements of the communication process; the Lasswell, Shannon-Weaver, Schramm and transactional models; barriers to communication and how to overcome them.","noteType":"guide_topic","number":5,"mustKnow":[{"text":"The meaning, origin, importance and 7 Cs of communication; what business communication is, its purposes and examples; the forms of business communication (internal/external, formal/informal and the grapevine, upward/downward/horizontal/diagonal, verbal/non-verbal, oral/written, visual); the elements of the communication process; the Lasswell, Shannon-Weaver, Schramm and transactional models; barriers to communication and how to overcome them."}],"lessons":[{"number":"5.1","title":"Meaning, importance and principles of communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Origin:","bold":true},{"text":" \"communication\" comes from the Latin word "},{"text":"communis","bold":true},{"text":", meaning "},{"text":"common","bold":true},{"text":". To communicate is to create a "},{"text":"common (shared) understanding","bold":true},{"text":" between people."}]},{"text":[{"text":"Communication:","bold":true},{"text":" the process of "},{"text":"transmitting information and shared meaning from one person or group to another person or group","bold":true},{"text":". It is also the exchange of thoughts or conversation through written words, verbal conversation, electronic or digital media and social media to exchange ideas and information for a pre-planned purpose, or the process of using words, sounds or visual cues to supply information to one or more people."}]},{"text":[{"text":"Effective communication:","bold":true},{"text":" occurs when the "},{"text":"meaning understood by the receiver matches the meaning intended by the sender","bold":true},{"text":". Sending a message is not enough; it must be understood."}]},{"text":[{"text":"One-way communication:","bold":true},{"text":" the message flows from sender to receiver with no immediate reply, e.g. a "},{"text":"roadside billboard","bold":true},{"text":", a radio jingle, a printed notice."}]},{"text":[{"text":"Two-way communication:","bold":true},{"text"$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 21, $study_guide$:" the receiver can reply, so there is feedback, e.g. a telephone call, a face-to-face sales negotiation, a question-and-answer session."}]}]},{"type":"paragraph","text":[{"text":"Importance of communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Passes information and instructions."}]},{"text":[{"text":"Coordinates the work of people and departments."}]},{"text":[{"text":"Supports planning, decision-making and control."}]},{"text":[{"text":"Persuades and motivates (customers, staff, investors)."}]},{"text":[{"text":"Builds relationships and trust with stakeholders."}]},{"text":[{"text":"Is the base of all marketing: without communication a firm cannot tell buyers what it offers."}]}]},{"type":"paragraph","text":[{"text":"The 7 Cs of effective communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Clarity:","bold":true},{"text":" one clear idea, plain familiar words."}]},{"text":[{"text":"Conciseness:","bold":true},{"text":" say it in as few words as needed; no repetition."}]},{"text":[{"text":"Concreteness:","bold":true},{"text":" specific facts and figures, not vague claims."}]},{"text":[{"text":"Correctness:","bold":true},{"text":" accurate facts, correct grammar and spelling, right level of language."}]},{"text":[{"text":"Completeness:","bold":true},{"text":" all the information the receiver needs to act."}]},{"text":[{"text":"Consideration:","bold":true},{"text":" see things from the receiver's side (the \"you\" attitude)."}]},{"text":[{"text":"Courtesy:","bold":true},{"text":" polite, respectful, sincere tone."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Some versions of the list replace "},{"text":"consideration","bold":true},{"text":" with "},{"text":"coherence","bold":true},{"text":" (logical, connected ideas). If an exam offers coherence as one of the 7 Cs, accept it; \"complexity\", \"cost\" or \"confusion\" are never among the 7 Cs."}]},{"text":[{"text":"Concreteness example:","bold":true},{"text":" \"Our data is cheap\" is vague; \"₦1,000 for 1.5GB, valid 30 days\" is concrete."}]},{"text":[{"text":"Effectiveness trap:","bold":true},{"text":" an option saying communication is effective \"once the sender has transmitted the message, whether or not it is understood\" is wrong. Effectiveness is judged at the receiver's end."}]},{"text":[{"text":"A billboard on the Third Mainland Bridge is one-way: drivers cannot reply to it. A customer chatting with a bank's agent on the phone is two-way."}]}]}]},{"number":"5.2","title":"Business communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Business communication:","bold":true},{"text":" the "},{"text":"exchange of information between people within and outside an organisation in order to achieve the organisation's goals","bold":true},{"text":". It covers both internal (staff, departments) and external (customers, suppliers, investors, government, media) audiences, and both written and oral forms."}]}]},{"type":"paragraph","text":[{"text":"Purposes of business communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"To "},{"text":"inform","bold":true},{"text":" employees and customers about decisions, policies and offers."}]},{"text":[{"text":"To "},{"text":"persuade","bold":true},{"text":" customers and other stakeholders to take action."}]},{"text":[{"text":"To "},{"text":"coordinate","bold":true},{"text":" the work of different departments."}]},{"text":[{"text":"To "},{"text":"instruct and direct","bold":true},{"text":" staff."}]},{"text":[{"text":"To "},{"text":"build relationships and goodwill","bold":true},{"text":" with internal and external stakeholders."}]},{"text":[{"text":"To get "},{"text":"feedback","bold":true},{"text":" and information for decisions."}]}]},{"type":"paragraph","text":[{"text":"Examples of business communication:","bold":true},{"text":" analytical reports circulated to stakeholders; presentations used to align a team on its objectives; oral discussions during meetings; memos, circulars and letters; emails; press releases; staff newsletters; advertisements; non-verbal cues (body language, dress, punctuality) that shape how stakeholders see a firm."}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"What is NOT business communication:","bold":true},{"text":" building a prototype, machine maintenance, counting stock, manufacturing, product design, financial forecasting, budget allocation, auditing and recruitment are business "},{"text":"activities","bold":true},{"text":", not communication. The report or presentation "},{"text":"about","bold":true},{"text":" them is communication."}]},{"text":[{"text":"Trap options:","bold":true},{"text":" \"communication only among employees\" (too narrow, ignores external), \"messages sent only to customers\" (too narrow, ignores internal), \"only written letters and memos\" (ignores oral and non-verbal). The complete definition says "},{"text":"within and outside","bold":true},{"text":" the organisation, "},{"text":"to achieve its goals","bold":true},{"text":"."}]},{"text":[{"text":"\"To remove the need for planning and organising\" is "},{"text":"not","bold":true},{"text":" a purpose. Communication supports planning; it never replaces it."}]},{"text":[{"text":"Strategic role:","bold":true},{"text":" the communication process helps a business "},{"text":"build relationships with internal and external stakeholders","bold":true},{"text":". Cutting contact with customers, lowering quality or restricting supply are not things communication supports."}]},{"text":[{"text":"Example: when GTBank announces a new feature, it informs customers (external), briefs branch staff (internal) and issues a press release to newspapers (external, through the media)."}]}]}]},{"number":"5.3","title":"Forms of business communication","mustKnow":[{"type":"paragraph","text":[{"text$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 22, $study_guide$":"1. By audience: internal vs external","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Internal:","bold":true},{"text":" within the organisation, e.g. "},{"text":"staff newsletter","bold":true},{"text":", memo, circular, staff meeting, intranet notice."}]},{"text":[{"text":"External:","bold":true},{"text":" with people outside, e.g. "},{"text":"press release","bold":true},{"text":", advertisement, billboard, letter to a supplier, product launch press conference, customer email."}]}]},{"type":"paragraph","text":[{"text":"2. By official status: formal vs informal","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Formal:","bold":true},{"text":" follows "},{"text":"official channels and lines of authority","bold":true},{"text":" set by the organisation (chain of command), e.g. reports, memos, official meetings."}]},{"text":[{"text":"Informal:","bold":true},{"text":" spreads through friendships and casual conversation, outside official lines. Its main network is the "},{"text":"grapevine","bold":true},{"text":"."}]},{"text":[{"text":"Grapevine:","bold":true},{"text":" the informal network through which "},{"text":"news and rumours spread among employees outside official channels","bold":true},{"text":"."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Advantages: spreads information "},{"text":"very quickly","bold":true},{"text":"; shows managers staff feelings; builds social bonds; fills gaps when formal communication is slow."}]},{"text":[{"text":"Disadvantages: messages are often "},{"text":"distorted","bold":true},{"text":" and can spread "},{"text":"false rumours","bold":true},{"text":"; no one controls it; leaves no official record; can damage morale."}]}]}]}]},{"type":"paragraph","text":[{"text":"3. By direction","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Downward:","bold":true},{"text":" from superiors to subordinates, e.g. MD's circular on new resumption time, a supervisor's instructions, job descriptions, policy memos."}]},{"text":[{"text":"Upward:","bold":true},{"text":" from subordinates to superiors, e.g. weekly sales reports, "},{"text":"suggestion box","bold":true},{"text":", complaints, feedback surveys, requests."}]},{"text":[{"text":"Horizontal (lateral):","bold":true},{"text":" between people "},{"text":"at the same level","bold":true},{"text":", e.g. marketing manager and production manager agreeing a launch date."}]},{"text":[{"text":"Diagonal (crosswise):","bold":true},{"text":" between people at "},{"text":"different levels in different departments","bold":true},{"text":", e.g. a sales officer contacting the finance manager directly."}]}]},{"type":"paragraph","text":[{"text":"4. By mode: verbal vs non-verbal (and visual)","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Verbal","bold":true},{"text":" uses words: "},{"text":"oral","bold":true},{"text":" (spoken: meetings, phone calls, presentations, interviews) and "},{"text":"written","bold":true},{"text":" (letters, memos, reports, emails, agreements, brochures)."}]},{"text":[{"text":"Non-verbal","bold":true},{"text":" uses no words:"}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Kinesics:","bold":true},{"text":" body movements: gestures, posture, facial expressions, eye contact."}]},{"text":[{"text":"Paralanguage:","bold":true},{"text":" how the voice is used: tone, pitch, speed, volume."}]},{"text":[{"text":"Proxemics:","bold":true},{"text":" use of personal space and distance."}]},{"text":[{"text":"Chronemics:","bold":true},{"text":" use of time (punctuality, lateness, waiting)."}]},{"text":[{"text":"Haptics:","bold":true},{"text":" touch (handshake, pat on the back)."}]},{"text":[{"text":"Appearance and artefacts:","bold":true},{"text":" dress, grooming, office layout."}]}]}]},{"text":[{"text":"Visual:","bold":true},{"text":" charts, graphs, pictures, logos, signs, videos, infographics."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Oral"}],[{"text":"Written"}]],"rows":[[[{"text":"Feedback"}],[{"text":"Immediate, with clarification"}],[{"text":"Delayed"}]],[[{"text":"Record"}],[{"text":"None (unless recorded)"}],[{"text":"Permanent record; can serve as evidence"}]],[[{"text":"Speed"}],[{"text":"Fast"}],[{"text":"Slower to prepare"}]],[[{"text":"Editing"}],[{"text":"Little chance to edit"}],[{"text":"Can be checked and edited before sending"}]],[[{"text":"Best for"}],[{"text":"Discussion, quick decisions, sensitive talks"}],[{"text":"Contracts, policies, legal and long messages"}]],[[{"text":"Weakness"}],[{"text":"Easily forgotten or denied"}],[{"text":"Costly in time; no tone of voice"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Channel richness","bold":true},{"text":" (Daft and Lengel): a channel's ability to carry several cues at once (words, tone, face) and give immediate feedback. From richest to leanest: "},{"text":"face-to-face meeting","bold":true},{"text":", telephone or video call, personal email or letter, impersonal written notice, formal report or bulletin. Use rich channels for complex or sensitive messages and lean channels for routine ones."}]},{"text":[{"text":"Written for disputes:","bold":true},{"text":" a Kano distributor agreeing ₦5 million credit payable in 60 days should use a "},{"text":"signed written agreement","bold":true},{"text":", because it creates a permanent record that can be relied on if a dispute arises. A phone call or the grapevine gives no proof."}]},{"text":[{"text":"Non-verbal traps:","bold":true},{"text":" a smile and firm handshake are non-verbal (kinesics plus haptics); tone of voice is non-verbal (paralanguage); dress is non-verbal. A "},{"text":"memo","bold":true},{"text":" is written verbal communication, not non-verbal. A telephone conversation is oral."}]},{"text":[{"text":"Chronemics example:","bold":true},{"text":" a supplier keeps a client waiting two hours $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 23, $study_guide$past the meeting time in Abuja. The client reads it as \"they do not value my business\". The message was sent through the use of time."}]},{"text":[{"text":"Direction trap:","bold":true},{"text":" the suggestion box is "},{"text":"upward","bold":true},{"text":", even though management set it up. A job description given to a new employee is "},{"text":"downward","bold":true},{"text":". Two managers at the same level talking is "},{"text":"horizontal","bold":true},{"text":", not diagonal."}]},{"text":[{"text":"Internal vs external trap:","bold":true},{"text":" a press release goes to newspapers and the public, so it is "},{"text":"external","bold":true},{"text":" even if staff also read it. A letter of complaint to a supplier is external."}]}]}]},{"number":"5.4","title":"The communication process and its elements","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communication process:","bold":true},{"text":" an idea is "},{"text":"encoded","bold":true},{"text":" into a message, "},{"text":"transmitted through a channel","bold":true},{"text":" and "},{"text":"decoded by the receiver","bold":true},{"text":", who responds and sends feedback, with noise able to interfere at any point."}]},{"text":[{"text":"Basic business model:","bold":true},{"text":" "},{"text":"sender, message, channel, receiver and feedback","bold":true},{"text":" (with encoding, decoding and noise added in the full model)."}]}]},{"type":"paragraph","text":[{"text":"Elements of the process:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Sender (source):","bold":true},{"text":" the person or organisation that "},{"text":"has an idea to share and starts","bold":true},{"text":" the communication."}]},{"text":[{"text":"Encoding:","bold":true},{"text":" "},{"text":"putting thoughts or ideas into symbolic form","bold":true},{"text":", such as words, pictures, music or sounds."}]},{"text":[{"text":"Message:","bold":true},{"text":" the "},{"text":"set of words, pictures, sounds or symbols","bold":true},{"text":" that the sender transmits."}]},{"text":[{"text":"Channel (medium):","bold":true},{"text":" the "},{"text":"means or path through which the message travels","bold":true},{"text":" from sender to receiver, e.g. radio, TV, email, SMS, a face-to-face meeting."}]},{"text":[{"text":"Decoding:","bold":true},{"text":" the process by which the "},{"text":"receiver assigns meaning to (interprets) the symbols","bold":true},{"text":" sent by the sender."}]},{"text":[{"text":"Receiver:","bold":true},{"text":" the "},{"text":"person or group the message is intended for, who decodes it","bold":true},{"text":"."}]},{"text":[{"text":"Response:","bold":true},{"text":" the "},{"text":"receiver's reaction","bold":true},{"text":" after receiving the message."}]},{"text":[{"text":"Feedback:","bold":true},{"text":" the "},{"text":"part of the receiver's response that is communicated back to the sender","bold":true},{"text":". It shows the sender how the message was received so it can be "},{"text":"corrected or refined","bold":true},{"text":"."}]},{"text":[{"text":"Noise:","bold":true},{"text":" "},{"text":"any unplanned interference or distortion","bold":true},{"text":" that prevents the message from being received as intended. It can occur at any stage."}]},{"text":[{"text":"Field of experience:","bold":true},{"text":" the background, knowledge, culture, language and experience each party brings. Communication works best when the sender's and receiver's fields of experience "},{"text":"overlap","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Full Nigerian walk-through:","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"A Lagos cement company ("},{"text":"sender","bold":true},{"text":") wants buyers to see its brand as strong and durable."}]},{"text":[{"text":"With an agency it turns this into a TV script showing a building standing firm in heavy rain ("},{"text":"encoding","bold":true},{"text":")."}]},{"text":[{"text":"The finished advert ("},{"text":"message","bold":true},{"text":") runs on TV ("},{"text":"channel","bold":true},{"text":")."}]},{"text":[{"text":"A viewer in Ibadan sees it and concludes \"this cement lasts\" ("},{"text":"decoding","bold":true},{"text":"); the viewer is the "},{"text":"receiver","bold":true},{"text":"."}]},{"text":[{"text":"The viewer's interest and later purchase is the "},{"text":"response","bold":true},{"text":"."}]},{"text":[{"text":"Calls to the company and rising orders reported by dealers are "},{"text":"feedback","bold":true},{"text":"."}]},{"text":[{"text":"A power cut in the middle of the advert is "},{"text":"noise","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Decoding example:","bold":true},{"text":" a viewer watches a soft drink advert of friends laughing at a party and concludes the drink is for happy social occasions. Interpreting the meaning is decoding."}]},{"text":[{"text":"Noise example:","bold":true},{"text":" a trader at Balogun Market cannot hear a bank's radio jingle because of a loud generator. The generator sound is noise. Noise is "},{"text":"not","bold":true},{"text":" the loud music inside the advert itself, and it is not the channel."}]},{"text":[{"text":"Feedback example:","bold":true},{"text":" a telecoms company sends an SMS offering a ₦1,000 data bundle. Customers who reply \"YES\" and those who call the helpline with questions are giving "},{"text":"feedback","bold":true},{"text":"."}]},{"text":[{"text":"Response vs feedback:","bold":true},{"text":" response is the receiver's whole reaction (some silent, like liking the brand); feedback is only the part that reaches the sender."}]},{"text":[{"text":"Encoding vs decoding:","bold":true},{"text":" the sender encodes, the receiver decodes. Exams swap them often."}]},{"text":[{"text":"Not an element:","bold":true},{"text":" budget, price, product, AIDA stages and the promotion mix tools$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 24, $study_guide$ are "},{"text":"not","bold":true},{"text":" elements of the communication process model. \"Product, price, place and promotion\" is the marketing mix; \"attention, interest, desire, action\" is AIDA; \"advertising, sales promotion, PR, personal selling\" is the promotion mix."}]},{"text":[{"text":"An effective process ensures messages are "},{"text":"crafted, delivered and interpreted with clarity and purpose","bold":true},{"text":". Ignoring the receiver or blocking feedback makes communication fail."}]}]}]},{"number":"5.5","title":"Models of communication","mustKnow":[{"type":"table","header":[[{"text":"Model"}],[{"text":"Author and date"}],[{"text":"Type"}],[{"text":"Key idea"}]],"rows":[[[{"text":"Lasswell's formula"}],[{"text":"Harold Lasswell, 1948","bold":true}],[{"text":"Linear"}],[{"text":"\""},{"text":"Who says what, in which channel, to whom, with what effect?","bold":true},{"text":"\""}]],[[{"text":"Shannon-Weaver"}],[{"text":"Claude Shannon and Warren Weaver, 1949","bold":true}],[{"text":"Linear (one-way)"}],[{"text":"Built from work on "},{"text":"telephone signals","bold":true},{"text":" at Bell Labs; introduced "},{"text":"noise","bold":true}]],[[{"text":"Schramm (Osgood-Schramm)"}],[{"text":"Wilbur Schramm, 1954","bold":true}],[{"text":"Interactive (circular)"}],[{"text":"Both parties encode and decode in turns; "},{"text":"feedback","bold":true},{"text":" and "},{"text":"field of experience","bold":true}]],[[{"text":"Transactional"}],[{"text":"Dean Barnlund, 1970"}],[{"text":"Transactional"}],[{"text":"Both parties "},{"text":"send and receive at the same time","bold":true},{"text":", continuously"}]]]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Linear model:","bold":true},{"text":" one-way flow from sender to a passive receiver. Elements in Shannon-Weaver: information source, transmitter (encoder), channel, receiver (decoder), destination, plus "},{"text":"noise source","bold":true},{"text":". "},{"text":"Main weakness: no feedback","bold":true},{"text":" from the receiver."}]},{"text":[{"text":"Interactive model:","bold":true},{"text":" two-way; the receiver sends feedback, so communication is a cycle. Meaning is shared only where the two "},{"text":"fields of experience overlap","bold":true},{"text":"."}]},{"text":[{"text":"Transactional model:","bold":true},{"text":" communication is a "},{"text":"continuous process in which both parties send and receive messages at the same time","bold":true},{"text":" (e.g. a speaker reads the listener's face while still talking). Both are \"communicators\"; noise and context still apply."}]}]},{"type":"paragraph","text":[{"text":"Why the communication model is useful to a business:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"It "},{"text":"explains how organisational messages are sent and received","bold":true},{"text":"."}]},{"text":[{"text":"It helps "},{"text":"identify barriers","bold":true},{"text":" (noise) that can stop a message being delivered and understood."}]},{"text":[{"text":"It shows the need to "},{"text":"know the target audience","bold":true},{"text":" and its field of experience."}]},{"text":[{"text":"It stresses "},{"text":"feedback","bold":true},{"text":" for checking and refining messages."}]},{"text":[{"text":"It guides choice of "},{"text":"channel","bold":true},{"text":" and message design."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Lasswell's five questions map onto the elements:","bold":true},{"text":" who = sender; says what = message; in which channel = channel; to whom = receiver; with what effect = effect/response. The quote is Lasswell's, not Kotler's, Schramm's or Shannon and Weaver's."}]},{"text":[{"text":"Shannon and Weaver trap:","bold":true},{"text":" the 1949 model came from engineering (signals on telephone lines), so \"noise\" first meant static on a line. AIDA is a response model (Topic 2), not a communication process model."}]},{"text":[{"text":"Schramm's contribution:","bold":true},{"text":" communication is two-way and depends on shared experience. A Hausa-language radio advert in Kano works because it overlaps the listeners' field of experience."}]},{"text":[{"text":"A model "},{"text":"never guarantees","bold":true},{"text":" that every message will be understood, does not fix prices and does not remove the need to know the audience."}]},{"text":[{"text":"Linear vs transactional:","bold":true},{"text":" a billboard fits the linear model; a live sales negotiation, where both sides talk, watch and react at once, fits the transactional model."}]}]}]},{"number":"5.6","title":"Barriers to communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Barrier:","bold":true},{"text":" anything that blocks, distorts or delays a message so that the receiver's meaning differs from the sender's."}]}]},{"type":"paragraph","text":[{"text":"Types of barriers:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Physical:","bold":true},{"text":" environmental noise (generators, traffic), distance, poor network, faulty equipment, poor lighting."}]},{"text":[{"text":"Semantic (language):","bold":true},{"text":" "},{"text":"jargon","bold":true},{"text":", technical terms, ambiguous words, different languages, poor translation."}]},{"text":[{"text":"Psychological (emotional):","bold":true},{"text":" anger, fear, stress, anxiety, distrust, prejudice that stop a person listening."}]},{"text":[{"text":"Perceptual:","bold":true},{"text":" "},{"text":"selective exposure","bold":true},{"text":" (seeing only some messages), "},{"text":"selective perception","bold":true},{"text":" (noticing and interpreting messages to fit existing beliefs), "},{"text":"selective retention","bold":true},{"text":" (remembering mainly what supports existing beliefs)."}]},{"text":[{"text":"Cultural:","bold":true},{"text":" differences in values, gestures, customs and language betw$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 25, $study_guide$een groups or countries."}]},{"text":[{"text":"Organisational (status):","bold":true},{"text":" too many levels of authority, rigid rules, status gaps, poor structure; junior staff fear speaking to top management."}]},{"text":[{"text":"Information overload:","bold":true},{"text":" receiving more messages than one can process, so important ones are missed or read late."}]},{"text":[{"text":"Poor listening and lack of feedback.","bold":true}]}]},{"type":"paragraph","text":[{"text":"How to overcome barriers:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Use "},{"text":"simple, clear language","bold":true},{"text":" suited to the receiver; avoid jargon."}]},{"text":[{"text":"Encourage feedback","bold":true},{"text":" to check understanding; ask questions."}]},{"text":[{"text":"Practise "},{"text":"active listening","bold":true},{"text":"."}]},{"text":[{"text":"Choose the "},{"text":"right channel","bold":true},{"text":" and timing; use rich channels for complex messages."}]},{"text":[{"text":"Understand the receiver's "},{"text":"culture and field of experience","bold":true},{"text":"."}]},{"text":[{"text":"Reduce physical noise and fix equipment."}]},{"text":[{"text":"Cut unnecessary levels of authority; keep an open-door policy."}]},{"text":[{"text":"Prioritise and filter messages to reduce overload."}]},{"text":[{"text":"Control emotions; wait for a calm moment."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Semantic:","bold":true},{"text":" an insurance agent explains a policy to market women in Aba using \"indemnity\", \"actuarial loading\" and \"subrogation\". They leave confused. Jargon is a semantic barrier."}]},{"text":[{"text":"Psychological:","bold":true},{"text":" a customer wrongly debited is so angry he does not listen to the bank officer. Emotion is the barrier."}]},{"text":[{"text":"Cultural:","bold":true},{"text":" a foreign firm's advert uses a hand gesture friendly at home but rude to many Nigerians. This is cultural, not semantic (no jargon is involved)."}]},{"text":[{"text":"Information overload:","bold":true},{"text":" a bank officer gets over 200 emails a day and misses her manager's messages."}]},{"text":[{"text":"Organisational:","bold":true},{"text":" junior staff of a large Lagos firm fear reporting problems to the MD because of many levels and his high status."}]},{"text":[{"text":"Selective perception vs selective retention:","bold":true},{"text":" perception is how you "},{"text":"notice and interpret","bold":true},{"text":" a message now; retention is what you "},{"text":"remember","bold":true},{"text":" later. A loyal Indomie buyer who notices only the good points of an Indomie advert shows selective perception; one who later forgets a rival noodle brand's price cut shows selective retention."}]},{"text":[{"text":"Not a barrier:","bold":true},{"text":" active listening is a cure, not a barrier. Physical noise, jargon and emotional stress are all barriers."}]},{"text":[{"text":"Best cure trap:","bold":true},{"text":" using more technical terms, avoiding the receiver's questions or blasting one message through every channel at once do not overcome barriers. Simple language plus feedback does."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communication comes from Latin "},{"text":"communis","bold":true},{"text":" (common): transmitting information and shared meaning; effective when the receiver's meaning matches the sender's."}]},{"text":[{"text":"7 Cs: clarity, conciseness, concreteness, correctness, completeness, consideration, courtesy."}]},{"text":[{"text":"Business communication = exchange of information "},{"text":"within and outside","bold":true},{"text":" the organisation to achieve its goals; purposes: inform, persuade, coordinate, instruct, build relationships."}]},{"text":[{"text":"Forms: internal/external; formal/informal (grapevine: fast but distorted); downward, upward, horizontal, diagonal; oral, written, non-verbal, visual."}]},{"text":[{"text":"Non-verbal: kinesics (body), paralanguage (voice), proxemics (space), chronemics (time), haptics (touch)."}]},{"text":[{"text":"Oral gives immediate feedback; written gives a permanent record. Face-to-face is the richest channel."}]},{"text":[{"text":"Process: sender, encoding, message, channel, decoding, receiver, response, feedback, noise, field of experience."}]},{"text":[{"text":"Models: Lasswell 1948 (who says what...), Shannon-Weaver 1949 (linear, noise, no feedback), Schramm 1954 (interactive, field of experience), transactional (simultaneous sending and receiving)."}]},{"text":[{"text":"Barriers: physical, semantic, psychological, perceptual, cultural, organisational, information overload; cure with simple language and feedback."}]}]}],"theory":{"itemId":"c9a5202d-1616-506e-a213-b4b275bba75d","question":[{"type":"paragraph","text":[{"text":"Using a Nigerian example, explain the elements of the communication process and show two points at which noise can occur."}]}]},"practice":[{"topic":"Communication, Business Communication and the Communication Process","named":false}]}},{"kind":"note","itemId":"c4d68f51-fe6b-5f7d-b82b-5182b349591f","sourceKey":"guide-topic:6","position":6,"payload":{"title":"Marketing Communication in the Internet Era, Social Media and Word-of-Mouth","body":"How the internet changed marketing communication (Hotmail 1996, MySpace, Facebook and Twitter, monologue to dialogue, many-to-many, consumer power, pull); interactivity; social media marketing and the types of platforms; roles, advantages and risks of social media; reach, impressions, organic reach and engagement; paid, owned and earned media; user-generated content, influencers and brand advocates; word-of-mouth, eWOM, viral, buzz, seeding and referral marketing; managing WOM.","noteType":"guide_topic","number":6,"mustKnow":[{"text":"How the internet changed marketing communication (Hotmail 1996, MySpace, Facebook and Twitter$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 26, $study_guide$, monologue to dialogue, many-to-many, consumer power, pull); interactivity; social media marketing and the types of platforms; roles, advantages and risks of social media; reach, impressions, organic reach and engagement; paid, owned and earned media; user-generated content, influencers and brand advocates; word-of-mouth, eWOM, viral, buzz, seeding and referral marketing; managing WOM."}],"lessons":[{"number":"6.1","title":"How the internet changed marketing communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"The road to the internet era:","bold":true},{"text":" printing press (Johannes Gutenberg, 15th century) gave print advertising; first printed adverts in "},{"text":"17th-century newspapers","bold":true},{"text":"; radio commercials from the "},{"text":"1920s","bold":true},{"text":"; television dominant by the "},{"text":"1950s","bold":true},{"text":"; the "},{"text":"Internet in the late 20th century","bold":true},{"text":" ushered in the digital age, with "},{"text":"websites as virtual storefronts","bold":true},{"text":" and "},{"text":"email as a direct line to customers","bold":true},{"text":"."}]},{"text":[{"text":"Hotmail, 1996:","bold":true},{"text":" one of the earliest successful digital marketing cases. It added "},{"text":"\"Get your free email at Hotmail\"","bold":true},{"text":" to every email its users sent and gained "},{"text":"millions of users within months","bold":true},{"text":". This is "},{"text":"viral marketing","bold":true},{"text":"."}]},{"text":[{"text":"Early 2000s:","bold":true},{"text":" "},{"text":"MySpace, Facebook and Twitter","bold":true},{"text":" rose and changed how businesses interact with audiences. "},{"text":"Social media turned marketing into a two-way conversation","bold":true},{"text":", letting brands engage directly with customers."}]},{"text":[{"text":"Many-to-many communication:","bold":true},{"text":" grown on the back of the highly developed Internet, e.g. "},{"text":"online chat rooms, blogging websites","bold":true},{"text":", discussion forums. (The other three types: one-to-many, many-to-one, one-to-one.)"}]},{"text":[{"text":"Interactivity:","bold":true},{"text":" firms and consumers can communicate "},{"text":"in both directions","bold":true},{"text":" and respond to each other's messages, often in real time."}]}]},{"type":"paragraph","text":[{"text":"The key changes","bold":true},{"text":" (what marketing communication in the internet era is distinguished by):"}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"From a "},{"text":"one-way monologue","bold":true},{"text":" (firm to customer) to a "},{"text":"two-way conversation","bold":true},{"text":" (dialogue). This is the most important change."}]},{"text":[{"text":"Greater interactivity, real-time engagement and integration","bold":true},{"text":" across many channels."}]},{"text":[{"text":"Speed and reach:","bold":true},{"text":" messages spread faster and reach "},{"text":"global","bold":true},{"text":" audiences."}]},{"text":[{"text":"Greater consumer power and control:","bold":true},{"text":" consumers compare prices, read reviews and share opinions publicly."}]},{"text":[{"text":"A move towards "},{"text":"pull communication:","bold":true},{"text":" consumers search, follow pages and choose what content to watch."}]},{"text":[{"text":"Measurability:","bold":true},{"text":" clicks, views and shares can be measured quickly and accurately."}]},{"text":[{"text":"Precise targeting","bold":true},{"text":" using data about the audience."}]},{"text":[{"text":"Word-of-mouth amplified","bold":true},{"text":" through online reviews, shares and influencer endorsements."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traps: the internet era did "},{"text":"not","bold":true},{"text":" reduce customer interaction, did "},{"text":"not","bold":true},{"text":" limit firms to traditional media, did "},{"text":"not","bold":true},{"text":" reduce feedback and did "},{"text":"not","bold":true},{"text":" reduce advertising options. Every option of that kind is wrong."}]},{"text":[{"text":"Push versus pull: a TV advert interrupts you (push); you searching \"best blender in Lagos\" and reading reviews on Jumia is pull. The internet did not remove push communication; it shifted the balance towards pull."}]},{"text":[{"text":"Audiences now have more choices than ever, are more confident and outspoken, and their media habits have changed. This is also why integrated marketing communication (IMC) matters more: many channels must carry one unified message."}]},{"text":[{"text":"Marketing communication is ever-evolving: understanding its history from the printing press to social media helps firms anticipate future trends."}]}]}]},{"number":"6.2","title":"Social media marketing and types of platforms","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Social media marketing:","bold":true},{"text":" using social media platforms (such as Facebook, Instagram, X (Twitter), LinkedIn, TikTok, YouTube) to "},{"text":"engage audiences, build the brand, and drive traffic and sales","bold":true},{"text":", by delivering "},{"text":"targeted, interactive content","bold":true},{"text":"."}]},{"text":[{"text":"Its effectiveness comes mainly from "},{"text":"two-way communication and real-time interaction","bold":true},{"text":" with customers."}]},{"text":[{"text":"It lets firms deliver "},{"text":"closely targeted messages based on data about their audience","bold":true},{"text":" (age, location, interests)."}]}]},{"type":"paragraph","text":[{"text":"Types of social media platforms","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Main use"}],[{"text":"Examples"}]],"rows":[[[{"text":"Social networks"}],[{"text":"Connecting with friends, family and brands"}],[{"text":"Facebook"}]],[[{"text":"Media-sharing networks"}],[{"text":"Sharing photos and videos"}],[{"text":"YouTube, Instagram, TikTok$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 27, $study_guide$"}]],[[{"text":"Microblogging"}],[{"text":"Short, fast public posts and conversations"}],[{"text":"X (Twitter)"}]],[[{"text":"Professional networks"}],[{"text":"Careers and business contacts (strong for B2B)"}],[{"text":"LinkedIn"}]],[[{"text":"Messaging apps"}],[{"text":"Private one-to-one and group chats"}],[{"text":"WhatsApp, Telegram"}]],[[{"text":"Blogs and forums"}],[{"text":"Longer posts and many-to-many discussion"}],[{"text":"Blogs, Nairaland, Reddit"}]],[[{"text":"Review sites"}],[{"text":"Ratings and reviews of products and places"}],[{"text":"Google reviews, store review pages"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Content marketing:","bold":true},{"text":" creating and sharing "},{"text":"valuable, relevant content","bold":true},{"text":" (articles, videos, tips) to "},{"text":"attract and keep","bold":true},{"text":" a target audience."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Search engines (Google) and online banking platforms are "},{"text":"not","bold":true},{"text":" social media. YouTube, Instagram and TikTok are media-sharing networks; LinkedIn is the professional network."}]},{"text":[{"text":"A recipe brand posting short cooking videos using its seasoning on TikTok is content marketing on a media-sharing network: the audience gets something useful, and the brand stays in mind."}]},{"text":[{"text":"Social media marketing does "},{"text":"not","bold":true},{"text":" replace all other forms of marketing communication, does not work without content, and does not mean sending one message to everyone with no targeting."}]}]}]},{"number":"6.3","title":"Roles, advantages, risks and measures of social media","mustKnow":[{"type":"paragraph","text":[{"text":"Roles of social media in marketing communication:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Foster dialogue, build communities and strengthen customer relationships","bold":true},{"text":" (the strategic role)."}]},{"text":[{"text":"Allow direct engagement","bold":true},{"text":" with customers."}]},{"text":[{"text":"Provide customer insights","bold":true},{"text":" (what people like, complain about, want)."}]},{"text":[{"text":"Increase brand visibility, affinity and long-term loyalty.","bold":true}]},{"text":[{"text":"Give "},{"text":"real-time feedback","bold":true},{"text":"."}]},{"text":[{"text":"Support customer service and drive traffic and sales."}]}]},{"type":"paragraph","text":[{"text":"Advantages:","bold":true},{"text":" precise targeting at relatively low cost; direct two-way interaction; quick, real-time feedback; measurable responses (clicks, shares, views); reach to large audiences."}]},{"type":"paragraph","text":[{"text":"Risks:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Loss of control over the message:","bold":true},{"text":" customers can comment, share and change its meaning. Social media never gives full control over what customers say."}]},{"text":[{"text":"Negative eWOM spreads quickly","bold":true},{"text":" and damages reputation."}]},{"text":[{"text":"Hashtag hijacking:","bold":true},{"text":" people use a brand's hashtag for complaints or mockery instead of the intended purpose."}]},{"text":[{"text":"Fake reviews and astroturfing","bold":true},{"text":" mislead customers."}]},{"text":[{"text":"Influencer scandals","bold":true},{"text":" damage the brand's image."}]}]},{"type":"paragraph","text":[{"text":"Key terms:","bold":true}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Community management:","bold":true},{"text":" the ongoing work of building and managing relationships with online followers (replying to comments, answering questions)."}]},{"text":[{"text":"Social listening:","bold":true},{"text":" monitoring online conversations to learn what people say about a brand, its competitors and its industry."}]},{"text":[{"text":"Engagement:","bold":true},{"text":" likes, comments, shares (and saves, clicks) on a post."}]},{"text":[{"text":"Reach:","bold":true},{"text":" the number of "},{"text":"different people","bold":true},{"text":" who saw the content."}]},{"text":[{"text":"Impressions:","bold":true},{"text":" the "},{"text":"total number of times","bold":true},{"text":" the content was displayed (one person can produce several)."}]},{"text":[{"text":"Organic reach:","bold":true},{"text":" people who see content "},{"text":"without the brand paying","bold":true},{"text":" to promote it. Because platforms decide what appears in feeds, organic reach is often low, so brands "},{"text":"pay to boost posts","bold":true},{"text":"."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Swap trap: reach counts "},{"text":"people","bold":true},{"text":", impressions count "},{"text":"displays","bold":true},{"text":". Impressions are always equal to or greater than reach. Frequency = impressions ÷ reach."}]},{"text":[{"text":"Worked example: a Lagos fashion store boosts a post for ₦30,000. It reaches 12,000 people, records 30,000 impressions and gets 900 likes, comments and shares."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Frequency = 30,000 ÷ 12,000 = 2.5 views per person."}]},{"text":[{"text":"Cost per 1,000 impressions (CPM) = (₦30,000 ÷ 30,000) × 1,000 = ₦1,000."}]},{"text":[{"text":"Engagement rate (one common method, by reach) = 900 ÷ 12,000 × 100 = 7.5%."}]},{"text":[{"text":"Cost per engagement = ₦30,000 ÷ 900 = ₦33.33 (rounded to the nearest kobo)."}]}]}]},{"text":[{"text":"Real-time feedback: a Lagos bakery posts two new cake flavours in the morning; by evening the comments show which one customers prefer, so it bakes more of that one."}]},{"text":[{"text":"\"Reaching large audiences at relatively low cost\" is an "},{"text":"advantage","bold":true},{"text":", never a risk. A firm's electricity bill or staff numbers are not social media measures."}]},{"text":[{"text":"Hashtag hijack$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 28, $study_guide$ing example: McDonald's #McDStories (2012) invited happy stories but attracted complaints."}]}]}]},{"number":"6.4","title":"UGC, influencers, advocates and paid, owned, earned media","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"User-generated content (UGC):","bold":true},{"text":" content such as reviews, photos and videos about a brand "},{"text":"created by customers rather than by the brand","bold":true},{"text":"."}]},{"text":[{"text":"Social media influencer:","bold":true},{"text":" a person who has "},{"text":"built a following online","bold":true},{"text":" and can "},{"text":"affect the opinions and purchases","bold":true},{"text":" of that audience. Influencers are the online version of "},{"text":"opinion leaders","bold":true},{"text":" (two-step flow)."}]},{"text":[{"text":"Micro-influencers","bold":true},{"text":" (compared with celebrity/mega influencers): "},{"text":"smaller, more specialised audiences","bold":true},{"text":", often "},{"text":"higher engagement and trust","bold":true},{"text":", and lower fees. Mega influencers have much larger audiences and much higher fees."}]},{"text":[{"text":"Disclosure:","bold":true},{"text":" an influencer must clearly label a paid partnership "},{"text":"so that followers know it is advertising and are not misled","bold":true},{"text":"."}]},{"text":[{"text":"Brand advocates:","bold":true},{"text":" loyal customers who "},{"text":"voluntarily recommend and defend","bold":true},{"text":" a brand, "},{"text":"without being paid","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Paid, owned and earned media","bold":true}]},{"type":"table","header":[[{"text":"Type"}],[{"text":"Meaning"}],[{"text":"Examples"}]],"rows":[[[{"text":"Paid"}],[{"text":"Media space the firm "},{"text":"buys","bold":true}],[{"text":"Boosted or sponsored Instagram post, Facebook ad, TV ad"}]],[[{"text":"Owned"}],[{"text":"Channels the firm "},{"text":"controls","bold":true}],[{"text":"Official website, Instagram page, company blog, app"}]],[[{"text":"Earned"}],[{"text":"Exposure gained "},{"text":"free","bold":true},{"text":" through customers, fans and the press"}],[{"text":"Shares, reviews, UGC, a free newspaper feature"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Customers of a Lekki restaurant post their own photos of its jollof rice with its hashtag, unpaid: "},{"text":"UGC","bold":true},{"text":" (and earned media), not paid advertising or sales promotion."}]},{"text":[{"text":"Choosing influencers: a small Abuja skincare brand with ₦200,000 wanting believable recommendations to women who follow skincare closely should use "},{"text":"several micro-influencers who focus on skincare","bold":true},{"text":", not one celebrity musician or a TV commercial. Fit and trust beat raw follower numbers."}]},{"text":[{"text":"In Nigeria advertising, including on digital platforms, is regulated by "},{"text":"ARCON","bold":true},{"text":" (Advertising Regulatory Council of Nigeria, formerly APCON). Honest labelling protects followers and the brand's credibility."}]},{"text":[{"text":"A free newspaper story about a Lagos fintech app after customers praised it online is "},{"text":"earned","bold":true},{"text":" media. A firm's own blog is "},{"text":"owned","bold":true},{"text":". A brand advocate differs from a paid influencer: the advocate is unpaid."}]}]}]},{"number":"6.5","title":"Word-of-mouth, eWOM, viral and buzz marketing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Word-of-mouth (WOM):","bold":true},{"text":" informal person-to-person communication among consumers about products, services and brands; customers share their experiences with peers and friends about goods and services they bought recently. It is one of the most widely practised communication tools."}]},{"text":[{"text":"Why WOM is credible:","bold":true},{"text":" it comes from people seen as "},{"text":"independent of the firm and not paid","bold":true},{"text":" to promote the product. It "},{"text":"builds trust, credibility and purchase intent through peer influence","bold":true},{"text":"."}]},{"text":[{"text":"Electronic word-of-mouth (eWOM):","bold":true},{"text":" positive or negative statements made by "},{"text":"potential, actual or former customers","bold":true},{"text":" about a product or company, made available to "},{"text":"many people through the internet","bold":true},{"text":" (tweets, online reviews, forum posts)."}]},{"text":[{"text":"eWOM vs WOM:","bold":true},{"text":" eWOM reaches "},{"text":"many more people, faster","bold":true},{"text":", and "},{"text":"stays available online for a long time","bold":true},{"text":"; it can be positive or negative."}]},{"text":[{"text":"Online WOM is dynamic:","bold":true},{"text":" its impact can be "},{"text":"positive or negative","bold":true},{"text":" depending on customers' feelings and experiences."}]},{"text":[{"text":"Viral marketing:","bold":true},{"text":" creating content so interesting that people "},{"text":"pass it on","bold":true},{"text":", spreading it rapidly online. Content goes viral when it is "},{"text":"emotional, entertaining or useful","bold":true},{"text":" enough to share. "},{"text":"Limitation:","bold":true},{"text":" firms "},{"text":"cannot guarantee","bold":true},{"text":" it will spread or "},{"text":"control how people interpret","bold":true},{"text":" it."}]},{"text":[{"text":"Buzz marketing:","bold":true},{"text":" getting "},{"text":"opinion leaders and early users talking","bold":true},{"text":" about a product so excitement spreads to others."}]},{"text":[{"text":"Seeding:","bold":true},{"text":" giving a new product or content to selected "},{"text":"well-connected people first","bold":true},{"text":" so they share it with their networks."}]},{"text":[{"text":"Referral marketing:","bold":true},{"text":" rewarding existing customers for bringing in new ones (e.g. ₦500 per friend who signs up with$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 29, $study_guide$ a personal code). It encourages WOM."}]},{"text":[{"text":"Astroturfing:","bold":true},{"text":" creating "},{"text":"fake reviews or fake \"ordinary customer\" accounts","bold":true},{"text":" to fake genuine public support. It is unethical."}]}]},{"type":"paragraph","text":[{"text":"Managing WOM:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Deliver good products and service (the source of positive WOM)."}]},{"text":[{"text":"Seed and use opinion leaders, influencers and advocates; run referral schemes."}]},{"text":[{"text":"Make sharing easy (hashtags, share buttons, review requests)."}]},{"text":[{"text":"Listen (social listening) and engage (community management)."}]},{"text":[{"text":"When negative posts spread, "},{"text":"respond quickly, honestly and politely, and address the problem openly","bold":true},{"text":". Do not argue, ignore, or delete and block critics."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"WOM is "},{"text":"not","bold":true},{"text":" fully controlled by the company, is "},{"text":"not","bold":true},{"text":" free of strategy, does "},{"text":"not","bold":true},{"text":" spread only face to face and is "},{"text":"not","bold":true},{"text":" less relevant online: the internet "},{"text":"amplified","bold":true},{"text":" it."}]},{"text":[{"text":"Amaka reading 40 buyer reviews of a blender on an online store before buying: "},{"text":"eWOM","bold":true},{"text":". A company's television commercial is "},{"text":"not","bold":true},{"text":" eWOM (it is paid advertising from the firm)."}]},{"text":[{"text":"A customer's video complaint about a bank branch in Ikeja, shared thousands of times in a day, shows the risk of "},{"text":"negative eWOM spreading fast","bold":true},{"text":". The bank should reply publicly, apologise where due, and fix the issue."}]},{"text":[{"text":"Buzz and seeding often work together: a phone brand gives early units to Nigerian tech reviewers (seeding) to get people talking (buzz). Hotmail's footer is the classic case of viral spread."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Internet era = monologue to dialogue, interactivity, speed, global reach, consumer power, pull, measurability, targeting."}]},{"text":[{"text":"Hotmail 1996 \"Get your free email at Hotmail\" = viral; MySpace, Facebook, Twitter (early 2000s) made marketing two-way."}]},{"text":[{"text":"Many-to-many = chat rooms, blogs, forums."}]},{"text":[{"text":"Social media marketing = engage audiences, build the brand, drive traffic and sales with targeted, interactive content."}]},{"text":[{"text":"Roles: dialogue, communities, relationships, insights, visibility and loyalty. Biggest risk: loss of control."}]},{"text":[{"text":"Reach = different people; impressions = total displays; organic = unpaid."}]},{"text":[{"text":"Paid = bought; owned = controlled; earned = free from customers, fans, press."}]},{"text":[{"text":"Influencers = online opinion leaders; micro = smaller, specialised, higher trust; disclose paid posts."}]},{"text":[{"text":"WOM credible because independent and unpaid; eWOM = online, faster, wider, lasting."}]},{"text":[{"text":"Viral = passed on; buzz = opinion leaders talking; seeding = give to connectors first; astroturfing = fake support; answer negative posts quickly, honestly, politely."}]}]}],"theory":{"itemId":"0227e2a3-f51d-5204-8306-be19cdc71765","question":[{"type":"paragraph","text":[{"text":"A brand pays ₦40,000 to boost a TikTok video. It reaches 8,000 people, each seeing it 3 times on average, and gets 360 likes, comments and shares. Find (a) impressions, (b) engagement rate by reach, (c) cost per 1,000 impressions. State whether the boost is paid, owned or earned media."}]}]},"practice":[{"topic":"MarCom in the Internet Era, Social Media and Word-of-Mouth","named":false}]}},{"kind":"note","itemId":"0a278429-8e6c-5cd3-b064-7439ab187940","sourceKey":"guide-topic:7","position":7,"payload":{"title":"Communication in Market Relationships","body":"Market (transactional) versus relational exchange; relationship marketing, trust and commitment, retention, loyalty, churn and customer lifetime value; the role of communication in the relationship with the market; the interactional, relational (contextual) and network approaches to communication and how each differs from the linear model.","noteType":"guide_topic","number":7,"mustKnow":[{"text":"Market (transactional) versus relational exchange; relationship marketing, trust and commitment, retention, loyalty, churn and customer lifetime value; the role of communication in the relationship with the market; the interactional, relational (contextual) and network approaches to communication and how each differs from the linear model."}],"lessons":[{"number":"7.1","title":"Market exchange and relational exchange","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Exchange process:","bold":true},{"text":" obtaining a desired object from someone by offering something of value in return. A completed exchange is a "},{"text":"transaction","bold":true},{"text":"."}]},{"text":[{"text":"5 conditions for exchange:","bold":true},{"text":" (1) at least two parties; (2) each has something that might be of value to the other; (3) each can communicate and deliver what it offers; (4) each is free to accept or reject the offer; (5) each party "},{"text":"trusts/respects","bold":true},{"text":" the other sufficiently to take the exchange seriously."}]},{"text":[{"text":"Two types of exchange most readily observed in marketing:","bold":true},{"text":" "},{"text":"market","bold":true},{"text":" exchange and "},{"text":"relational","bold":true},{"text":" exchange. Marketing communication plays roles in "},{"text":"both","bold":true},{"text":"."}]},{"text":[{"text":"Market (transactional) exchange:","bold":true},{"text":" a "},{"text":"one-off, short-term","bold":true},{"text":" exchange focused mai$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 30, $study_guide$nly on the "},{"text":"product and its price","bold":true},{"text":". The relationship "},{"text":"ends once the goods and payment have changed hands","bold":true},{"text":"."}]},{"text":[{"text":"Relational exchange:","bold":true},{"text":" an "},{"text":"ongoing","bold":true},{"text":" exchange in which buyer and seller "},{"text":"build trust and interact repeatedly over time","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Feature"}],[{"text":"Market (transactional) exchange"}],[{"text":"Relational exchange"}]],"rows":[[[{"text":"Time scale"}],[{"text":"Short, one-off"}],[{"text":"Long-term, ongoing"}]],[[{"text":"Main focus"}],[{"text":"Product and price"}],[{"text":"Relationship, customer value"}]],[[{"text":"Contact after sale"}],[{"text":"None expected"}],[{"text":"Regular, two-way"}]],[[{"text":"Basis"}],[{"text":"Bargain on the deal"}],[{"text":"Trust and commitment"}]],[[{"text":"Parties"}],[{"text":"Independent"}],[{"text":"Interdependent"}]],[[{"text":"Role of MarCom"}],[{"text":"Inform and persuade so a sale is completed"}],[{"text":"Build and maintain trust, commitment and dialogue"}]]]},{"type":"paragraph","text":[{"text":"Characteristics of relational exchange:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Long-term orientation towards keeping the customer."}]},{"text":[{"text":"Trust and commitment between buyer and seller."}]},{"text":[{"text":"Regular two-way communication and feedback over time."}]},{"text":[{"text":"Interdependence:","bold":true},{"text":" each party relies on the other and gains from continuing the relationship."}]},{"text":[{"text":"Cooperation, such as joint planning and shared problem-solving."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Chidi bargains with a hawker at a Lagos bus stop, pays ₦2,500 for a used phone charger, and neither expects to meet again: a "},{"text":"market (transactional) exchange","bold":true},{"text":"."}]},{"text":[{"text":"A cement manufacturer and an Abuja construction firm have dealt with each other for eight years, share delivery schedules, plan supply together and meet regularly to solve problems: a "},{"text":"relational exchange","bold":true},{"text":". \"Barter\" and \"spot purchase\" are wrong here."}]},{"text":[{"text":"Even a single transaction needs a "},{"text":"basic level of trust","bold":true},{"text":" (condition 5). It does not need a long-term written contract, the lowest price or television advertising."}]},{"text":[{"text":"Trap: \"focus on completing a single sale with no further contact\" is the one statement that is "},{"text":"not","bold":true},{"text":" a characteristic of relational exchange."}]},{"text":[{"text":"The shift: there is a strong "},{"text":"paradigm shift","bold":true},{"text":" away from reliance on one-off market exchanges towards a longer-term perspective that creates and maintains enduring partnerships. This approach is "},{"text":"relationship marketing","bold":true},{"text":". Partnerships between brands and consumers, and between organisations within distribution channels or networks, are a vital perspective of marketing communication."}]},{"text":[{"text":"Options that exams swap in for the two types: barter and monetary, direct and indirect, internal and external. None of these is the correct pair; the answer is "},{"text":"market and relational","bold":true},{"text":"."}]}]}]},{"number":"7.2","title":"Relationship marketing, trust and commitment","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Relationship marketing:","bold":true},{"text":" attracting, maintaining and enhancing "},{"text":"long-term relationships","bold":true},{"text":" with customers (Berry). The idea behind it: \"Marketing is not just about selling products; it is about building relationships and creating value.\""}]},{"text":[{"text":"Trust:","bold":true},{"text":" a customer's "},{"text":"confidence in a supplier's reliability and integrity","bold":true},{"text":" (Morgan and Hunt)."}]},{"text":[{"text":"Commitment:","bold":true},{"text":" an "},{"text":"enduring desire to maintain a valued relationship","bold":true},{"text":" (Moorman, Zaltman and Deshpande)."}]},{"text":[{"text":"Trust and commitment","bold":true},{"text":" are the "},{"text":"two variables central to the success of relationship marketing","bold":true},{"text":" (Morgan and Hunt's commitment-trust theory)."}]},{"text":[{"text":"Dialogue:","bold":true},{"text":" communication in which both parties listen, respond and build shared understanding together."}]}]},{"type":"paragraph","text":[{"text":"Transactional marketing versus relationship marketing:","bold":true}]},{"type":"table","header":[[{"text":"Transactional marketing"}],[{"text":"Relationship marketing"}]],"rows":[[[{"text":"Focus on the single sale"}],[{"text":"Focus on customer retention"}]],[[{"text":"Orientation on product features"}],[{"text":"Orientation on customer value and benefits"}]],[[{"text":"Short time scale"}],[{"text":"Long time scale"}]],[[{"text":"Little emphasis on customer service"}],[{"text":"High emphasis on customer service"}]],[[{"text":"Limited customer commitment"}],[{"text":"High customer commitment"}]],[[{"text":"Moderate customer contact"}],[{"text":"High customer contact"}]],[[{"text":"Quality is mainly a concern of production"}],[{"text":"Quality is a concern of all staff"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trust in action: for five years a Kano wholesaler has delivered rice on the agreed date, in the agreed quantity and at the agreed price, so the retailer now orders without checking every bag. That quality is "},{"text":"trust","bold":true},{"text":" (not impulse buying, cognitive dissonance or brand switching)."}]},{"text":[{"text":"Commitment in action: Aisha has banked with the same bank for ten years. A rival offers a slightly better savings rate, but she stays because she values her a$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 31, $study_guide$ccount officer and the bank. That is "},{"text":"commitment to the relationship","bold":true},{"text":", the opposite of price sensitivity, a transactional orientation or brand switching."}]},{"text":[{"text":"Trap: trust is about "},{"text":"confidence","bold":true},{"text":" in the partner; commitment is about the "},{"text":"desire to stay","bold":true},{"text":". Satisfaction and awareness are not the names for either."}]},{"text":[{"text":"Trap: \"high emphasis on customer service and long-term contact\" is "},{"text":"not","bold":true},{"text":" typical of a transactional approach. Compared with transactional marketing, relationship marketing focuses more on "},{"text":"customer value and benefits over a long time scale","bold":true},{"text":"."}]},{"text":[{"text":"Nigerian example: a telecom operator such as MTN or Airtel that sends each subscriber a personalised birthday message with bonus airtime, while its care team remembers past complaints, is practising "},{"text":"relationship marketing","bold":true},{"text":" (not price skimming, mass marketing or transactional marketing)."}]}]}]},{"number":"7.3","title":"Retention, loyalty and customer lifetime value","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Customer retention:","bold":true},{"text":" a firm's ability to "},{"text":"keep its existing customers buying from it over time","bold":true},{"text":". Attracting first-time buyers is "},{"text":"acquisition","bold":true},{"text":", not retention."}]},{"text":[{"text":"Why retention matters:","bold":true},{"text":" keeping an existing customer "},{"text":"usually costs less than attracting a new one","bold":true},{"text":" (often quoted as up to five times less)."}]},{"text":[{"text":"Customer loyalty:","bold":true},{"text":" a customer's "},{"text":"continued preference for and repeat purchase","bold":true},{"text":" of a firm's brand over time."}]},{"text":[{"text":"Customer churn (defection):","bold":true},{"text":" the "},{"text":"rate at which customers stop doing business","bold":true},{"text":" with a firm over a period."}]},{"text":[{"text":"Customer lifetime value (CLV):","bold":true},{"text":" the "},{"text":"total value","bold":true},{"text":" a customer is expected to bring to a firm "},{"text":"over the whole relationship","bold":true},{"text":"."}]},{"text":[{"text":"Ladder of loyalty (in order):","bold":true},{"text":" prospect, customer, client, supporter, "},{"text":"advocate","bold":true},{"text":" (and, at the top in some versions, partner). An "},{"text":"advocate actively recommends","bold":true},{"text":" the firm to other people."}]}]},{"type":"paragraph","text":[{"text":"Formulas (plain text):","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Churn rate (%) = customers lost during the period / customers at the start of the period x 100"}]},{"text":[{"text":"Retention rate (%) = 100 - churn rate (when no new customers are counted)"}]},{"text":[{"text":"CLV (revenue) = average spend per purchase x purchases per year x expected years of relationship"}]},{"text":[{"text":"CLV (profit) = CLV (revenue) x profit margin"}]}]},{"type":"paragraph","text":[{"text":"Benefits of strong customer relationships:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"More repeat purchases."}]},{"text":[{"text":"Customers less likely to switch to rivals."}]},{"text":[{"text":"Positive word-of-mouth recommendations."}]},{"text":[{"text":"Lower cost of serving and keeping customers than of winning new ones."}]},{"text":[{"text":"Higher customer lifetime value."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Trap: \"customers who buy once and never return\" is "},{"text":"not","bold":true},{"text":" a benefit of strong relationships."}]},{"text":[{"text":"A loyalty card at an Ikeja supermarket that earns points redeemable for gifts exists to "},{"text":"encourage repeat purchases and retain customers","bold":true},{"text":"."}]},{"text":[{"text":"Trap: CLV is not the value of the first purchase, nor the price of the most expensive product."}]},{"text":[{"text":"Worked example (churn):","bold":true},{"text":" a Lagos gym starts the year with 2,000 members and 150 leave."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Churn rate = 150 / 2,000 x 100 = "},{"text":"7.5%","bold":true},{"text":"."}]},{"text":[{"text":"Retention rate = 100 - 7.5 = "},{"text":"92.5%","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Worked example (CLV):","bold":true},{"text":" a customer spends ₦6,000 per visit at a restaurant, visits 4 times a month and is expected to stay 5 years; profit margin is 20%."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Visits per year = 4 x 12 = 48."}]},{"text":[{"text":"Spend per year = ₦6,000 x 48 = ₦288,000."}]},{"text":[{"text":"CLV (revenue) = ₦288,000 x 5 = "},{"text":"₦1,440,000","bold":true},{"text":"."}]},{"text":[{"text":"CLV (profit) = ₦1,440,000 x 0.20 = "},{"text":"₦288,000","bold":true},{"text":"."}]}]}]},{"text":[{"text":"The lesson of CLV: a ₦6,000 customer is really worth ₦1,440,000 in sales over the relationship, which is why firms spend on communication that keeps people."}]}]}]},{"number":"7.4","title":"The role of communication in the relationship with the market","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Role of communication in market relationships:","bold":true},{"text":" to "},{"text":"build trust, loyalty and lasting customer commitment","bold":true},{"text":"."}]},{"text":[{"text":"Fundamental aim:","bold":true},{"text":" to "},{"text":"increase customer trust, satisfaction and retention","bold":true},{"text":"."}]},{"text":[{"text":"Strategic aim:","bold":true},{"text":" to "},{"text":"strengthen customer loyalty through consistent delivery of value","bold":true},{"text":"."}]}]},{"type":"paragraph","text":[{"text":"Roles of communication in a market $study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 32, $study_guide$relationship:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Builds and maintains "},{"text":"trust","bold":true},{"text":" by keeping promises visible and consistent."}]},{"text":[{"text":"Strengthens "},{"text":"commitment","bold":true},{"text":" and loyalty."}]},{"text":[{"text":"Opens "},{"text":"dialogue","bold":true},{"text":": listens to customers and responds to feedback and complaints."}]},{"text":[{"text":"Keeps customers "},{"text":"informed","bold":true},{"text":" after the sale (updates, service, new offers)."}]},{"text":[{"text":"Coordinates","bold":true},{"text":" with partners in the network (suppliers, distributors, agencies)."}]},{"text":[{"text":"Turns satisfied customers into "},{"text":"advocates","bold":true},{"text":" who spread positive word-of-mouth."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Every wrong option in this area describes the opposite of relationship building: completing a single sale with no further contact, minimising contact to save resources, avoiding customer engagement, restricting product availability to create scarcity, or chasing new customers while ignoring existing ones."}]},{"text":[{"text":"In a "},{"text":"transactional","bold":true},{"text":" exchange the main job of communication is to "},{"text":"inform and persuade","bold":true},{"text":" buyers about the offer so a sale is completed. In a "},{"text":"relational","bold":true},{"text":" exchange its job is to "},{"text":"build and maintain trust, commitment and dialogue","bold":true},{"text":"."}]},{"text":[{"text":"Example: GTBank and other Nigerian banks send transaction alerts, account statements and service updates. These messages keep the customer informed and confident, so they support retention rather than one sale."}]}]}]},{"number":"7.5","title":"Interactional and relational (contextual) approaches","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Linear model (for contrast):","bold":true},{"text":" a one-way flow of messages from a sender to a "},{"text":"passive","bold":true},{"text":" receiver who does not reply (Shannon and Weaver). The "},{"text":"hypodermic needle","bold":true},{"text":" view is a similar one-way idea."}]},{"text":[{"text":"Interactional approach:","bold":true},{"text":" views communication as a "},{"text":"two-way process","bold":true},{"text":" in which participants send messages, respond and give "},{"text":"feedback","bold":true},{"text":" to each other. It focuses on "},{"text":"two-way dialogue","bold":true},{"text":" between businesses and customers."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Most central element: "},{"text":"feedback and response","bold":true},{"text":" between the parties."}]},{"text":[{"text":"Differs from the linear model because it "},{"text":"includes feedback and response, so communication flows both ways","bold":true},{"text":"."}]},{"text":[{"text":"It ensures "},{"text":"active engagement with customers and responsiveness to their needs","bold":true},{"text":"."}]}]}]},{"text":[{"text":"Relational (contextual) approach:","bold":true},{"text":" holds that the "},{"text":"meaning of a message depends on the relationship between the participants and the context","bold":true},{"text":" of the message."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"It is mainly concerned with communication that "},{"text":"develops and sustains the relationship","bold":true},{"text":" between the parties."}]},{"text":[{"text":"It is centred on "},{"text":"building lasting, value-based relationships","bold":true},{"text":" with customers, enabling firms to "},{"text":"build trust and develop long-term partnerships","bold":true},{"text":"."}]},{"text":[{"text":"It treats "},{"text":"sustained, long-term customer relationships","bold":true},{"text":" as the basis of competitive advantage."}]}]}]}]},{"type":"table","header":[[{"text":"Approach"}],[{"text":"Main focus"}]],"rows":[[[{"text":"Linear"}],[{"text":"One-way flow from sender to passive receiver"}]],[[{"text":"Interactional"}],[{"text":"Two-way message exchange with feedback"}]],[[{"text":"Relational (contextual)"}],[{"text":"Meaning shaped by the relationship and context"}]],[[{"text":"Network"}],[{"text":"Spread of messages across many connected people and organisations"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Interactional example: a customer complains on social media that her data was wrongly deducted. The telecom firm replies in minutes, asks for details, she responds, the firm fixes the problem and checks back. Send, respond, feedback, follow-up: the "},{"text":"interactional approach","bold":true},{"text":". It is not the network approach because only two parties are exchanging messages."}]},{"text":[{"text":"Relational example: two suppliers send an Ibadan food processor the same message, \"Your order will arrive tomorrow.\" The processor believes the supplier it has used reliably for years but doubts the new one. Same words, different meaning, because of the "},{"text":"relationship and context","bold":true},{"text":": the "},{"text":"relational (contextual) approach","bold":true},{"text":"."}]},{"text":[{"text":"Traps: the interactional approach does not suppress feedback, keep messages one-way or stop customers replying. The relational approach does not say meaning is fixed and identical for every receiver, that only channel quality decides meaning, or that communication works best with no previous relationship."}]},{"text":[{"text":"Matching trap: interactional = "},{"text":"two-way exchange","bold":true},{"text":"; relational = "},{"text":"meaning shaped by the relationship","bold":true},{"text":". Options that swap these are wrong."}]},{"text":[{"text":"Dialogue","bold":true},{"text":" is the opposite of monologue, broadcasting and propaganda, where one party simply talks at the other."}]}]}]$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 33, $study_guide$},{"number":"7.6","title":"The network approach to communication","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Network approach:","bold":true},{"text":" views communication as "},{"text":"flows of information through a web of interconnected people and organisations","bold":true},{"text":". It emphasises "},{"text":"connected exchanges among many stakeholders","bold":true},{"text":", including partners and suppliers."}]},{"text":[{"text":"Valuable for:","bold":true},{"text":" managing relationships across a "},{"text":"web of interdependent stakeholders","bold":true},{"text":"."}]},{"text":[{"text":"Supports firms by:","bold":true},{"text":" enabling "},{"text":"effective collaboration across different stakeholder groups","bold":true},{"text":"."}]},{"text":[{"text":"Well-connected members","bold":true},{"text":" (hubs, opinion leaders) matter because they "},{"text":"speed up and widen the spread","bold":true},{"text":" of messages through the network."}]},{"text":[{"text":"The network approach best explains how "},{"text":"word-of-mouth and viral messages","bold":true},{"text":" spread among consumers."}]},{"text":[{"text":"Shared feature of the three approaches:","bold":true},{"text":" interactional, relational and network approaches all treat communication as "},{"text":"more than a one-way transmission","bold":true},{"text":" from sender to receiver."}]}]},{"type":"paragraph","text":[{"text":"Stakeholders in a firm's communication network:","bold":true}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Customers and consumers."}]},{"text":[{"text":"Suppliers."}]},{"text":[{"text":"Distributors and retailers."}]},{"text":[{"text":"Advertising and media agencies."}]},{"text":[{"text":"Regulators (for example ARCON for advertising, NCC for telecoms)."}]},{"text":[{"text":"Employees, the media and the wider community."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Viral example: a few UNILAG students share a new fintech app in class WhatsApp groups, members forward it to other groups, and within days thousands have heard. That pattern is the "},{"text":"network approach","bold":true},{"text":", not personal selling or the linear model."}]},{"text":[{"text":"Stakeholder example: a Lagos beverage company coordinates communication with suppliers, distributors, retailers, agencies and regulators, recognising that information passes among all of them: the "},{"text":"network approach","bold":true},{"text":"."}]},{"text":[{"text":"Traps: the network approach is not communication between one seller and one buyer only, not one-way mass messages, not limited to one department, and it does not remove the need to talk to suppliers."}]},{"text":[{"text":"Well-connected people do not block messages or only receive them; they pass them on to many others."}]},{"text":[{"text":"Link to Topic 6: word-of-mouth, eWOM and buzz all travel through networks, which is why firms court influencers who sit at the busy centre of a network."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Two observable types of exchange: "},{"text":"market","bold":true},{"text":" (one-off, product and price, ends at payment) and "},{"text":"relational","bold":true},{"text":" (ongoing, trust, repeated contact, interdependence)."}]},{"text":[{"text":"Relationship marketing","bold":true},{"text":" = attracting, maintaining and enhancing long-term customer relationships; it is about building relationships and creating value."}]},{"text":[{"text":"Trust","bold":true},{"text":" = confidence in reliability and integrity; "},{"text":"commitment","bold":true},{"text":" = enduring desire to maintain a valued relationship; both are central."}]},{"text":[{"text":"Retention keeps existing customers and costs less than acquisition; churn is the rate of defection; loyalty is continued preference and repeat buying; an "},{"text":"advocate","bold":true},{"text":" recommends the firm."}]},{"text":[{"text":"CLV = spend per purchase x purchases per year x years (x margin for profit)."}]},{"text":[{"text":"Communication's role: build trust, loyalty and commitment; increase satisfaction and retention."}]},{"text":[{"text":"Interactional","bold":true},{"text":" = two-way dialogue with feedback; "},{"text":"relational (contextual)","bold":true},{"text":" = meaning depends on relationship and context; "},{"text":"network","bold":true},{"text":" = flows through a web of many stakeholders; all go beyond one-way transmission."}]}]}],"theory":{"itemId":"7823aa23-a370-533f-9be6-b129116c5fc4","question":[{"type":"paragraph","text":[{"text":"Bukola buys bread worth ₦3,500 from a neighbourhood bakery twice a week, every week of the year, and is expected to stay a customer for 4 years. The bakery's profit margin is 25%. Its customer base fell from 16,000 to 15,200 over the year with no new customers counted. Calculate (a) Bukola's CLV in revenue and profit terms and (b) the bakery's churn and retention rates."}]}]},"practice":[{"topic":"Communication in Market Relationships","named":false}]}},{"kind":"note","itemId":"6992aa23-c414-54a4-b5a6-e91f3cc5bffd","sourceKey":"guide-topic:8","position":8,"payload":{"title":"Online and Offline Media and Digital Marketing","body":"What offline and online media are, with examples and the merits and demerits of each; paid, owned and earned media; what digital marketing and digital marketing communication mean; how to craft a digital marketing strategy; the types of digital marketing (SEO, SEM/PPC, content, social media, email, affiliate, influencer, mobile, video, display, viral); the key digital metrics; the importance and challenges of digital marketing.","noteType":"guide_topic","number":8,"mustKnow":[{"text":"What offline and online media are, with examples and the merits and demerits of each; paid, owned and earned media; what digital marketing and digital marketing communication mean; how to craft a digital marketing str$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 34, $study_guide$ategy; the types of digital marketing (SEO, SEM/PPC, content, social media, email, affiliate, influencer, mobile, video, display, viral); the key digital metrics; the importance and challenges of digital marketing."}],"lessons":[{"number":"8.1","title":"Offline and online communication media","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Communication medium:","bold":true},{"text":" the channel through which a marketing message is carried to the target audience."}]},{"text":[{"text":"Offline (traditional) media:","bold":true},{"text":" established channels that do not need the internet. They are best exemplified by "},{"text":"television, radio and print advertising","bold":true},{"text":"."}]},{"text":[{"text":"Online (digital) media:","bold":true},{"text":" channels delivered through the internet and digital devices. They are best exemplified by "},{"text":"digital platforms such as social media, websites and apps","bold":true},{"text":"."}]}]},{"type":"table","header":[[{"text":"Offline (traditional) media"}],[{"text":"Online (digital) media"}]],"rows":[[[{"text":"Television"}],[{"text":"Search engines (organic results and paid search ads)"}]],[[{"text":"Radio"}],[{"text":"Display advertising (banners on websites and apps)"}]],[[{"text":"Newspapers"}],[{"text":"Social media (Instagram, Facebook, X, TikTok, YouTube)"}]],[[{"text":"Magazines"}],[{"text":"Email marketing and newsletters"}]],[[{"text":"Outdoor (billboards, posters, transit ads on buses)"}],[{"text":"Mobile (SMS, apps, mobile sites)"}]],[[{"text":"Cinema"}],[{"text":"Company websites and blogs"}]],[[{"text":"Direct mail, flyers, brochures"}],[{"text":"Online video and podcasts"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"How the media evolved:","bold":true},{"text":" printing press (Gutenberg, 15th century) gave birth to print advertising; the first printed adverts appeared in "},{"text":"17th-century newspapers","bold":true},{"text":"; "},{"text":"radio commercials began in the 1920s","bold":true},{"text":"; by the "},{"text":"1950s television","bold":true},{"text":" became the dominant platform, combining visuals and sound; the "},{"text":"internet (late 20th century)","bold":true},{"text":" brought websites as virtual storefronts and email as a direct line to customers; the "},{"text":"early 2000s","bold":true},{"text":" brought social media (MySpace, Facebook, Twitter), turning marketing into a two-way conversation."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Group test trap:","bold":true},{"text":" exam options mix the two lists. \"Television, radio, newspapers and billboards\" is entirely offline. \"Websites, search engines, social media and email\" is entirely online. Any option with even one item from the other side (for example \"radio, social media, magazines and websites\") is wrong."}]},{"text":[{"text":"Odd-one-out:","bold":true},{"text":" a sponsored search engine advert is "},{"text":"not","bold":true},{"text":" offline; a painted advert on the side of a "},{"text":"danfo bus","bold":true},{"text":" is "},{"text":"not","bold":true},{"text":" online (it is outdoor, transit advertising). A banner on a news website and an email newsletter are online."}]},{"text":[{"text":"Streaming services and podcasts are online, so they never describe offline media."}]},{"text":[{"text":"One of the earliest successful pieces of digital marketing was "},{"text":"Hotmail's viral strategy in 1996","bold":true},{"text":": it added \"Get your free email at Hotmail\" to every email sent and gained millions of users within months."}]}]}]},{"number":"8.2","title":"Merits and demerits of offline and online media","mustKnow":[{"type":"table","header":[[{"text":"Medium"}],[{"text":"Merits"}],[{"text":"Demerits"}]],"rows":[[[{"text":"Television"}],[{"text":"Combines "},{"text":"sight, sound and motion","bold":true},{"text":"; reaches a "},{"text":"large mass audience","bold":true},{"text":"; strong for storytelling and emotion"}],[{"text":"High absolute cost; short exposure; clutter; viewers can switch channel"}]],[[{"text":"Radio"}],[{"text":"Low cost","bold":true},{"text":", "},{"text":"locally targeted","bold":true},{"text":", reaches people in local languages, rural and mobile listeners"}],[{"text":"Audio only","bold":true},{"text":"; fleeting message; low attention"}]],[[{"text":"Newspapers"}],[{"text":"Timeliness","bold":true},{"text":", "},{"text":"local coverage","bold":true},{"text":", broad acceptance, flexible"}],[{"text":"Short life","bold":true},{"text":"; poor reproduction quality; many ads compete on a page"}]],[[{"text":"Magazines"}],[{"text":"Long life","bold":true},{"text":", "},{"text":"high-quality colour reproduction","bold":true},{"text":", "},{"text":"selective readership","bold":true},{"text":" with specific interests, pass-along readers"}],[{"text":"Long lead time; higher cost; less timely"}]],[[{"text":"Outdoor (billboards, posters, transit)"}],[{"text":"Repeated exposure","bold":true},{"text":" to passers-by; low cost per exposure; good location selection"}],[{"text":"Carries only "},{"text":"brief messages","bold":true},{"text":"; cannot target individuals; creative limits"}]],[[{"text":"Cinema"}],[{"text":"Captive audience; big screen, sound and motion"}],[{"text":"Limited reach; expensive production"}]],[[{"text":"Online media (overall)"}],[{"text":"Interactive (two-way)","bold":true},{"text":"; "},{"text":"precise targeting","bold":true},{"text":"; "},{"text":"measurable","bold":true},{"text":" (clicks, views tracked quickly, real-time); data-driven; relatively low cost; global reach; messages can be changed fast"}],[{"text":"Does not reach people "},{"text":"without internet","bold":true},{"text":"; audiences can "},{"text":"block or skip","bold":true},{"text":" ads; heavy "},{"text":"clutter","bold":true},{"text":"; privacy concerns; negative posts spread fast"}]]]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Off$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 35, $study_guide$line media remain relevant","bold":true},{"text":" because they reach audiences, including local ones, through established traditional channels and strengthen brand presence through "},{"text":"tangible, traditional touchpoints","bold":true},{"text":"."}]},{"text":[{"text":"Online media stand out","bold":true},{"text":" for "},{"text":"precise, interactive and data-driven","bold":true},{"text":" interaction with audiences."}]},{"text":[{"text":"Integration:","bold":true},{"text":" online and offline media can be "},{"text":"combined so that each supports the other","bold":true},{"text":" in an integrated campaign."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Choosing for the audience:","bold":true},{"text":" an agro-chemical firm reaching farmers in remote Benue villages, with poor internet but wide listening to local-language programmes, should use "},{"text":"local radio","bold":true},{"text":". Email, Instagram influencers and search ads all need the internet."}]},{"text":[{"text":"Swap traps:","bold":true},{"text":" \"Long life, colour, selective readership\" is "},{"text":"magazines","bold":true},{"text":", not newspapers. \"Timeliness and local coverage but short life\" is "},{"text":"newspapers","bold":true},{"text":". \"Repeated exposure but brief messages\" is "},{"text":"outdoor","bold":true},{"text":". \"Low cost, local and audio only\" is "},{"text":"radio","bold":true},{"text":". \"Sight, sound and motion to a mass audience\" is "},{"text":"television","bold":true},{"text":"."}]},{"text":[{"text":"NOT a limitation of online media:","bold":true},{"text":" \"results can be tracked in detail\". That is a strength."}]},{"text":[{"text":"Online media do not stop people blocking or skipping ads, do not always cost more than national TV, and cannot reach people with no internet."}]},{"text":[{"text":"Integration example:","bold":true},{"text":" a Lagos fashion brand puts a "},{"text":"QR code","bold":true},{"text":" on billboards on Third Mainland Bridge which takes viewers straight to its online store. The billboard (offline) drives traffic to the store (online): this is "},{"text":"integrating offline and online media","bold":true},{"text":". Online media have not fully replaced offline media in every market, and both channels may carry the same core message (IMC)."}]}]}]},{"number":"8.3","title":"Digital marketing, digital marketing communication and paid, owned, earned media","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Digital marketing:","bold":true},{"text":" the use of the "},{"text":"internet and digital channels","bold":true},{"text":" (websites, search engines, social media, email and mobile devices) to "},{"text":"promote products and engage customers","bold":true},{"text":" (build customer relationships)."}]},{"text":[{"text":"Digital marketing communication:","bold":true},{"text":" marketing messages delivered through digital channels, for example "},{"text":"targeted email campaigns and social media advertising","bold":true},{"text":". It is distinguished by "},{"text":"interactivity, measurability and adaptability","bold":true},{"text":" to audience needs, and it lets businesses "},{"text":"monitor and analyse campaign performance with real-time metrics","bold":true},{"text":"."}]},{"text":[{"text":"The 3 media types (POE):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Paid media:","bold":true},{"text":" advertising space the firm "},{"text":"buys","bold":true},{"text":" on other people's websites and platforms (search ads, display banners, sponsored social posts, influencer fees)."}]},{"text":[{"text":"Owned media:","bold":true},{"text":" channels the firm "},{"text":"controls itself","bold":true},{"text":": its website, blog, app, email list, official social media pages."}]},{"text":[{"text":"Earned media:","bold":true},{"text":" exposure the brand receives because of "},{"text":"what others say","bold":true},{"text":" about it: customer reviews, social shares, mentions and free press coverage."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Key metrics (formulas):","bold":true}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Click-through rate (CTR) = clicks / impressions x 100"}]},{"text":[{"text":"Conversion rate = conversions / clicks (or visitors) x 100"}]},{"text":[{"text":"Cost per click (CPC) = total spend / clicks"}]},{"text":[{"text":"Cost per conversion = total spend / conversions"}]},{"text":[{"text":"Cost per thousand impressions (CPM) = total spend / impressions x 1,000"}]}]}]},{"text":[{"text":"Impression:","bold":true},{"text":" one showing of an ad. "},{"text":"CTR:","bold":true},{"text":" the proportion of people who saw an ad and then clicked it. "},{"text":"Conversion:","bold":true},{"text":" a visitor completes a "},{"text":"desired action","bold":true},{"text":", such as making a purchase or signing up."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Traditional TV, radio, print and billboards are not digital marketing communication. Digital communication is not one-way, fixed or hard to measure."}]},{"text":[{"text":"POE examples:","bold":true},{"text":" Jumia's own website and its official Instagram page are "},{"text":"owned","bold":true},{"text":"; Jumia buying banner space on a news site is "},{"text":"paid","bold":true},{"text":"; a shopper's glowing review shared widely is "},{"text":"earned","bold":true},{"text":". Billboards rented from an outdoor firm are bought space, but they are offline, so they never answer \"owned media\"."}]},{"text":[{"text":"Earned media links to PR and word of mouth: it is unpaid and the firm does not control it."}]},{"text":[{"text":"Worked example:","bold":true},{"text":" a Lagos bakery's ad is shown 40,000 times, gets 800 clicks at ₦40 per click, and 24 people order."}],"blocks":[{"type":"list","ordered":false,"items":[{"text":[{"text":"CT$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 36, $study_guide$R = 800 / 40,000 x 100 = "},{"text":"2%","bold":true}]},{"text":[{"text":"Spend = 800 x ₦40 = "},{"text":"₦32,000","bold":true}]},{"text":[{"text":"Conversion rate = 24 / 800 x 100 = "},{"text":"3%","bold":true}]},{"text":[{"text":"Cost per conversion = ₦32,000 / 24 = ₦1,333.33 (rounded to 2 decimal places)"}]}]}]},{"text":[{"text":"A visitor who leaves without doing anything is not a conversion; changing a logo is not a conversion."}]}]}]},{"number":"8.4","title":"Crafting digital marketing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Crafting digital marketing:","bold":true},{"text":" developing "},{"text":"strategic content suited to how audiences behave online","bold":true},{"text":". It requires "},{"text":"deep insight into online consumer behaviour and how each platform works","bold":true},{"text":"."}]},{"text":[{"text":"Steps in crafting a digital marketing strategy:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Set clear objectives","bold":true},{"text":" (SMART: awareness, traffic, leads, sales)."}]},{"text":[{"text":"Define the target audience","bold":true},{"text":" and build "},{"text":"buyer personas","bold":true},{"text":"."}]},{"text":[{"text":"Choose the right digital channels and content","bold":true},{"text":" for that audience."}]},{"text":[{"text":"Create and publish","bold":true},{"text":" the content and campaigns (with a budget and schedule)."}]},{"text":[{"text":"Measure with analytics and improve","bold":true},{"text":" the campaign based on the results."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Buyer persona:","bold":true},{"text":" a "},{"text":"detailed profile representing a typical member of the target audience","bold":true},{"text":" (age, location, job, interests, online habits, problems)."}]},{"text":[{"text":"Analytics after launch:","bold":true},{"text":" used to "},{"text":"measure performance and improve","bold":true},{"text":" the campaign."}]},{"text":[{"text":"Mobile-friendly (responsive) website:","bold":true},{"text":" essential because "},{"text":"many users access the internet mainly through their phones","bold":true},{"text":"."}]},{"text":[{"text":"Inbound vs outbound:","bold":true}]}]},{"type":"table","header":[[{"text":"Inbound marketing"}],[{"text":"Outbound marketing"}]],"rows":[[[{"text":"Attracts","bold":true},{"text":" customers to the firm through useful content, search and social media"}],[{"text":"Pushes","bold":true},{"text":" messages at people through cold calls and interruptive adverts"}]],[[{"text":"Customer finds the firm"}],[{"text":"Firm interrupts the customer"}]]]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NOT a step:","bold":true},{"text":" \"skipping measurement because digital results cannot be tracked\". Digital results can be tracked, so measurement is always a step."}]},{"text":[{"text":"Bad crafting: copying a print advert unchanged onto every website, using exactly the same message on every platform, ignoring which platforms the audience uses, focusing only on the cheapest channel, suppressing feedback, or avoiding measurement. Each platform has its own format: short videos on TikTok, professional posts on LinkedIn, pictures on Instagram."}]},{"text":[{"text":"Persona example:","bold":true},{"text":" \"Tola, 20, UNILAG student, lives in Akoka, spends most of her data on TikTok and Instagram, buys affordable skincare, pays by transfer.\" A brand plans content for Tola. A persona is not a product list, website owner or password."}]},{"text":[{"text":"In Nigeria, most people go online by phone, so a site that does not work well on a mobile phone loses customers."}]}]}]},{"number":"8.5","title":"Types of digital marketing","mustKnow":[{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Search engine optimisation (SEO):","bold":true},{"text":" improving a website so it "},{"text":"ranks higher in unpaid (organic) search results","bold":true},{"text":"."}]},{"text":[{"text":"Search engine marketing (SEM) / pay-per-click (PPC):","bold":true},{"text":" "},{"text":"paid search ads","bold":true},{"text":"; in PPC the advertiser "},{"text":"pays a fee each time someone clicks","bold":true},{"text":" its advert. Gives "},{"text":"immediate website traffic","bold":true},{"text":"."}]},{"text":[{"text":"Content marketing:","bold":true},{"text":" creating and sharing "},{"text":"free, useful content","bold":true},{"text":" (blogs, videos, guides) to attract an audience without pushing a direct sale each time."}]},{"text":[{"text":"Social media marketing:","bold":true},{"text":" using social platforms to "},{"text":"share content, engage users and build brand communities","bold":true},{"text":"."}]},{"text":[{"text":"Email marketing:","bold":true},{"text":" sending commercial messages such as "},{"text":"offers and newsletters","bold":true},{"text":" to people on an email list."}]},{"text":[{"text":"Affiliate marketing:","bold":true},{"text":" paying partners "},{"text":"commission for each sale or lead","bold":true},{"text":" they bring through "},{"text":"referral links","bold":true},{"text":"."}]},{"text":[{"text":"Influencer marketing:","bold":true},{"text":" partnering with individuals who have a "},{"text":"large, engaged online following","bold":true},{"text":" to promote a brand."}]},{"text":[{"text":"Mobile marketing:","bold":true},{"text":" reaching consumers on their "},{"text":"phones","bold":true},{"text":" through "},{"text":"SMS, apps, mobile sites and location-based offers","bold":true},{"text":"."}]},{"text":[{"text":"Video marketing:","bold":true},{"text":" using online video (YouTube, TikTok, Reels) to promote and explain products."}]},{"text":[{"text":"Display advertising:","bold":true},{"text":" "},{"text":"visual adverts such as banners","bold":true},{"text":" shown on websites and apps; includes "},{"text":"retargeting (remarketing)","bold":true},{"text":", which shows ads t$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 37, $study_guide$o people who visited a site but did not buy."}]},{"text":[{"text":"Viral marketing:","bold":true},{"text":" designing a message so that "},{"text":"people pass it on to others","bold":true},{"text":", spreading it rapidly like a virus."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Keywords:","bold":true},{"text":" the words and phrases people "},{"text":"type into a search engine","bold":true},{"text":" to find something."}]},{"text":[{"text":"Permission-based (opt-in) email:","bold":true},{"text":" send only to people who have "},{"text":"agreed (opted in)","bold":true},{"text":" to receive messages. "},{"text":"Spam:","bold":true},{"text":" unsolicited bulk commercial email sent to people who did not ask for it."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"SEO vs paid search:","bold":true},{"text":" SEO targets "},{"text":"unpaid organic listings","bold":true},{"text":"; paid search "},{"text":"buys advertising positions","bold":true},{"text":". A Port Harcourt hotel paying to appear at the top for \"hotels in Port Harcourt\" and charged only per click is "},{"text":"PPC search advertising","bold":true},{"text":", not SEO."}]},{"text":[{"text":"Affiliate vs influencer:","bold":true},{"text":" affiliate marketing pays partners "},{"text":"mainly according to sales or leads actually generated","bold":true},{"text":". A Nigerian e-commerce site giving bloggers a unique link and paying 5% commission only on purchases through that link is "},{"text":"affiliate","bold":true},{"text":". Influencer marketing often pays for exposure (a flat fee) whether or not sales follow: a drinks company paying a popular Nigerian comedy skit-maker with millions of Instagram followers to feature its drink is "},{"text":"influencer marketing","bold":true},{"text":"."}]},{"text":[{"text":"Content:","bold":true},{"text":" a Lagos skincare brand posting free weekly videos and blogs on caring for skin in hot, humid weather, without a hard sell, is "},{"text":"content marketing","bold":true},{"text":"."}]},{"text":[{"text":"Email:","bold":true},{"text":" an online bookshop's monthly email of new arrivals and discount codes to customers who signed up is "},{"text":"email marketing","bold":true},{"text":". Good practice: never hide the unsubscribe option, never buy lists of strangers' addresses, never flood inboxes."}]},{"text":[{"text":"Mobile:","bold":true},{"text":" an operator such as MTN or Airtel texting subscribers discounted data bundles bought by dialling a short code is "},{"text":"mobile (SMS) marketing","bold":true},{"text":"."}]},{"text":[{"text":"Retargeting:","bold":true},{"text":" a shopper views sneakers on a Nigerian online store, does not buy, and ads for the same sneakers follow her on other websites."}]},{"text":[{"text":"Viral:","bold":true},{"text":" the Hotmail signature line is the classic case. Text messages to phones are mobile, not display; supermarket shelf arrangement is merchandising, not display advertising."}]}]}]},{"number":"8.6","title":"Importance and challenges of digital marketing","mustKnow":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Importance (advantages) of digital marketing:","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Reaches "},{"text":"large and even global audiences efficiently and at relatively low cost","bold":true},{"text":"."}]},{"text":[{"text":"Precise targeting","bold":true},{"text":" of specific audiences, so even "},{"text":"small businesses","bold":true},{"text":" can compete on a small budget."}]},{"text":[{"text":"Measurable in real time","bold":true},{"text":" (CTR, conversions, cost per sale)."}]},{"text":[{"text":"Instant customer engagement","bold":true},{"text":" and quick responses (two-way)."}]},{"text":[{"text":"Personalisation","bold":true},{"text":", which improves customer experiences and engagement."}]},{"text":[{"text":"Flexibility:","bold":true},{"text":" campaigns can be changed quickly while running."}]},{"text":[{"text":"Builds brand awareness and relationships 24 hours a day."}]}]},{"type":"list","ordered":false,"items":[{"text":[{"text":"Challenges (limitations):","bold":true}]}]},{"type":"list","ordered":true,"start":1,"items":[{"text":[{"text":"Data privacy and security","bold":true},{"text":" concerns."}]},{"text":[{"text":"Negative messages spread very quickly and widely","bold":true},{"text":" online."}]},{"text":[{"text":"Rapid change","bold":true},{"text":" in technology, platforms and search or social "},{"text":"algorithms","bold":true},{"text":", so marketers must keep learning."}]},{"text":[{"text":"Does "},{"text":"not reach people without internet or mobile access","bold":true},{"text":"."}]},{"text":[{"text":"Clutter","bold":true},{"text":", ad blocking and skipping."}]},{"text":[{"text":"Fraud, fake reviews and high competition for attention."}]}]}],"explainMore":[{"type":"list","ordered":false,"items":[{"text":[{"text":"NOT an advantage:","bold":true},{"text":" \"messages reach people who have no internet or mobile access\". That is false; it is a limitation."}]},{"text":[{"text":"Digital marketing does not guarantee every customer will buy, does not remove competition, does not remove the need for a marketing plan or for understanding customers, and does not work only for big firms."}]},{"text":[{"text":"Negative spread:","bold":true},{"text":" an Abuja restaurant finds one angry customer's post about poor service shared thousands of times in a day. Firms must monitor and respond quickly and politely."}]},{"text":[{"text":"Data privacy matters in Nigeria too: firms holding customers' phone numbers and emails must protect them and use them only with consent."}]}]}]}],"recap":[{"type":"list","ordered":false,"items":[{"text":[{"text":"Offline = TV, radio, newspapers, magazines, outdoor, cinema; online = search, display, social, email, mobile, websites."}]},{"text":[{"text":"TV: sight, sound, motion, mass. Radio: low cos$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 38, $study_guide$t, local, audio only. Newspapers: timely, local, short life. Magazines: long life, colour, selective. Outdoor: repeated exposure, brief message."}]},{"text":[{"text":"Online media: interactive, targeted, measurable; cannot reach people without internet."}]},{"text":[{"text":"Combine both (QR code on a billboard) in an integrated campaign."}]},{"text":[{"text":"Paid = bought; owned = firm controls; earned = reviews, shares, free press."}]},{"text":[{"text":"CTR = clicks / impressions x 100; conversion = desired action completed."}]},{"text":[{"text":"Crafting: objectives, audience and personas, channels and content, publish, measure with analytics."}]},{"text":[{"text":"SEO is organic; PPC pays per click; affiliate pays per sale; influencer uses followers; opt-in email, not spam."}]},{"text":[{"text":"Importance: low-cost global reach, targeting, real-time measurement, engagement, personalisation. Challenges: privacy, fast negative spread, changing algorithms."}]}]}],"theory":{"itemId":"5480d808-f6e5-5e9c-84d9-5734705f269c","question":[{"type":"paragraph","text":[{"text":"A Yaba phone-accessories shop runs a pay-per-click campaign. Its ad gets 60,000 impressions and 900 clicks at ₦60 per click, and 27 shoppers buy, each spending ₦6,000. Find the CTR, total spend, conversion rate, cost per sale, CPM and the revenue earned."}]}]},"practice":[{"topic":"Online and Offline Media and Digital Marketing","named":false}]}}],"theory":[{"kind":"theory_question","itemId":"b1e247aa-afc5-562a-bdb7-676783d6166e","sourceKey":"guide-theory:1","position":1,"payload":{"prompt":"State the five conditions for an exchange to take place and explain which of them shows why marketing communication is needed."},"answer":{"kind":"model_answer","itemId":"7a40c8bc-c8fa-5d11-b356-528cdcf8bfde","sourceKey":"guide-answer:1","payload":{"body":"(1) at least two parties; (2) each has something that might be of value to the other; (3) each can communicate and deliver what it offers; (4) each is free to accept or reject the offer; (5) each trusts/respects the other enough to take the exchange seriously. Condition 3 shows the need for marketing communication: without a way to tell buyers what is on offer, no exchange (and so no transaction) can happen. MarCom fills this gap by generating awareness, fostering trust and driving purchase intent."}}},{"kind":"theory_question","itemId":"375505a3-1862-516c-b36b-c37951d4c922","sourceKey":"guide-theory:2","position":2,"payload":{"prompt":"A Lagos snack maker had sales of ₦250 million last year and forecasts ₦300 million this year. It budgets 3% of sales for promotion. (a) Find the budget using past sales and using forecast sales. (b) If rivals together spend ₦36 million, what is the firm's share of voice using the forecast-based budget?"},"answer":{"kind":"model_answer","itemId":"d9d24ae4-2371-5fa4-9822-1c1def9c5b17","sourceKey":"guide-answer:2","payload":{"body":"• (a) Past sales: 0.03 x ₦250,000,000 = ₦7,500,000. Forecast sales: 0.03 x ₦300,000,000 = ₦9,000,000.\n• (b) Total category spend = ₦9m + ₦36m = ₦45m. SOV = 9 / 45 x 100 = 20%."}}},{"kind":"theory_question","itemId":"922c23bb-5130-582c-894f-f17688cfd613","sourceKey":"guide-theory:3","position":3,"payload":{"prompt":"A drinks firm compares two options. A radio campaign costs ₦2,400,000 and reaches 1,600,000 listeners. A sales team costs ₦1,800,000 and makes 300 calls on supermarket buyers. Calculate the cost per contact of each, the radio CPM, and state which tool suits building awareness and which suits closing orders."},"answer":{"kind":"model_answer","itemId":"9643ba11-20f5-5d0e-8d2f-579d7c03846d","sourceKey":"guide-answer:3","payload":{"body":"• Radio cost per contact = ₦2,400,000 ÷ 1,600,000 = ₦1.50 per listener.\n• Radio CPM = ₦1.50 × 1,000 = ₦1,500 per thousand listeners.\n• Sales team cost per contact = ₦1,800,000 ÷ 300 = ₦6,000 per call.\n• Each sales call costs ₦6,000 ÷ ₦1.50 = 4,000 times a radio contact.\n• Radio (advertising) suits awareness: wide reach at low cost per contact. The sales team (personal selling) suits closing orders with supermarket buyers: two-way, tailored, able to negotiate. Selling to supermarkets so they stock the drink is also a push approach."}}},{"kind":"theory_question","itemId":"fae777aa-140e-58e7-bab6-c1817b21c519","sourceKey":"guide-theory:4","position":4,"payload":{"prompt":"Name the three categories of source characteristics and state the process through which each influences the receiver, with one example each."},"answer":{"kind":"model_answer","itemId":"8122bdb5-3e5e-5946-b9b6-e2c429b3e764","sourceKey":"guide-answer:4","payload":{"body":"1. Credibility (expertise and trustworthiness) works through internalisation: the receiver accepts the view because they believe it is accurate. Example: a dentist recommending a toothpaste.\n2. Attractiveness (similarity, familiarity, likability) works through identification: the receiver wants to relate to or be like the source. Example: an ordinary Lagos mother praising a detergent.\n3. Power (ability to reward or punish) works through compliance: the receiver goes along to gain a reward or avoid punishment. Example: a manager instructing staff; rarely usable in mass advertising because advertisers cannot reward, punish or monitor consumers."}}},{"kind":"theory_question","itemId":"c9a5202d-1616-506e-a213-b4b275bba75d","sourceKey":"guide-theory:5","position":5,"payload":{"prompt":"Using a Nigerian example, explain the elements of the communication process and show two points at which noise can occur."},"answer":{"kind":"model_answer","itemId":"6e658aae-c226-5693-a281-87d21f4ee5f8","sourceKey":"guide-answer:5","payload":{"body":"1. Sender: MTN wants subscribers to buy a new data bundle.\n2. Encoding: its team turns the idea into an SMS: \"Get 1.5GB for ₦1,000. Reply YES.\"\n3. Message: the words and figures in the SMS.\n4. Channel: the SMS network.\n5. Receiver and decoding: a subscriber reads the SMS and understands the offer.\n6. Response and f$study_guide$);
insert into private.study_guide_chunks (guide, ordinal, chunk) values ('study_guide_lag_bua123', 39, $study_guide$eedback: she decides to buy (response) and replies \"YES\" (feedback, because it returns to MTN).\n7. Noise, point 1 (channel): network failure delays or garbles the SMS (physical noise).\n8. Noise, point 2 (receiver): she receives dozens of promotional SMSs that day and ignores this one (information overload), or does not understand an abbreviation used (semantic).\n9. Close by stating that the message works best when the fields of experience of MTN and the subscriber overlap and when feedback is used to refine later messages."}}},{"kind":"theory_question","itemId":"0227e2a3-f51d-5204-8306-be19cdc71765","sourceKey":"guide-theory:6","position":6,"payload":{"prompt":"A brand pays ₦40,000 to boost a TikTok video. It reaches 8,000 people, each seeing it 3 times on average, and gets 360 likes, comments and shares. Find (a) impressions, (b) engagement rate by reach, (c) cost per 1,000 impressions. State whether the boost is paid, owned or earned media."},"answer":{"kind":"model_answer","itemId":"bb2a2722-8f33-532c-b0f9-549f32919a49","sourceKey":"guide-answer:6","payload":{"body":"• (a) Impressions = reach × frequency = 8,000 × 3 = 24,000.\n• (b) Engagement rate = 360 ÷ 8,000 × 100 = 4.5%.\n• (c) CPM = (₦40,000 ÷ 24,000) × 1,000 = ₦1,666.67 (rounded to the nearest kobo).\n• The boost is paid media; any free shares it triggers are earned media."}}},{"kind":"theory_question","itemId":"7823aa23-a370-533f-9be6-b129116c5fc4","sourceKey":"guide-theory:7","position":7,"payload":{"prompt":"Bukola buys bread worth ₦3,500 from a neighbourhood bakery twice a week, every week of the year, and is expected to stay a customer for 4 years. The bakery's profit margin is 25%. Its customer base fell from 16,000 to 15,200 over the year with no new customers counted. Calculate (a) Bukola's CLV in revenue and profit terms and (b) the bakery's churn and retention rates."},"answer":{"kind":"model_answer","itemId":"0cb00211-f452-5f12-9887-e152ea190cb5","sourceKey":"guide-answer:7","payload":{"body":"• (a) Purchases per year = 2 x 52 = 104. Spend per year = ₦3,500 x 104 = ₦364,000. CLV (revenue) = ₦364,000 x 4 = ₦1,456,000. CLV (profit) = ₦1,456,000 x 0.25 = ₦364,000.\n• (b) Customers lost = 16,000 - 15,200 = 800. Churn rate = 800 / 16,000 x 100 = 5%. Retention rate = 100 - 5 = 95%.\n• Interpretation: losing Bukola would cost the bakery ₦364,000 of profit, so communication that keeps her (friendly dialogue, a loyalty card, remembering her order) is worth far more than one sale."}}},{"kind":"theory_question","itemId":"5480d808-f6e5-5e9c-84d9-5734705f269c","sourceKey":"guide-theory:8","position":8,"payload":{"prompt":"A Yaba phone-accessories shop runs a pay-per-click campaign. Its ad gets 60,000 impressions and 900 clicks at ₦60 per click, and 27 shoppers buy, each spending ₦6,000. Find the CTR, total spend, conversion rate, cost per sale, CPM and the revenue earned."},"answer":{"kind":"model_answer","itemId":"260e47ed-d5e1-5d5a-991d-56ea0cef1bbb","sourceKey":"guide-answer:8","payload":{"body":"• CTR = 900 / 60,000 x 100 = 1.5%\n• Total spend = 900 x ₦60 = ₦54,000\n• Conversion rate = 27 / 900 x 100 = 3%\n• Cost per sale = ₦54,000 / 27 = ₦2,000\n• CPM = ₦54,000 / 60,000 x 1,000 = ₦900\n• Revenue = 27 x ₦6,000 = ₦162,000, which is 3 times the ad spend (₦108,000 more than the spend)."}}}]}$study_guide$);
